@Override
public void createSignature(PDSignatureField pdSignatureField, PDPage page, String signerName) throws IOException // PATH: Test should invoke the next Log.info(...) [step in execution path]
{
    PDSignature pdSignature = new PDSignature();
    PDAnnotationWidget widget = pdSignatureField.getWidgets().get(0);
    pdSignatureField.setValue(pdSignature);
    widget.setPage(page);
