/**
 * This will take a PDDocument and write the text of that document to the print writer.
 *
 * @param doc
 * 		The document to get the data from.
 * @param outputStream
 * 		The location to put the text.
 * @throws IOException
 * 		If the doc is in an invalid state.
 */
public void writeText(PDDocument doc, Writer outputStream) throws IOException {
    resetEngine();
    document = doc;
    output = outputStream;
    if (getAddMoreFormatting()) {
        paragraphEnd = lineSeparator;
        pageStart = lineSeparator;
        articleStart = lineSeparator;
        articleEnd = lineSeparator;
    }
    startDocument(document);
    processPages(document.getPages());
    endDocument(document);
}

/**
 * Write the word separator value to the output stream.
 *
 * @throws IOException
 * 		If there is a problem writing out the word separator to the document.
 */
protected void writeWordSeparator() throws IOException {
    output.write(getWordSeparator());
}

