/**
 * Decodes a hex String into a byte array.
 *
 * @param s
 * 		A String with ASCII hex.
 * @return decoded byte array.
 */
public static byte[] decodeHex(String s) {
    ByteArrayOutputStream baos = new ByteArrayOutputStream((s.length() + 1) / 2);
    int i = 0;
    while (i < (s.length() - 1)) {
        if ((s.charAt(i) == '\n') || (s.charAt(i) == '\r')) {
            ++i;
        } else {
            int value = (16 * getHexValue(s.charAt(i))) + getHexValue(s.charAt(i + 1));
            if (value >= 0) {
                baos.write(value);
            } else // PATH: Test should invoke the next Log.error(...) [step in execution path]
            {
                String hexByte = s.substring(i, i + 2);
                LOG.error(("Can't parse " + hexByte) + ", aborting decode");
                break;
            }
            i += 2;
        }
    } 
    return baos.toByteArray();
}

