/**
 * Set the font and font size to draw text with.
 *
 * @param font
 * 		The font to use.
 * @param fontSize
 * 		The font size to draw the text.
 * @throws IOException
 * 		If there is an error writing the font information.
 */
public void setFont(PDFont font, float fontSize) throws IOException {
    if (fontStack.isEmpty()) {
        fontStack.add(font);
    } else {
        fontStack.pop();
        fontStack.push(font);
    }
    // keep track of fonts which are configured for subsetting
    if (font.willBeSubset()) {
        if (document != null) {
            document.getFontsToSubset().add(font);
        } else {
            LOG.warn(("Using the subsetted font '" + font.getName()) + "' without a PDDocument context; call subset() before saving");
        }
    } else if ((!font.isEmbedded()) && (!font.isStandard14())) {
        LOG.warn(("attempting to use font '" + font.getName()) + "' that isn't embedded");
    }
    // complex text layout
    if (font instanceof PDType0Font) {
        PDType0Font type0Font = ((PDType0Font) (font));
        GsubData gsubData = type0Font.getGsubData();
        if (gsubData != GsubData.NO_DATA_FOUND) {
            GsubWorker gsubWorker = gsubWorkerFactory.getGsubWorker(type0Font.getCmapLookup(), gsubData);
            gsubWorkers.put(((PDType0Font) (font)), gsubWorker);
        } else // PATH: Test should invoke the next Log.isDebugEnabled(...) [step in execution path]
        if (LOG.isDebugEnabled()) {
            LOG.debug("No GSUB data found in font" + font.getName());
        }
    }
    writeOperand(resources.add(font));
    writeOperand(fontSize);
    writeOperator(OperatorName.SET_FONT_AND_SIZE);
}

