protected void writeParagraphEnd() throws IOException {
    if (!inParagraph) {
        writeParagraphStart();
    }
    output.write(getParagraphEnd());
    inParagraph = false;
}

/**
 * Write something (if defined) at the start of a paragraph.
 *
