protected void writeParagraphStart() throws IOException {
    if (inParagraph) {
        writeParagraphEnd();
        inParagraph = false;
    }
    output.write(getParagraphStart());
    inParagraph = true;
}

/**
 * Write a Java string to the output stream.
 *
 * @param text
