/**
 * Returns the version of PDFBox.
 *
 * @return the version of PDFBox
 */
public static String getVersion() {
    try (InputStream resourceAsStream = Version.class.getResourceAsStream(PDFBOX_VERSION_PROPERTIES);InputStream is = new BufferedInputStream(resourceAsStream)) {
        Properties properties = new Properties();
        properties.load(is);
        return properties.getProperty("pdfbox.version", null);
    } catch (IOException io) {
        LOG.debug("Unable to read version from properties - returning null", io);
        return null;
    }
}

