/**
 * Constructor that will use the provided function to create a stream cache for the storage of the PDF streams.
 *
 * @param streamCacheCreateFunction
 * 		a function to create an instance of a stream cache
 * @param parser
 * 		Parser to be used to parse the document on demand
 */
public (StreamCacheCreateFunction streamCacheCreateFunction, ICOSParser parser) {
    // PATH: Test should invoke the next COSDocument.getStreamCache(...) [step in execution path]
    streamCache = getStreamCache(streamCacheCreateFunction);
    this.parser = parser;
}

private RandomAccessStreamCache getStreamCache(StreamCacheCreateFunction streamCacheCreateFunction) {
    if (streamCacheCreateFunction == null) {
        return null;
    }
    try {
        return streamCacheCreateFunction.create();
    } catch (IOException exception1) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn("An error occurred when creating stream cache. Using memory only cache as fallback.", exception1);
    }
    try {
        return IOUtils.createMemoryOnlyStreamCache().create();
    } catch (IOException exception2) {
        LOG.warn("An error occurred when creating stream cache for fallback.", exception2);
    }
    return null;
}

