/**
 * Populate XRef HashMap with given values.
 * Each entry maps ObjectKeys to byte offsets in the file.
 *
 * @param xrefTableValues
 * 		xref table entries to be added
 */
public void addXRefTable(Map<COSObjectKey, Long> xrefTableValues) {
    xrefTable.putAll(xrefTableValues);
}

/**
 * This will close all storage and delete the tmp files.
 *
 * @throws IOException
 * 		If there is an error close resources.
 */
@Override
public void close() throws IOException {
    if (closed) {
        return;
    }
    // Make sure that:
    // - first Exception is kept
    // - all COSStreams are closed
    // - stream cache is closed
    // - there's a way to see which errors occurred
    IOException firstException = null;
    // close all open I/O streams
    for (COSObject object : objectPool.values()) {
        if (!object.isObjectNull()) {
            COSBase cosObject = object.getObject();
            if (cosObject instanceof COSStream) {
                firstException = IOUtils.closeAndLogException(((COSStream) (cosObject)), LOG, "COSStream", firstException);
            }
        }
    }
    for (COSStream stream : streams) {
        firstException = IOUtils.closeAndLogException(stream, LOG, "COSStream", firstException);
    }
    if (streamCache != null) {
        firstException = IOUtils.closeAndLogException(streamCache, LOG, "Stream Cache", firstException);
    }
    closed = true;
    // rethrow first exception to keep method contract
    if (firstException != null) {
        throw firstException;
    }
}

