/**
 * This will dispatch to the correct method.
 *
 * @param obj
 * 		The object to decrypt.
 * @param objNum
 * 		The object number.
 * @param genNum
 * 		The object generation Number.
 * @throws IOException
 * 		If there is an error getting the stream data.
 */
public void decrypt(COSBase obj, long objNum, long genNum) throws IOException {
    // PDFBOX-4477: only cache strings and streams, this improves speed and memory footprint
    if (obj instanceof COSString) // PATH: Test should invoke the next SecurityHandler.decryptString(...) [step in execution path]
    {
        if (objects.contains(obj)) {
            return;
        }
        objects.add(obj);
        decryptString(((COSString) (obj)), objNum, genNum);
    } else if (obj instanceof COSStream) {
        if (objects.contains(obj)) {
            return;
        }
        objects.add(obj);
        decryptStream(((COSStream) (obj)), objNum, genNum);
    } else if (obj instanceof COSDictionary) {
        decryptDictionary(((COSDictionary) (obj)), objNum, genNum);
    } else if (obj instanceof COSArray) {
        decryptArray(((COSArray) (obj)), objNum, genNum);
    }
}

/**
 * This will decrypt a string.
 *
 * @param string
 * 		the string to decrypt.
 * @param objNum
 * 		The object number.
 * @param genNum
 * 		The object generation number.
