/**
 * This will read a chunk of data.
 *
 * @param data
 * 		The buffer to write data to.
 * @param offset
 * 		The offset into the data stream.
 * @param length
 * 		The number of byte to attempt to read.
 * @return The number of bytes actually read.
 * @throws IOException
 * 		If there is an error reading data from the underlying stream.
 */
@Override
public int read(byte[] data, int offset, int length) throws IOException {
    if (isEOF) {
        return -1;
    }
    int numberOfBytesRead = 0;
    while (numberOfBytesRead < length) {
        int available = bytesDecoded - currentDataIndex;
        if (available > 0) {
            int bytes2Copy = Math.min(length - numberOfBytesRead, available);
            System.arraycopy(decodedData, currentDataIndex, data, numberOfBytesRead + offset, bytes2Copy);
            currentDataIndex += bytes2Copy;
            numberOfBytesRead += bytes2Copy;
        } else if (// PATH: Test should invoke the next FlateFilterDecoderStream.fetch(...) [step in execution path]
        !fetch()) {
            break;
        }
    } 
    return numberOfBytesRead;
}

private boolean fetch() throws IOException {
    currentDataIndex = 0;
    if (isEOF || inflater.finished()) {
        isEOF = true;
        bytesDecoded = 0;
        return false;
    }
    if (inflater.needsInput()) {
        int bytesRead = in.read(buffer);
        if (bytesRead > (-1)) {
            inflater.setInput(buffer, 0, bytesRead);
        } else {
            isEOF = true;
            return false;
        }
    }
    try {
        // overwrite formerly read bytes
        if (bytesDecoded > 0) {
            Arrays.fill(decodedData, 0, bytesDecoded, ((byte) (0)));
        }
        bytesDecoded = inflater.inflate(decodedData);
    } catch (DataFormatException exception) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        isEOF = true;
        // check if some bytes could be read at all
        int countZeros = 0;
        for (int i = 0; i < decodedData.length; i++) {
            if (decodedData[i] == 0) {
                countZeros++;
            } else {
                countZeros = 0;
            }
        }
        bytesDecoded = decodedData.length - countZeros;
        // don't throw an exception, use the already read data or an empty stream
        LOG.warn("FlateFilter: premature end of stream due to a DataFormatException = " + exception.getMessage());
        return bytesDecoded > 0;
    }
    return true;
}

