/**
 * Renders a given page to an AWT Graphics2D instance.
 * <p>
 * Known problems:
 * <ul>
 * <li>rendering of PDF files with transparencies is not supported on Ubuntu, see
 * <a href="https://issues.apache.org/jira/browse/PDFBOX-4581">PDFBOX-4581</a> and
 * <a href="https://bugs.openjdk.java.net/browse/JDK-6689349">JDK-6689349</a>. Rendering will
 * not abort, but the pages will be rendered incorrectly.</li>
 * <li>Clipping the Graphics2D will not work properly, see
 * <a href="https://issues.apache.org/jira/browse/PDFBOX-4583">PDFBOX-4583</a>.</li>
 * </ul>
 * If you encounter these problems, then you should render into an image by using the
 * {@link #renderImage(int) renderImage} methods.
 *
 * @param pageIndex
 * 		the zero-based index of the page to be converted
 * @param graphics
 * 		the Graphics2D on which to draw the page
 * @param scaleX
 * 		the scale to draw the page at for the x-axis, where 1 = 72 DPI
 * @param scaleY
 * 		the scale to draw the page at for the y-axis, where 1 = 72 DPI
 * @param destination
 * 		controlling visibility of optional content groups
 * @throws IOException
 * 		if the PDF cannot be read
 * @throws IllegalStateException
 * 		if the requested index isn't found or doesn't point to a valid
 * 		page dictionary
 * @throws IndexOutOfBoundsException
 * 		if the requested index is higher than the page count
 */
public void renderPageToGraphics(int pageIndex, Graphics2D graphics, float scaleX, float scaleY, RenderDestination destination) throws IOException {
    PDPage page = pageTree.get(pageIndex);
    // TODO need width/height calculations? should these be in PageDrawer?
    PDRectangle cropBox = page.getCropBox();
    transform(graphics, page.getRotation(), cropBox, scaleX, scaleY);
    graphics.clearRect(0, 0, ((int) (cropBox.getWidth())), ((int) (cropBox.getHeight())));
    // the end-user may provide a custom PageDrawer
    RenderingHints actualRenderingHints = (renderingHints == null) ? createDefaultRenderingHints(graphics) : renderingHints;
    PageDrawerParameters parameters = new PageDrawerParameters(this, page, subsamplingAllowed, destination, actualRenderingHints, imageDownscalingOptimizationThreshold);
    // PATH: Test should invoke the next PDFRenderer.createPageDrawer(...) [step in execution path]
    PageDrawer drawer = createPageDrawer(parameters);
    drawer.drawPage(graphics, cropBox);
}

/**
 * Returns a new PageDrawer instance, using the given parameters. May be overridden.
 *
 * @param parameters
 * 		parameters to be used when creating the PageDrawer instance
 * @return a new PageDrawer instance
 * @throws IOException
 * 		id the PageDrawer instance could not be created
 */
protected PageDrawer createPageDrawer(PageDrawerParameters parameters) throws IOException {
    PageDrawer pageDrawer = new PageDrawer(parameters);
    pageDrawer.setAnnotationFilter(annotationFilter);
    return pageDrawer;
}

