/**
 * Private. Creates a new PDType0Font font for embedding.
 *
 * @param document
 * @param ttf
 * @param embedSubset
 * @param closeTTF
 * 		whether to close the ttf parameter after embedding. Must be true when the ttf
 * 		parameter was created in the load() method, false when the ttf parameter was passed to the
 * 		load() method.
 * @param vertical
 * 		whether to enable vertical substitutions.
 * @throws IOException
 */
private (PDDocument document, TrueTypeFont ttf, boolean embedSubset, boolean closeTTF, boolean vertical) throws IOException // PATH: Test should invoke the next PDType0Font.readEncoding(...) [step in execution path]
{
    if (vertical) {
        ttf.enableVerticalSubstitutions();
    }
    gsubData = ttf.getGsubData();
    cmapLookup = ttf.getUnicodeCmapLookup();
    embedder = new PDCIDFontType2Embedder(document, dict, ttf, embedSubset, this, vertical);
    descendantFont = embedder.getCIDFont();
    readEncoding();
    fetchCMapUCS2();
    if (closeTTF) {
        if (embedSubset) {
            this.ttf = ttf;
            document.registerTrueTypeFontForClosing(ttf);
        } else {
            // the TTF is fully loaded and it is safe to close the underlying data source
            ttf.close();
        }
    }
}

/**
 * Reads the font's Encoding entry, which should be a CMap name/stream.
 */
private void readEncoding() throws IOException {
    COSBase encoding = dict.getDictionaryObject(COSName.ENCODING);
    if (encoding instanceof COSName) {
        // predefined CMap
        COSName encodingName = ((COSName) (encoding));
        cMap = CMapManager.getPredefinedCMap(encodingName.getName());
        isCMapPredefined = true;
    } else if (encoding != null) {
        cMap = readCMap(encoding);
        if (cMap == null) {
            throw new IOException("Missing required CMap");
        } else if (!cMap.hasCIDMappings()) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
        {
            LOG.warn("Invalid Encoding CMap in font " + getName());
        }
    }
    // check if the descendant font is CJK
    PDCIDSystemInfo ros = descendantFont.getCIDSystemInfo();
    if (ros != null) {
        String ordering = ros.getOrdering();
        isDescendantCJK = "Adobe".equals(ros.getRegistry()) && ((("GB1".equals(ordering) || "CNS1".equals(ordering)) || "Japan1".equals(ordering)) || "Korea1".equals(ordering));
    }
}

