/**
 * This will export all FDF form data.
 *
 * @return An FDF document used to export the document.
 * @throws IOException
 * 		If there is an error when exporting the document.
 */
public FDFDocument exportFDF() throws IOException {
    FDFDocument fdf = new FDFDocument();
    FDFCatalog catalog = fdf.getCatalog();
    FDFDictionary fdfDict = new FDFDictionary();
    catalog.setFDF(fdfDict);
    List<PDField> fields = getFields();
    List<FDFField> fdfFields = new ArrayList<>(fields.size());
    for (PDField field : fields) {
        // PATH: Test should invoke the next PDNonTerminalField.exportFDF(...) [step in execution path]
        fdfFields.add(field.exportFDF());
    }
    fdfDict.setID(document.getDocument().getDocumentID());
    if (!fdfFields.isEmpty()) {
        fdfDict.setFields(fdfFields);
    }
    return fdf;
}

@Override
FDFField exportFDF() throws IOException {
    FDFField fdfField = new FDFField();
    fdfField.setPartialFieldName(getPartialName());
    fdfField.setValue(getValue());
    // PATH: Test should invoke the next PDNonTerminalField.getChildren(...) [step in execution path]
    List<PDField> children = getChildren();
    List<FDFField> fdfChildren = new ArrayList<>(children.size());
    for (PDField child : children) {
        fdfChildren.add(child.exportFDF());
    }
    fdfField.setKids(fdfChildren);
    return fdfField;
}

/**
 * Returns this field's children. These may be either terminal or non-terminal fields.
 *
 * @return the list of child fields. Be aware that this list is <i>not</i> backed by the
children of the field, so adding or deleting has no effect on the PDF document until you call
{@link #setChildren(java.util.List) setChildren()} with the modified list.
 */
public List<PDField> getChildren() {
    // TODO: why not return a COSArrayList like in PDPage.getAnnotations() ?
    List<PDField> children = new ArrayList<>();
    COSArray kids = getCOSObject().getCOSArray(COSName.KIDS);
    if (kids == null) {
        return children;
    }
    for (int i = 0; i < kids.size(); i++) {
        COSBase kid = kids.getObject(i);
        if (kid instanceof COSDictionary) {
            if (kid.getCOSObject() == this.getCOSObject()) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
            {
                LOG.warn("Child field is same object as parent");
                continue;
            }
            PDField field = PDField.fromDictionary(getAcroForm(), ((COSDictionary) (kid)), this);
            if (field != null) {
                children.add(field);
            }
        }
    }
    return children;
}

