@Override
public DecodeResult decode(InputStream encoded, OutputStream decoded, COSDictionary parameters, int index) throws IOException {
    // PATH: Test should invoke the next DCTFilter.decode(...) [step in execution path]
    return decode(encoded, decoded, parameters, index, DecodeOptions.DEFAULT);
}

@Override
public DecodeResult decode(InputStream encoded, OutputStream decoded, COSDictionary parameters, int index, DecodeOptions options) throws IOException {
    ImageReader reader = findRasterReader("JPEG", "a suitable JAI I/O image filter is not installed");
    try (ImageInputStream iis = ImageIO.createImageInputStream(encoded)) {
        // skip one LF if there
        if (iis.read() != 0xa) {
            iis.seek(0);
        }
        reader.setInput(iis);
        ImageReadParam irp = reader.getDefaultReadParam();
        irp.setSourceSubsampling(options.getSubsamplingX(), options.getSubsamplingY(), options.getSubsamplingOffsetX(), options.getSubsamplingOffsetY());
        irp.setSourceRegion(options.getSourceRegion());
        options.setFilterSubsampled(true);
        Raster raster = readImageRaster(reader, irp);
        // special handling for 4-component images
        if (raster.getNumBands() == 4) {
            // get APP14 marker
            Integer transform;
            try {
                // PATH: Test should invoke the next DCTFilter.getAdobeTransform(...) [step in execution path]
                transform = getAdobeTransform(reader.getImageMetadata(0));
            } catch (IIOException | NegativeArraySizeException e) {
                // we really tried asking nicely, now we're using brute force.
                LOG.debug("Couldn't read usíng getAdobeTransform() - using getAdobeTransformByBruteForce() as fallback", e);
                transform = getAdobeTransformByBruteForce(iis);
            }
            int colorTransform = (transform != null) ? transform : 0;
            // 0 = Unknown (RGB or CMYK), 1 = YCbCr, 2 = YCCK
            // https://exiftool.org/TagNames/JPEG.html#Adobe
            switch (colorTransform) {
                case 0 :
                    // already CMYK
                    break;
                case 1 :
                    LOG.warn("There is no 4 channel YCbCr, using YCCK");
                    // fallthrough
                case 2 :
                    raster = fromYCCKtoCMYK(raster);
                    break;
                default :
                    throw new IllegalArgumentException("Unknown colorTransform");
            }
        } else if (raster.getNumBands() == 3) {
            // BGR to RGB
            raster = fromBGRtoRGB(raster);
        }
        DataBufferByte dataBuffer = ((DataBufferByte) (raster.getDataBuffer()));
        decoded.write(dataBuffer.getData());
    } catch (CMMException ex) {
        // PDFBOX-5732
        throw new IOException(ex);
    } finally {
        reader.dispose();
    }
    return new DecodeResult(parameters);
}

// reads the APP14 Adobe transform tag and returns its value, or 0 if unknown
private Integer getAdobeTransform(IIOMetadata metadata) {
    Element tree = ((Element) (metadata.getAsTree("javax_imageio_jpeg_image_1.0")));
    Element markerSequence = ((Element) (tree.getElementsByTagName("markerSequence").item(0)));
    NodeList app14AdobeNodeList = markerSequence.getElementsByTagName("app14Adobe");
    if (app14AdobeNodeList != null) {
        int app14AdobeNodeListLength = app14AdobeNodeList.getLength();
        if (app14AdobeNodeListLength > 0) {
            if (app14AdobeNodeListLength > 1) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
            {
                LOG.warn("app14Adobe entry appears several times, using the last one");
            }
            Element adobe = ((Element) (app14AdobeNodeList.item(app14AdobeNodeListLength - 1)));
            return Integer.valueOf(adobe.getAttribute("transform"));
        }
    }
    return 0;
}

