 * 		an encoded stream of image data
 * @param cosFilter
 * 		the filter or a COSArray of filters
 * @param width
 * 		the image width
 * @param height
 * 		the image height
 * @param bitsPerComponent
 * 		the bits per component
 * @param initColorSpace
 * 		the color space
 * @throws IOException
 * 		if there is an error creating the XObject.
 */
public PDImageXObject(PDDocument document, InputStream encodedStream, COSBase cosFilter, int width, int height, int bitsPerComponent, PDColorSpace initColorSpace) throws IOException {
    super(createRawStream(document, encodedStream), COSName.IMAGE);
    getCOSObject().setItem(COSName.FILTER, cosFilter);
    resources = null;
    colorSpace = null;
    setBitsPerComponent(bitsPerComponent);
    setWidth(width);
    setHeight(height);
    setColorSpace(initColorSpace);
}

/**
 * Creates an Image XObject with the given stream as its contents and current color spaces. This
 * constructor is for internal PDFBox use and is not for PDF generation. Users who want to
 * create images should look at {@link #createFromFileByExtension(File, PDDocument)}.
 *
 * @param stream
 * 		the XObject stream to read
 * @param resources
 * 		the current resources
 * @throws java.io.IOException
 * 		if there is an error creating the XObject.
 */
public PDImageXObject(PDStream stream, PDResources resources) throws IOException {
    super(stream, COSName.IMAGE);
    this.resources = resources;
    List<COSName> filters = stream.getFilters();
    if ((!filters.isEmpty()) && COSName.JPX_DECODE.equals(filters.get(filters.size() - 1))) {
        hasJPXFilter = true;
    }
}

