    Matrix parameters = // 0
    // 0
    new Matrix(fontSize * horizontalScaling, 0, 0, fontSize, 0, textState.getRise());// 1

    Matrix textMatrix = state.getTextMatrix();
    // read the stream until it is empty
    InputStream in = new ByteArrayInputStream(string);
    while (in.available() > 0) // PATH: Test should invoke the next LegacyPDFStreamEngine.showGlyph(...) [step in execution path]
    {
        // decode a character
        int before = in.available();
        int code = font.readCode(in);
        int codeLength = before - in.available();
        // Word spacing shall be applied to every occurrence of the single-byte character code
        // 32 in a string when using a simple font or a composite font that defines code 32 as
        // a single-byte code.
        float wordSpacing = 0;
        if ((codeLength == 1) && (code == 32)) {
            wordSpacing += textState.getWordSpacing();
