private boolean isOwnerPassword56(byte[] ownerPassword, byte[] user, byte[] owner, int encRevision) throws IOException {
    if (owner.length < 40) {
        // PDFBOX-5104
        throw new IOException("Owner password is too short");
    }
    byte[] truncatedOwnerPassword = truncate127(ownerPassword);
    byte[] oHash = new byte[32];
    byte[] oValidationSalt = new byte[8];
    System.arraycopy(owner, 0, oHash, 0, 32);
    System.arraycopy(owner, 32, oValidationSalt, 0, 8);
    if (encRevision == REVISION_5) {
        return MessageDigest.isEqual(computeSHA256(truncatedOwnerPassword, oValidationSalt, user), oHash);
    } else {
        return MessageDigest.isEqual(computeHash2A(truncatedOwnerPassword, oValidationSalt, user), oHash);
    }
}

