                setAES(true);
                if (encryption.getCOSObject().containsKey(COSName.LENGTH)) {
                    // PDFBOX-5345
                    int newLength = encryption.getLength() / 8;
                    if (newLength < dicLength) {
                        LOG.warn(((("Using " + newLength) + " bytes key length instead of ") + dicLength) + " in AESV3 encryption?!");
                        dicLength = newLength;
                    }
