                LOG.error("This page tree node has already been visited");
                continue;
            } else if (kid.containsKey(COSName.KIDS)) {
                set.add(kid);
            }
            enqueueKids(kid);
        }
    } else if ((node != null) && COSName.PAGE.equals(node.getCOSName(COSName.TYPE))) {
        queue.add(node);
    } else {
        LOG.error("Page skipped due to an invalid or missing type " + (node == null ? "(null)" : node.getCOSName(COSName.TYPE)));
