/**
 * Create a PDImageXObject from an image file. The file format is determined by the file
 * content. The following file types are supported: JPG, JPEG, TIF, TIFF, GIF, BMP and PNG. This
 * is a convenience method that calls {@link JPEGFactory#createFromStream},
 * {@link CCITTFactory#createFromFile} or {@link ImageIO#read} combined with
 * {@link LosslessFactory#createFromImage}. (The later can also be used to create a
 * PDImageXObject from a BufferedImage). Starting with 2.0.18, this call will create an image
 * directly from a PNG file without decoding it (when possible), which is faster. However the
 * result size depends on the compression skill of the software that created the PNG file. If
 * file size or bandwidth are important to you or to your clients, then create your PNG files
 * with a tool that has implemented the
 * <a href="https://blog.codinghorror.com/zopfli-optimization-literally-free-bandwidth/">Zopfli
 * algorithm</a>, or use the two-step process mentioned above.
 *
 * @param file
 * 		the image file.
 * @param doc
 * 		the document that shall use this PDImageXObject.
 * @return a PDImageXObject.
 * @throws IOException
 * 		if there is an error when reading the file or creating the
 * 		PDImageXObject.
 * @throws IllegalArgumentException
 * 		if the image type is not supported.
 */
public static PDImageXObject createFromFileByContent(File file, PDDocument doc) throws IOException {
    FileType fileType = null;
    try (BufferedInputStream bufferedInputStream = new BufferedInputStream(new FileInputStream(file))) {
        fileType = FileTypeDetector.detectFileType(bufferedInputStream);
    } catch (IOException e) {
        throw new IOException("Could not determine file type: " + file.getName(), e);
    }
    if (fileType == null) {
        throw new IllegalArgumentException("Image type not supported: " + file.getName());
    }
    if (fileType == FileType.JPEG) {
        try (FileInputStream fis = new FileInputStream(file)) {
            // PATH: Test should invoke the next JPEGFactory.createFromStream(...) [step in execution path]
            return JPEGFactory.createFromStream(doc, fis);
        }
    }
    if (fileType == FileType.TIFF) {
        try {
            return CCITTFactory.createFromFile(doc, file);
        } catch (IOException ex) {
            LOG.debug("Reading as TIFF failed, setting fileType to PNG", ex);
            // Plan B: try reading with ImageIO
            // common exception:
            // First image in tiff is not CCITT T4 or T6 compressed
            fileType = FileType.PNG;
        }
    }
    if (((fileType == FileType.BMP) || (fileType == FileType.GIF)) || (fileType == FileType.PNG)) {
        BufferedImage bim = ImageIO.read(file);
        return LosslessFactory.createFromImage(doc, bim);
    }
    throw new IllegalArgumentException((("Image type " + fileType) + " not supported: ") + file.getName());
}

/**
 * Creates a new JPEG Image XObject from a byte array containing JPEG data.
 *
 * @param document
 * 		the document where the image will be created
 * @param byteArray
 * 		bytes of JPEG image
 * @return a new Image XObject
 * @throws IOException
 * 		if the input stream cannot be read
 */
public static PDImageXObject createFromByteArray(PDDocument document, byte[] byteArray) throws IOException {
    // copy stream
    ByteArrayInputStream byteStream = new ByteArrayInputStream(byteArray);
    // PATH: Test should invoke the next JPEGFactory.retrieveDimensions(...) [step in execution path]
    Dimensions meta = retrieveDimensions(byteStream);
    PDColorSpace colorSpace;
    switch (meta.numComponents) {
        case 1 :
            colorSpace = PDDeviceGray.INSTANCE;
            break;
        case 3 :
            colorSpace = PDDeviceRGB.INSTANCE;
            break;
        case 4 :
            colorSpace = PDDeviceCMYK.INSTANCE;
            break;
        default :
            throw new UnsupportedOperationException("number of data elements not supported: " + meta.numComponents);
    }
    // create PDImageXObject from stream
    PDImageXObject pdImage = new PDImageXObject(document, byteStream, COSName.DCT_DECODE, meta.width, meta.height, 8, colorSpace);
    if (colorSpace instanceof PDDeviceCMYK) {
        COSArray decode = new COSArray();
        decode.add(COSInteger.ONE);
        decode.add(COSInteger.ZERO);
        decode.add(COSInteger.ONE);
        decode.add(COSInteger.ZERO);
        decode.add(COSInteger.ONE);
        decode.add(COSInteger.ZERO);
        decode.add(COSInteger.ONE);
        decode.add(COSInteger.ZERO);
        pdImage.setDecode(decode);
    }
    return pdImage;
}

private static Dimensions retrieveDimensions(ByteArrayInputStream stream) throws IOException {
    ImageReader reader = Filter.findRasterReader("JPEG", "a suitable JAI I/O image filter is not installed");
    try (ImageInputStream iis = ImageIO.createImageInputStream(stream)) {
        reader.setInput(iis);
        Dimensions meta = new Dimensions();
        meta.width = reader.getWidth(0);
        meta.height = reader.getHeight(0);
        // PDFBOX-4691: get from image metadata (faster because no decoding)
        try // PATH: Test should invoke the next Log.info(...) [step in execution path]
        {
            meta.numComponents = getNumComponentsFromImageMetadata(reader);
            if (meta.numComponents != 0) {
                return meta;
            }
            LOG.info("No image metadata, will decode image and use raster size");
        } catch (IOException ex) {
            LOG.warn("Error reading image metadata, will decode image and use raster size");
        }
        // Old method: get from raster (slower)
        ImageIO.setUseCache(false);
        Raster raster = reader.readRaster(0, null);
        meta.numComponents = raster.getNumDataElements();
        return meta;
    } finally {
        stream.reset();
        reader.dispose();
    }
}

