/**
 * visitor pattern double dispatch method.
 *
 * @param visitor
 * 		The object to notify when visiting this object.
 * @throws IOException
 * 		If an error occurs while visiting this object.
 */
@Override
public void accept(ICOSVisitor visitor) throws IOException // PATH: Test should invoke the next COSWriter.visitFromDocument(...) [step in execution path]
{
    visitor.visitFromDocument(this);
}

@Override
public void visitFromDocument(COSDocument doc) throws IOException {
    if (!incrementalUpdate) // PATH: Test should invoke the next COSWriter.doWriteHeader(...) [step in execution path]
    {
        doWriteHeader(doc);
    } else {
        // Sometimes the original file will be missing a newline at the end
        // In order to avoid having %%EOF the first object on the same line
        // as the %%EOF, we put a newline here. If there's already one at
        // the end of the file, an extra one won't hurt. PDFBOX-1051
        getStandardOutput().writeCRLF();
    }
    if (isCompress()) {
        doWriteBodyCompressed(doc);
    } else {
        doWriteBody(doc);
    }
    if (incrementalUpdate || doc.isXRefStream()) {
        doWriteXRefInc(doc);
    } else {
        doWriteXRefTable();
        doWriteTrailer(doc);
    }
    // write endof
    getStandardOutput().write(STARTXREF);
    getStandardOutput().writeEOL();
    getStandardOutput().write(String.valueOf(getStartxref()).getBytes(StandardCharsets.ISO_8859_1));
    getStandardOutput().writeEOL();
    getStandardOutput().write(EOF);
    getStandardOutput().writeEOL();
    if (incrementalUpdate) {
        if ((signatureOffset == 0) || (byteRangeOffset == 0)) {
            doWriteIncrement();
        } else {
            doWriteSignature();
        }
    }
}

/**
 * This will write the header to the PDF document.
 *
 * @param doc
 * 		The document to get the data from.
 * @throws IOException
 * 		If there is an error writing to the stream.
 */
protected void doWriteHeader(COSDocument doc) throws IOException {
    if (isCompress()) {
        pdDocument.setVersion(Math.max(pdDocument.getVersion(), COSWriterCompressionPool.MINIMUM_SUPPORTED_VERSION));
        doc.setVersion(Math.max(doc.getVersion(), COSWriterCompressionPool.MINIMUM_SUPPORTED_VERSION));
    }
    String headerString;
    if (fdfDocument != null) {
        headerString = "%FDF-" + doc.getVersion();
    } else {
        headerString = "%PDF-" + doc.getVersion();
    }
    getStandardOutput().write(headerString.getBytes(StandardCharsets.ISO_8859_1));
    getStandardOutput().writeEOL();
    getStandardOutput().write(COMMENT);
    getStandardOutput().write(GARBAGE);
    getStandardOutput().writeEOL();
}

