/**
 * Returns the page labels descriptor of the document.
 *
 * @return the page labels descriptor of the document.
 * @throws IOException
 * 		If there is a problem retrieving the page labels.
 */
public PDPageLabels getPageLabels() throws IOException {
    COSDictionary dict = root.getCOSDictionary(COSName.PAGE_LABELS);
    return dict == null ? null : new PDPageLabels(document, dict);
}

/**
 * Creates an page label dictionary for a document using the information in
 * the given COS dictionary.
 *
 * <p>
 * Note that the page label dictionary won't be automatically added to the
 * document; you will still need to do it manually (see
 * {@link org.apache.pdfbox.pdmodel.PDDocumentCatalog#setPageLabels(PDPageLabels)}.
 * </p>
 *
 * @param document
 * 		The document the page label dictionary is created for.
 * @param dict
 * 		an existing page label dictionary
 * @see org.apache.pdfbox.pdmodel.PDDocumentCatalog#setPageLabels(PDPageLabels)
 * @throws IOException
 * 		If something goes wrong during the number tree conversion.
 */
public (PDDocument document, COSDictionary dict) throws IOException // PATH: Test should invoke the next PDPageLabels.findLabels(...) [step in execution path]
{
    this(document);
    if (dict == null) {
        return;
    }
    PDNumberTreeNode root = new PDNumberTreeNode(dict, PDPageLabelRange.class);
    findLabels(root);
}

private void findLabels(PDNumberTreeNode node) throws IOException {
    // PATH: Test should invoke the next PDNumberTreeNode.getKids(...) [step in execution path]
    List<PDNumberTreeNode> kids = node.getKids();
    if (kids != null) {
        for (PDNumberTreeNode kid : kids) {
            findLabels(kid);
        }
    } else {
        Map<Integer, COSObjectable> numbers = node.getNumbers();
        if (numbers != null) {
            numbers.forEach((key, pageLabelRange) -> {
                if (key >= 0) {
                    labels.put(key, ((PDPageLabelRange) (pageLabelRange)));
                }
            });
        }
    }
}

/**
 * Return the children of this node.  This list will contain PDNumberTreeNode objects.
 *
 * @return The list of children or null if there are no children.
 */
public List<PDNumberTreeNode> getKids() {
    List<PDNumberTreeNode> retval = null;
    COSArray kids = node.getCOSArray(COSName.KIDS);
    if (kids != null) {
        List<PDNumberTreeNode> pdObjects = new ArrayList<>(kids.size());
        for (int i = 0; i < kids.size(); i++) {
            COSBase base = kids.getObject(i);
            PDNumberTreeNode childNode;
            if (base instanceof COSDictionary) {
                childNode = createChildNode(((COSDictionary) (base)));
            } else // PATH: Test should invoke the next Log.warn(...) [step in execution path]
            {
                LOG.warn("Bad child node at position " + i);
                childNode = new PDNumberTreeNode(valueType);
            }
            pdObjects.add(childNode);
        }
        retval = new COSArrayList<>(pdObjects, kids);
    }
    return retval;
}

