@Override
public void process(Operator operator, List<COSBase> operands) throws IOException {
    if ((operator.getImageData() == null) || (operator.getImageData().length == 0)) {
        return;
    }
    PDFGraphicsStreamEngine context = getGraphicsContext();
    PDImage image = new PDInlineImage(operator.getImageParameters(), operator.getImageData(), context.getResources());
    // maybe something went wrong when decoding the image data
    if (image.isEmpty()) {
        return;
    }
    if ((!image.isStencil()) && (!context.isShouldProcessColorOperators())) {
        return;
    }
    context.drawImage(image);
}

/**
 * Creates an inline image from the given parameters and data.
 *
 * @param parameters
 * 		the image parameters
 * @param data
 * 		the image data
 * @param resources
 * 		the current resources
 * @throws IOException
 * 		if the stream cannot be decoded
 */
public (COSDictionary parameters, byte[] data, PDResources resources) throws IOException {
    this.parameters = parameters;
    this.resources = resources;
    this.rawData = data;
    DecodeResult decodeResult = null;
    List<String> filters = getFilters();
    if (filters.isEmpty()) {
        this.decodedData = data;
    } else {
        ByteArrayInputStream in = new ByteArrayInputStream(data);
        ByteArrayOutputStream out = new ByteArrayOutputStream(data.length);
        byte[] ba = null;
        for (int i = 0; i < filters.size(); i++) {
            // TODO handling of abbreviated names belongs here, rather than in other classes
            out.reset();
            Filter filter = FilterFactory.INSTANCE.getFilter(filters.get(i));
            // PATH: Test should invoke the next CCITTFaxFilter.decode(...) [step in execution path]
            decodeResult = filter.decode(in, out, parameters, i);
            ba = out.toByteArray();
            in = new ByteArrayInputStream(ba);
        }
        this.decodedData = ba;
    }
    // repair parameters
    if (decodeResult != null) {
        parameters.addAll(decodeResult.getParameters());
    }
}

@Override
public DecodeResult decode(InputStream encoded, OutputStream decoded, COSDictionary parameters, int index) throws IOException {
    // get decode parameters
    // PATH: Test should invoke the next Filter.getDecodeParams(...) [step in execution path]
    COSDictionary decodeParms = getDecodeParams(parameters, index);
    // parse dimensions
    int cols = decodeParms.getInt(COSName.COLUMNS, 1728);
    int rows = decodeParms.getInt(COSName.ROWS, 0);
    int height = parameters.getInt(COSName.HEIGHT, COSName.H, 0);
    if ((rows > 0) && (height > 0)) {
        // PDFBOX-771, PDFBOX-3727: rows in DecodeParms sometimes contains an incorrect value
        rows = height;
    } else {
        // at least one of the values has to have a valid value
        rows = Math.max(rows, height);
    }
    // decompress data
    int k = decodeParms.getInt(COSName.K, 0);
    boolean encodedByteAlign = decodeParms.getBoolean(COSName.ENCODED_BYTE_ALIGN, false);
    int arraySize = ((cols + 7) / 8) * rows;
    // TODO possible options??
    byte[] decompressed = new byte[arraySize];
    CCITTFaxDecoderStream s;
    int type;
    long tiffOptions = 0;
    if (k == 0) {
        if (decodeParms.containsKey(COSName.END_OF_LINE)) {
            // PDFBOX-6080: respect the parameter if it exists
            boolean hasEndOfLine = decodeParms.getBoolean(COSName.END_OF_LINE, false);
            type = (hasEndOfLine) ? TIFFExtension.COMPRESSION_CCITT_T4 : TIFFExtension.COMPRESSION_CCITT_MODIFIED_HUFFMAN_RLE;
        } else {
            // In twelvemonkeys, this part is found in CCITTFaxDecoderStream.findCompressionType()
            // needed for 015315-p8-ccitt.pdf, PDFBOX-2123-1bit.pdf, PDFBOX-2778.pdf
            type = TIFFExtension.COMPRESSION_CCITT_T4;// Group 3 1D

            byte[] streamData = new byte[20];
            int bytesRead = encoded.read(streamData);
            if (bytesRead == (-1)) {
                throw new IOException("EOF while reading CCITT header");
            }
            PushbackInputStream pushbackInputStream = new PushbackInputStream(encoded, streamData.length);
            pushbackInputStream.unread(streamData, 0, bytesRead);
            encoded = pushbackInputStream;
            if ((streamData[0] != 0) || (((streamData[1] >> 4) != 1) && (streamData[1] != 1))) {
                // leading EOL (0b000000000001) not found, search further and try RLE if not found
                type = TIFFExtension.COMPRESSION_CCITT_MODIFIED_HUFFMAN_RLE;
                short b = ((short) (((streamData[0] << 8) + (streamData[1] & 0xff)) >> 4));
                for (int i = 12; i < (bytesRead * 8); i++) {
                    b = ((short) ((b << 1) + ((streamData[i / 8] >> (7 - (i % 8))) & 0x1)));
                    if ((b & 0xfff) == 1) {
                        type = TIFFExtension.COMPRESSION_CCITT_T4;
                        break;
                    }
                }
            }
        }
    } else if (k > 0) {
        // Group 3 2D
        type = TIFFExtension.COMPRESSION_CCITT_T4;
        tiffOptions = TIFFExtension.GROUP3OPT_2DENCODING;
    } else {
        // Group 4
        type = TIFFExtension.COMPRESSION_CCITT_T6;
    }
    s = new CCITTFaxDecoderStream(encoded, cols, type, tiffOptions, encodedByteAlign);
    readFromDecoderStream(s, decompressed);
    // invert bitmap
    boolean blackIsOne = decodeParms.getBoolean(COSName.BLACK_IS_1, false);
    if (!blackIsOne) {
        // Inverting the bitmap
        // Note the previous approach with starting from an IndexColorModel didn't work
        // reliably. In some cases the image wouldn't be painted for some reason.
        // So a safe but slower approach was taken.
        invertBitmap(decompressed);
    }
    decoded.write(decompressed);
    return new DecodeResult(parameters);
}

// gets the decode params for a specific filter index, this is used to
// normalise the DecodeParams entry so that it is always a dictionary
protected COSDictionary getDecodeParams(COSDictionary dictionary, int index) {
    COSBase filter = dictionary.getDictionaryObject(COSName.F, COSName.FILTER);
    COSBase obj = dictionary.getDictionaryObject(COSName.DP, COSName.DECODE_PARMS);
    if ((filter instanceof COSName) && (obj instanceof COSDictionary)) {
        // PDFBOX-3932: The PDF specification requires "If there is only one filter and that
        // filter has parameters, DecodeParms shall be set to the filter’s parameter dictionary"
        // but tests show that Adobe means "one filter name object".
        return ((COSDictionary) (obj));
    } else if ((filter instanceof COSArray) && (obj instanceof COSArray)) {
        COSArray array = ((COSArray) (obj));
        if (index < array.size()) {
            COSBase objAtIndex = array.getObject(index);
            if (objAtIndex instanceof COSDictionary) {
                return ((COSDictionary) (objAtIndex));
            }
        }
    } else if ((obj != null) && (!((filter instanceof COSArray) || (obj instanceof COSArray)))) // PATH: Test should invoke the next Log.error(...) [step in execution path]
    {
        LOG.error("Expected DecodeParams to be an Array or Dictionary but found " + obj.getClass().getName());
    }
    return new COSDictionary();
}

