/**
 * Private. Creates a new PDType0Font font for embedding.
 *
 * @param document
 * @param ttf
 * @param embedSubset
 * @param closeTTF
 * 		whether to close the ttf parameter after embedding. Must be true when the ttf
 * 		parameter was created in the load() method, false when the ttf parameter was passed to the
 * 		load() method.
 * @param vertical
 * 		whether to enable vertical substitutions.
 * @throws IOException
 */
private PDType0Font(PDDocument document, TrueTypeFont ttf, boolean embedSubset, boolean closeTTF, boolean vertical) throws IOException {
    if (vertical) {
        ttf.enableVerticalSubstitutions();
    }
    gsubData = ttf.getGsubData();
    cmapLookup = ttf.getUnicodeCmapLookup();
    embedder = new PDCIDFontType2Embedder(document, dict, ttf, embedSubset, this, vertical);
    descendantFont = embedder.getCIDFont();
    readEncoding();
    fetchCMapUCS2();
    if (closeTTF) {
        if (embedSubset) {
            this.ttf = ttf;
            document.registerTrueTypeFontForClosing(ttf);
        } else {
            // the TTF is fully loaded and it is safe to close the underlying data source
            ttf.close();
        }
    }
}

