/**
 * This will take a document and extract the desired pages into a new
 * document.  Both startPage and endPage are included in the extracted
 * document.  If the endPage is greater than the number of pages in the
 * source document, it will go to the end of the document.  If startPage is
 * less than 1, it'll start with page 1.  If startPage is greater than
 * endPage or greater than the number of pages in the source document, a
 * blank document will be returned.
 *
 * @return The extracted document
 * @throws IOException
 * 		If there is an IOError
 */
public PDDocument extract() throws IOException {
    if (((endPage - startPage) + 1) <= 0) {
        return new PDDocument();
    }
    Splitter splitter = new Splitter();
    splitter.setStartPage(Math.max(startPage, 1));
    splitter.setEndPage(Math.min(endPage, sourceDocument.getNumberOfPages()));
    splitter.setSplitAtPage((getEndPage() - getStartPage()) + 1);
    // PATH: Test should invoke the next Splitter.split(...) [step in execution path]
    List<PDDocument> splitted = splitter.split(sourceDocument);
    return splitted.get(0);
}

/**
 * This will take a document and split into several other documents.
 *
 * @param document
 * 		The document to split.
 * @return A list of all the split documents. These should all be saved before closing any
documents, including the source document. Any further operations should be made after
reloading them, to avoid problems due to resource sharing. For the same reason, they should
not be saved with encryption.
 * @throws IOException
 * 		If there is an IOError
 */
public List<PDDocument> split(PDDocument document) throws IOException // PATH: Test should invoke the next Splitter.processPages(...) [step in execution path]
{
    // reset the currentPageNumber for a case if the split method will be used several times
    currentPageNumber = 0;
    destinationDocuments = new ArrayList<>();
    sourceDocument = document;
    pageDictMaps = new ArrayList<>();
    annotDictMaps = new ArrayList<>();
    destToFixMap = new HashMap<>();
    idSet = new HashSet<>();
    roleSet = new HashSet<>();
    processPages();
    for (int i = 0; i < destinationDocuments.size(); ++i) {
        PDDocument destinationDocument = destinationDocuments.get(i);
        pageDictMap = pageDictMaps.get(i);
        annotDictMap = annotDictMaps.get(i);
        cloneStructureTree(destinationDocument);
        fixDestinations(destinationDocument);
    }
    return destinationDocuments;
}

/**
 * Interface method to handle the start of the page processing.
 *
 * @throws IOException
 * 		If an IO error occurs.
 */
private void processPages() throws IOException {
    for (PDPage page : sourceDocument.getPages()) {
        if (((currentPageNumber + 1) >= startPage) && ((currentPageNumber + 1) <= endPage)) // PATH: Test should invoke the next Splitter.processPage(...) [step in execution path]
        {
            processPage(page);
            currentPageNumber++;
        } else if (currentPageNumber > endPage) {
            break;
        } else {
            currentPageNumber++;
        }
    }
}

/**
 * Interface to start processing a new page.
 *
 * @param page
 * 		The page that is about to get processed.
 * @throws IOException
 * 		If there is an error creating the new document.
 */
protected void processPage(PDPage page) throws IOException {
    createNewDocumentIfNecessary();
    PDPage imported = getDestinationDocument().importPage(page);
    if ((page.getResources() != null) && (!page.getCOSObject().containsKey(COSName.RESOURCES))) {
        imported.setResources(page.getResources());
        LOG.info("Resources imported in Splitter");// follow-up to warning in importPage

    }
    if (imported.getCOSObject().containsKey(COSName.B)) {
        imported.getCOSObject().removeItem(COSName.B);
        LOG.warn("/B entry (beads) removed by splitter");
    }
    // remove page links to avoid copying not needed resources
    processAnnotations(imported);
    pageDictMap.put(page.getCOSObject(), imported.getCOSObject());
}

