/**
 * Private. Creates a new PDType0Font font for embedding.
 *
 * @param document
 * @param ttf
 * @param embedSubset
 * @param closeTTF
 * 		whether to close the ttf parameter after embedding. Must be true when the ttf
 * 		parameter was created in the load() method, false when the ttf parameter was passed to the
 * 		load() method.
 * @param vertical
 * 		whether to enable vertical substitutions.
 * @throws IOException
 */
private (PDDocument document, TrueTypeFont ttf, boolean embedSubset, boolean closeTTF, boolean vertical) throws IOException {
    if (vertical) {
        ttf.enableVerticalSubstitutions();
    }
    gsubData = ttf.getGsubData();
    cmapLookup = ttf.getUnicodeCmapLookup();
    embedder = new PDCIDFontType2Embedder(document, dict, ttf, embedSubset, this, vertical);
    // PATH: Test should invoke the next PDCIDFontType2Embedder.getCIDFont(...) [step in execution path]
    descendantFont = embedder.getCIDFont();
    readEncoding();
    fetchCMapUCS2();
    if (closeTTF) {
        if (embedSubset) {
            this.ttf = ttf;
            document.registerTrueTypeFontForClosing(ttf);
        } else {
            // the TTF is fully loaded and it is safe to close the underlying data source
            ttf.close();
        }
    }
}

/**
 * Returns the descendant CIDFont.
 */
public PDCIDFont getCIDFont() throws IOException {
    return new PDCIDFontType2(cidFont, parent, ttf);
}

/**
 * Constructor.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @param parent
 * 		The parent font.
 * @param trueTypeFont
 * 		The true type font used to create the parent font
 * @throws IOException
 * 		if the font could not be read
 */
public (COSDictionary fontDictionary, PDType0Font parent, TrueTypeFont trueTypeFont) throws IOException {
    this(fontDictionary, parent);
    PDFontDescriptor fd = getFontDescriptor();
    if (trueTypeFont != null) {
        ttf = trueTypeFont;
        otf = ((trueTypeFont instanceof OpenTypeFont) && ((OpenTypeFont) (trueTypeFont)).isSupportedOTF()) ? ((OpenTypeFont) (trueTypeFont)) : null;
        isEmbedded = true;
        isDamaged = false;
    } else {
        boolean fontIsDamaged = false;
        TrueTypeFont ttfFont = null;
        PDStream stream = null;
        if (fd != null) {
            stream = fd.getFontFile2();
            if (stream == null) {
                stream = fd.getFontFile3();
            }
            if (stream == null) {
                // Acrobat looks in FontFile too, even though it is not in the spec, see PDFBOX-2599
                stream = fd.getFontFile();
            }
        }
        if (stream != null) {
            try {
                // embedded OTF or TTF
                RandomAccessRead view = stream.getCOSObject().createView();
                TTFParser ttfParser = getParser(view, true);
                ttfFont = ttfParser.parse(view);
                ttfFont.close();
            } catch (IOException e) {
                fontIsDamaged = true;
                LOG.warn("Could not read embedded OTF for font " + getBaseFont(), e);
            }
            if ((ttfFont instanceof OpenTypeFont) && (!((OpenTypeFont) (ttfFont)).isSupportedOTF())) {
                // the OpenType font contains CFF2 outlines which are not supported yet
                ttfFont = null;
                fontIsDamaged = true;
                LOG.warn("Found an OpenType font using CFF2 outlines which are not supported " + fd.getFontName());
            }
        }
        isEmbedded = ttfFont != null;
        isDamaged = fontIsDamaged;
        if (ttfFont == null) {
            // PATH: Test should invoke the next PDCIDFontType2.findFontOrSubstitute(...) [step in execution path]
            ttfFont = findFontOrSubstitute();
        }
        otf = ((ttfFont instanceof OpenTypeFont) && ((OpenTypeFont) (ttfFont)).isSupportedOTF()) ? ((OpenTypeFont) (ttfFont)) : null;
        ttf = ttfFont;
    }
    cmap = ttf.getUnicodeCmapLookup(false);
    cid2gid = readCIDToGIDMap();
}

private TrueTypeFont findFontOrSubstitute() throws IOException {
    TrueTypeFont ttfFont;
    CIDFontMapping mapping = FontMappers.instance().getCIDFont(getBaseFont(), getFontDescriptor(), getCIDSystemInfo());
    if (mapping.isCIDFont()) {
        ttfFont = mapping.getFont();
    } else {
        ttfFont = ((TrueTypeFont) (mapping.getTrueTypeFont()));
        if (ttfFont == null) {
            // shouldn't happen?!
            throw new IOException("mapping.getTrueTypeFont() returns null, please report");
        }
    }
    if (mapping.isFallback()) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn((("Using fallback font " + ttfFont.getName()) + " for CID-keyed TrueType font ") + getBaseFont());
    }
    return ttfFont;
}

