/**
 * Create a PDImageXObject from an image byte array. This overloaded version allows providing
 * a custom factory to handle specific image formats, such as BMP and GIF, or to act as a
 * fallback strategy when the default converters (e.g., for PNG or TIFF) fail.
 *
 * @param document
 * 		the document that shall use this PDImageXObject.
 * @param byteArray
 * 		bytes from an image file.
 * @param name
 * 		name of image file for exception messages, can be null.
 * @param customFactory
 * 		optional factory used to handle BMP, GIF, or fallback cases
 * 		(e.g., for PNG or TIFF). If {@code null}, this method delegates to
 * 		{@link #createFromByteArray(PDDocument, byte[], String)}.
 * @return a PDImageXObject.
 * @throws IOException
 * 		if there is an error when reading the file or creating the
 * 		PDImageXObject.
 * @throws IllegalArgumentException
 * 		if the image type is not supported.
 */
public static PDImageXObject createFromByteArray(PDDocument document, byte[] byteArray, String name, CustomFactory customFactory) throws IOException {
    FileType fileType = FileTypeDetector.detectFileType(byteArray);
    if (fileType == null) {
        throw new IllegalArgumentException("Image type not supported: " + name);
    }
    if (fileType == FileType.JPEG) {
        return JPEGFactory.createFromByteArray(document, byteArray);
    }
    if (fileType == FileType.PNG) {
        // Try to directly convert the image without recoding it.
        // PATH: Test should invoke the next PNGConverter.convertPNGImage(...) [step in execution path]
        PDImageXObject image = PNGConverter.convertPNGImage(document, byteArray);
        if (image != null) {
            return image;
        }
    }
    if (fileType == FileType.TIFF) {
        try {
            return CCITTFactory.createFromByteArray(document, byteArray);
        } catch (IOException ex) {
            LOG.debug("Reading as TIFF failed, setting fileType to PNG", ex);
            // Plan B: try reading with ImageIO
            // common exception:
            // First image in tiff is not CCITT T4 or T6 compressed
            fileType = FileType.PNG;
        }
    }
    if (((fileType == FileType.BMP) || (fileType == FileType.GIF)) || (fileType == FileType.PNG)) {
        if (customFactory != null) {
            return customFactory.createFromByteArray(document, byteArray);
        }
        ByteArrayInputStream bais = new ByteArrayInputStream(byteArray);
        BufferedImage bim = ImageIO.read(bais);
        return LosslessFactory.createFromImage(document, bim);
    }
    throw new IllegalArgumentException((("Image type " + fileType) + " not supported: ") + name);
}

/**
 * Try to convert a PNG into a PDImageXObject. If for any reason the PNG can not
 * be converted, null is returned.
 * <p>
 * This usually means the PNG structure is damaged (CRC error, etc.) or it uses
 * some features which can not be mapped to PDF.
 *
 * @param doc
 * 		the document to put the image in
 * @param imageData
 * 		the byte data of the PNG
 * @return null or the PDImageXObject built from the png
 */
static PDImageXObject convertPNGImage(PDDocument doc, byte[] imageData) throws IOException {
    // PATH: Test should invoke the next PNGConverter.parsePNGChunks(...) [step in execution path]
    PNGConverterState state = parsePNGChunks(imageData);
    if (!checkConverterState(state)) {
        // There is something wrong, we can't convert this PNG
        return null;
    }
    return convertPng(doc, state);
}

/**
 * Parse the PNG structure into the PNGConverterState. If we can't handle
 * something, this method will return null.
 *
 * @param imageData
 * 		the byte array with the PNG data
 * @return null or the converter state with all relevant chunks
 */
private static PNGConverterState parsePNGChunks(byte[] imageData) {
    if (imageData.length < 20) {
        LOG.error("ByteArray way to small: " + imageData.length);
        return null;
    }
    PNGConverterState state = new PNGConverterState();
    int ptr = 8;
    int firstChunkType = readInt(imageData, ptr + 4);
    if (firstChunkType != CHUNK_IHDR) {
        LOG.error(String.format("First Chunktype was %08X, not IHDR", firstChunkType));
        return null;
    }
    while ((ptr + 12) <= imageData.length) {
        int chunkLength = readInt(imageData, ptr);
        int chunkType = readInt(imageData, ptr + 4);
        ptr += 8;
        if (((ptr + chunkLength) + 4) > imageData.length) {
            LOG.error((((("Not enough bytes. At offset " + ptr) + " are ") + chunkLength) + " bytes expected. Overall length is ") + imageData.length);
            return null;
        }
        Chunk chunk = new Chunk();
        chunk.chunkType = chunkType;
        chunk.bytes = imageData;
        chunk.start = ptr;
        chunk.length = chunkLength;
        switch (chunkType) {
            case CHUNK_IHDR :
                if (state.IHDR != null) {
                    LOG.error("Two IHDR chunks? There is something wrong.");
                    return null;
                }
                state.IHDR = chunk;
                break;
            case CHUNK_IDAT :
                // The image data itself
                state.IDATs.add(chunk);
                break;
            case CHUNK_PLTE :
                // For indexed images the palette table
                if (state.PLTE != null) {
                    LOG.error("Two PLTE chunks? There is something wrong.");
                    return null;
                }
                state.PLTE = chunk;
                break;
            case CHUNK_IEND :
                // We are done, return the state
                return state;
            case CHUNK_TRNS :
                // For indexed images the alpha transparency table
                if (state.tRNS != null) {
                    LOG.error("Two tRNS chunks? There is something wrong.");
                    return null;
                }
                state.tRNS = chunk;
                break;
            case CHUNK_GAMA :
                // Gama
                state.gAMA = chunk;
                break;
            case CHUNK_CHRM :
                // Chroma
                state.cHRM = chunk;
                break;
            case CHUNK_ICCP :
                // ICC Profile
                state.iCCP = chunk;
                break;
            case CHUNK_SBIT :
                LOG.debug("Can't convert PNGs with sBIT chunk.");
                break;
            case CHUNK_SRGB :
                // We use the rendering intent from the chunk
                state.sRGB = chunk;
                break;
            case CHUNK_TEXT :
            case CHUNK_ZTXT :
            case CHUNK_ITXT :
                // We don't care about this text infos / metadata
                break;
            case CHUNK_KBKG :
                // As we can handle transparency we don't need the background color information.
                break;
            case CHUNK_HIST :
                // We don't need the color histogram
                break;
            case CHUNK_PHYS :
                // The PDImageXObject will be placed by the user however he wants,
                // so we can not enforce the physical dpi information stored here.
                // We just ignore it.
                break;
            case CHUNK_SPLT :
                // This palette stuff seems editor related, we don't need it.
                break;
            case CHUNK_TIME :
                // We don't need the last image change time either
                break;
            default :
                LOG.debug(String.format("Unknown chunk type %08X, skipping.", chunkType));
                break;
        }
        ptr += chunkLength;
        // Read the CRC
        chunk.crc = readInt(imageData, ptr);
        ptr += 4;
    } 
    LOG.error("No IEND chunk found.");
    return null;
}

