private void drawNewParagraph(PDAnnotationText annotation, final PDAppearanceContentStream contentStream) throws IOException {
    adjustRectAndBBox(annotation, 13, 20);
    contentStream.setMiterLimit(4);
    contentStream.setLineJoinStyle(0);
    contentStream.setLineCapStyle(0);
    contentStream.setLineWidth(0.59F);// value from Adobe

    // small triangle (values from Adobe)
    contentStream.moveTo(6.4995F, 20);
    contentStream.lineTo(0.295F, 7.287F);
    contentStream.lineTo(12.705F, 7.287F);
    contentStream.closeAndFillAndStroke();
    // rescale and translate so that "NP" fits below the triangle
    // values gathered by trial and error
    contentStream.transform(Matrix.getScaleInstance(0.001F * 4, 0.001F * 4));
    contentStream.transform(Matrix.getTranslateInstance(200, 0));
    // PATH: Test should invoke the next Standard14Fonts.getGlyphPath(...) [step in execution path]
    addPath(contentStream, Standard14Fonts.getGlyphPath(FontName.HELVETICA_BOLD, "N"));
    contentStream.transform(Matrix.getTranslateInstance(1300, 0));
    addPath(contentStream, Standard14Fonts.getGlyphPath(FontName.HELVETICA_BOLD, "P"));
    contentStream.fill();
}

/**
 * Returns the path for the character with the given name for the specified Standard 14 font. The mapped font is
 * cached. The path may differ in different environments as it depends on the mapped font.
 *
 * @param baseName
 * 		name of the standard 14 font
 * @param glyphName
 * 		name of glyph
 * @return the mapped font
 * @throws IOException
 * 		if the data could not be read
 */
public static GeneralPath getGlyphPath(FontName baseName, String glyphName) throws IOException {
    // copied and adapted from PDType1Font.getNameInFont(String)
    if (!glyphName.equals(".notdef")) {
        FontBoxFont mappedFont = getMappedFont(baseName);
        if (mappedFont != null) {
            if (mappedFont.hasGlyph(glyphName)) {
                return mappedFont.getPath(glyphName);
            }
            // PATH: Test should invoke the next GlyphList.toUnicode(...) [step in execution path]
            String unicodes = getGlyphList(baseName).toUnicode(glyphName);
            if ((unicodes != null) && (unicodes.length() == 1)) {
                String uniName = getUniNameOfCodePoint(unicodes.codePointAt(0));
                if (mappedFont.hasGlyph(uniName)) {
                    return mappedFont.getPath(uniName);
                }
            }
            if ("SymbolMT".equals(mappedFont.getName())) {
                Integer code = SymbolEncoding.INSTANCE.getNameToCodeMap().get(glyphName);
                if (code != null) {
                    String uniName = getUniNameOfCodePoint(code + 0xf000);
                    if (mappedFont.hasGlyph(uniName)) {
                        return mappedFont.getPath(uniName);
                    }
                }
            }
        }
    }
    return new GeneralPath();
}

/**
 * Returns the Unicode character sequence for the given glyph name, or null if there isn't any.
 *
 * @param name
 * 		PostScript glyph name
 * @return Unicode character(s), or null.
 */
public String toUnicode(String name) {
    if (name == null) {
        return null;
    }
    String unicode = nameToUnicode.get(name);
    if (unicode != null) {
        return unicode;
    }
    // separate read/write cache for thread safety
    unicode = uniNameToUnicodeCache.get(name);
    if (unicode == null) {
        // test if we have a suffix and if so remove it
        if (name.indexOf('.') > 0) {
            unicode = toUnicode(name.substring(0, name.indexOf('.')));
        } else if (((name.length() == 7) && name.startsWith("uni")) || ((name.length() == 5) && name.startsWith("u"))) {
            // test for Unicode name in the format uniXXXX where X is hex
            int start = (name.length() == 7) ? 3 : 1;
            try {
                int codePoint = Integer.parseInt(name.substring(start), 16);
                if ((codePoint > 0xd7ff) && (codePoint < 0xe000)) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
                {
                    LOG.warn("Unicode character name with disallowed code area: " + name);
                } else {
                    unicode = String.valueOf(((char) (codePoint)));
                }
            } catch (NumberFormatException nfe) {
                LOG.warn("Not a number in Unicode character name: " + name);
            }
        }
        if (unicode != null) {
            // null value not allowed in ConcurrentHashMap
            uniNameToUnicodeCache.put(name, unicode);
        }
    }
    return unicode;
}

