/**
 * Creates a new TrueType font from a Font dictionary.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @throws IOException
 * 		if the font could not be created
 */
public (COSDictionary fontDictionary) throws IOException {
    this(fontDictionary);
    TrueTypeFont ttfFont = null;
    boolean fontIsDamaged = false;
    if (getFontDescriptor() != null) {
        PDFontDescriptor fd = super.getFontDescriptor();
        PDStream ff2Stream = fd.getFontFile2();
        if (ff2Stream != null) {
            RandomAccessRead view = null;
            try {
                view = ff2Stream.getCOSObject().createView();
                // embedded
                TTFParser ttfParser = getParser(view, true);
                ttfFont = ttfParser.parse(view);
                ttfFont.close();
            } catch (IOException e) {
                LOG.warn("Could not read embedded TTF for font " + getBaseFont(), e);
                fontIsDamaged = true;
                IOUtils.closeQuietly(view);
            }
        }
    }
    isEmbedded = ttfFont != null;
    isDamaged = fontIsDamaged;
    // substitute
    if (ttfFont == null) {
        // PATH: Test should invoke the next FontMapperImpl.getTrueTypeFont(...) [step in execution path]
        FontMapping<TrueTypeFont> mapping = FontMappers.instance().getTrueTypeFont(getBaseFont(), getFontDescriptor());
        ttfFont = mapping.getFont();
        if (mapping.isFallback()) {
            LOG.warn((("Using fallback font " + ttfFont) + " for ") + getBaseFont());
        }
    }
    otf = ((ttfFont instanceof OpenTypeFont) && ((OpenTypeFont) (ttfFont)).isSupportedOTF()) ? ((OpenTypeFont) (ttfFont)) : null;
    ttf = ttfFont;
    readEncoding();
}

/**
 * Finds a TrueType font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param fontDescriptor
 * 		FontDescriptor
 */
@Override
public FontMapping<TrueTypeFont> getTrueTypeFont(String baseFont, PDFontDescriptor fontDescriptor) {
    // PATH: Test should invoke the next FontMapperImpl.findFont(...) [step in execution path]
    TrueTypeFont ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, baseFont)));
    if (ttf != null) {
        return new FontMapping<>(ttf, false);
    } else {
        // fallback - todo: i.e. fuzzy match
        String fontName = getFallbackFontName(fontDescriptor);
        ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, fontName)));
        if (ttf == null) {
            // we have to return something here as TTFs aren't strictly required on the system
            ttf = lastResortFont;
        }
        return new FontMapping<>(ttf, true);
    }
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param postScriptName
 * 		PostScript font name
 */
private FontBoxFont findFont(FontFormat format, String postScriptName) {
    // handle damaged PDFs, see PDFBOX-2884
    if (postScriptName == null) {
        return null;
    }
    // make sure the font provider is initialized
    if (fontProvider == null) {
        getProvider();
    }
    // first try to match the PostScript name
    FontInfo info = getFont(format, postScriptName);
    if (info != null) {
        // PATH: Test should invoke the next FileSystemFontProvider$FSFontInfo.getFont(...) [step in execution path]
        return info.getFont();
    }
    // remove hyphens (e.g. Arial-Black -> ArialBlack)
    info = getFont(format, postScriptName.replace("-", ""));
    if (info != null) {
        return info.getFont();
    }
    // then try named substitutes
    for (String substituteName : getSubstitutes(postScriptName)) {
        info = getFont(format, substituteName);
        if (info != null) {
            return info.getFont();
        }
    }
    // then try converting Windows names e.g. (ArialNarrow,Bold) -> (ArialNarrow-Bold)
    info = getFont(format, postScriptName.replace(",", "-"));
    if (info != null) {
        return info.getFont();
    }
    if (postScriptName.contains(",")) {
        postScriptName = postScriptName.substring(0, postScriptName.indexOf(","));
        // PDFBOX-5806: try cutting font style and getting the basefont
        // eg. for "Wingdings,Bolt" to "Wingding-Regular" (including the following step)
        info = getFont(format, postScriptName);
        if (info != null) {
            return info.getFont();
        }
    }
    // try appending "-Regular", works for Wingdings on windows
    info = getFont(format, postScriptName + "-Regular");
    if (info != null) {
        return info.getFont();
    }
    // no matches
    return null;
}

/**
 * {@inheritDoc }
 * <p>
 * The method returns null if there was an error opening the font.
 */
@Override
public synchronized FontBoxFont getFont() {
    // synchronized to avoid race condition on cache access,
    // which could result in an unreferenced but open font
    FontBoxFont cached = parent.cache.getFont(this);
    if (cached != null) {
        return cached;
    } else {
        FontBoxFont font;
        switch (format) {
            case PFB :
                font = getType1Font(postScriptName, file);
                break;
            case TTF :
                // PATH: Test should invoke the next FileSystemFontProvider$FSFontInfo.getTrueTypeFont(...) [step in execution path]
                font = getTrueTypeFont(postScriptName, file);
                break;
            case OTF :
                font = getOTFFont(postScriptName, file);
                break;
            default :
                throw new RuntimeException("can't happen");
        }
        if (font != null) {
            parent.cache.addFont(this, font);
        }
        return font;
    }
}

private TrueTypeFont getTrueTypeFont(String postScriptName, File file) {
    try {
        TrueTypeFont ttf = readTrueTypeFont(postScriptName, file);
        if (LOG.isDebugEnabled()) {
            LOG.debug((("Loaded " + postScriptName) + " from ") + file);
        }
        return ttf;
    } catch (IOException e) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn("Could not load font file: " + file, e);
    }
    return null;
}

