/**
 * This will write the pdf document. If signature should be created externally,
 * {@link #writeExternalSignature(byte[])} should be invoked to set signature after calling this method.
 *
 * @param doc
 * 		The document to write.
 * @param signInterface
 * 		class to be used for signing; {@code null} if external signing would be performed
 * 		or there will be no signing at all
 * @throws IOException
 * 		If an error occurs while generating the data.
 * @throws IllegalStateException
 * 		If the document has an encryption dictionary but no protection
 * 		policy.
 */
public void write(PDDocument doc, SignatureInterface signInterface) throws IOException {
    pdDocument = doc;
    COSDocument cosDoc = pdDocument.getDocument();
    COSDictionary trailer = cosDoc.getTrailer();
    if (incrementalUpdate) {
        trailer.toIncrement().exclude(trailer).forEach(base -> {
            objectsToWrite.add(base);
            if (base instanceof COSObject) {
                actualsAdded.add(((COSObject) (base)).getObject());
            } else {
                actualsAdded.add(base);
            }
        });
    }
    signatureInterface = signInterface;
    number = pdDocument.getDocument().getHighestXRefObjectNumber();
    if (incrementalUpdate) {
        prepareIncrement();
    }
    long idTime = (pdDocument.getDocumentId() == null) ? System.currentTimeMillis() : pdDocument.getDocumentId();
    // if the document says we should remove encryption, then we shouldn't encrypt
    if (doc.isAllSecurityToBeRemoved()) {
        willEncrypt = false;
        // also need to get rid of the "Encrypt" in the trailer so readers
        // don't try to decrypt a document which is not encrypted
        trailer.removeItem(COSName.ENCRYPT);
    } else if (pdDocument.getEncryption() != null) {
        if (!incrementalUpdate) // PATH: Test should invoke the next PublicKeySecurityHandler.prepareDocumentForEncryption(...) [step in execution path]
        {
            SecurityHandler<? extends ProtectionPolicy> securityHandler = pdDocument.getEncryption().getSecurityHandler();
            if (!securityHandler.hasProtectionPolicy()) {
                throw new IllegalStateException("PDF contains an encryption dictionary, please remove it with " + "setAllSecurityToBeRemoved() or set a protection policy with protect()");
            }
            securityHandler.prepareDocumentForEncryption(pdDocument);
        }
        willEncrypt = true;
    } else {
        willEncrypt = false;
    }
    COSArray idArray;
    boolean missingID = true;
    COSBase base = trailer.getDictionaryObject(COSName.ID);
    if (base instanceof COSArray) {
        idArray = ((COSArray) (base));
        if (idArray.size() == 2) {
            missingID = false;
        }
    } else {
        idArray = new COSArray();
    }
    if (missingID || incrementalUpdate) {
        MessageDigest sha256;
        try {
            sha256 = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            // should never happen
            throw new RuntimeException(e);
        }
        // algorithm says to use time/path/size/values in doc to generate the id.
        // we don't have path or size, so do the best we can
        sha256.update(Long.toString(idTime).getBytes(StandardCharsets.ISO_8859_1));
        COSDictionary info = trailer.getCOSDictionary(COSName.INFO);
        if (info != null) {
            for (COSBase cosBase : info.getValues()) {
                sha256.update(cosBase.toString().getBytes(StandardCharsets.ISO_8859_1));
            }
        }
        // reuse origin documentID if available as first value
        COSString firstID = (missingID) ? new COSString(sha256.digest()) : ((COSString) (idArray.get(0)));
        // it's ok to use the same ID for the second part if the ID is created for the first time
        COSString secondID = (missingID) ? firstID : new COSString(sha256.digest());
        idArray = new COSArray();
        idArray.add(firstID);
        idArray.add(secondID);
        trailer.setItem(COSName.ID, idArray);
    }
    cosDoc.accept(this);
    if (!incrementalUpdate) {
        cosDoc.setHighestXRefObjectNumber(number);
    }
}

/**
 * Prepare the document for encryption.
 *
 * @param doc
 * 		The document that will be encrypted.
 * @throws IOException
 * 		If there is an error while encrypting.
 */
@Override
public void prepareDocumentForEncryption(PDDocument doc) throws IOException {
    try {
        PDEncryption dictionary = doc.getEncryption();
        if (dictionary == null) {
            dictionary = new PDEncryption();
        }
        dictionary.setFilter(FILTER);
        dictionary.setLength(getKeyLength());
        int version = computeVersionNumber();
        dictionary.setVersion(version);
        // remove CF, StmF, and StrF entries that may be left from a previous encryption
        dictionary.removeV45filters();
        // create the 20 bytes seed
        byte[] seed = new byte[20];
        KeyGenerator key;
        try {
            key = KeyGenerator.getInstance("AES");
        } catch (NoSuchAlgorithmException e) {
            // should never happen
            throw new RuntimeException(e);
        }
        key.init(192, new SecureRandom());
        SecretKey sk = key.generateKey();
        // create the 20 bytes seed
        System.arraycopy(sk.getEncoded(), 0, seed, 0, 20);
        // PATH: Test should invoke the next PublicKeySecurityHandler.computeRecipientsField(...) [step in execution path]
        byte[][] recipientsFields = computeRecipientsField(seed);
        int shaInputLength = seed.length;
        for (byte[] field : recipientsFields) {
            shaInputLength += field.length;
        }
        byte[] shaInput = new byte[shaInputLength];
        System.arraycopy(seed, 0, shaInput, 0, 20);
        int shaInputOffset = 20;
        for (byte[] recipientsField : recipientsFields) {
            System.arraycopy(recipientsField, 0, shaInput, shaInputOffset, recipientsField.length);
            shaInputOffset += recipientsField.length;
        }
        byte[] mdResult;
        switch (version) {
            case 4 :
                dictionary.setSubFilter(SUBFILTER5);
                mdResult = MessageDigests.getSHA1().digest(shaInput);
                prepareEncryptionDictAES(dictionary, COSName.AESV2, recipientsFields);
                break;
            case 5 :
                dictionary.setSubFilter(SUBFILTER5);
                mdResult = MessageDigests.getSHA256().digest(shaInput);
                prepareEncryptionDictAES(dictionary, COSName.AESV3, recipientsFields);
                break;
            default :
                dictionary.setSubFilter(SUBFILTER4);
                mdResult = MessageDigests.getSHA1().digest(shaInput);
                dictionary.setRecipients(recipientsFields);
                break;
        }
        setEncryptionKey(new byte[getKeyLength() / 8]);
        System.arraycopy(mdResult, 0, getEncryptionKey(), 0, getKeyLength() / 8);
        doc.setEncryptionDictionary(dictionary);
        doc.getDocument().setEncryptionDictionary(dictionary.getCOSObject());
    } catch (GeneralSecurityException e) {
        throw new IOException(e);
    }
}

private byte[][] computeRecipientsField(byte[] seed) throws GeneralSecurityException, IOException {
    PublicKeyProtectionPolicy protectionPolicy = getProtectionPolicy();
    byte[][] recipientsField = new byte[protectionPolicy.getNumberOfRecipients()][];
    Iterator<PublicKeyRecipient> it = protectionPolicy.getRecipientsIterator();
    int i = 0;
    while (it.hasNext()) {
        PublicKeyRecipient recipient = it.next();
        X509Certificate certificate = recipient.getX509();
        int permission = recipient.getPermission().getPermissionBytesForPublicKey();
        byte[] pkcs7input = new byte[24];
        byte one = ((byte) (permission));
        byte two = ((byte) (permission >>> 8));
        byte three = ((byte) (permission >>> 16));
        byte four = ((byte) (permission >>> 24));
        // put this seed in the pkcs7 input
        System.arraycopy(seed, 0, pkcs7input, 0, 20);
        pkcs7input[20] = four;
        pkcs7input[21] = three;
        pkcs7input[22] = two;
        pkcs7input[23] = one;
        // PATH: Test should invoke the next PublicKeySecurityHandler.createDERForRecipient(...) [step in execution path]
        ASN1Primitive obj = createDERForRecipient(pkcs7input, certificate);
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        obj.encodeTo(baos, ASN1Encoding.DER);
        recipientsField[i] = baos.toByteArray();
        i++;
    } 
    return recipientsField;
}

private ASN1Primitive createDERForRecipient(byte[] in, X509Certificate cert) throws IOException, GeneralSecurityException {
    String algorithm = PKCSObjectIdentifiers.RC2_CBC.getId();
    AlgorithmParameterGenerator apg;
    KeyGenerator keygen;
    Cipher cipher;
    try {
        Provider provider = SecurityProvider.getProvider();
        apg = AlgorithmParameterGenerator.getInstance(algorithm, provider);
        keygen = KeyGenerator.getInstance(algorithm, provider);
        cipher = Cipher.getInstance(algorithm, provider);
    } catch (NoSuchAlgorithmException e) {
        // happens when using the command line app .jar file
        throw new IOException(("Could not find a suitable javax.crypto provider for algorithm " + algorithm) + "; possible reason: using an unsigned .jar file", e);
    } catch (NoSuchPaddingException e) {
        // should never happen, if this happens throw IOException instead
        throw new RuntimeException("Could not find a suitable javax.crypto provider", e);
    }
    AlgorithmParameters parameters = apg.generateParameters();
    ASN1Primitive object;
    try (ASN1InputStream input = new ASN1InputStream(parameters.getEncoded("ASN.1"))) {
        object = input.readObject();
    }
    keygen.init(128);
    SecretKey secretkey = keygen.generateKey();
    cipher.init(1, secretkey, parameters);
    byte[] bytes = cipher.doFinal(in);
    // PATH: Test should invoke the next PublicKeySecurityHandler.computeRecipientInfo(...) [step in execution path]
    KeyTransRecipientInfo recipientInfo = computeRecipientInfo(cert, secretkey.getEncoded());
    DERSet set = new DERSet(new RecipientInfo(recipientInfo));
    AlgorithmIdentifier algorithmId = new AlgorithmIdentifier(new ASN1ObjectIdentifier(algorithm), object);
    EncryptedContentInfo encryptedInfo = new EncryptedContentInfo(PKCSObjectIdentifiers.data, algorithmId, new DEROctetString(bytes));
    EnvelopedData enveloped = new EnvelopedData(null, set, encryptedInfo, ((ASN1Set) (null)));
    ContentInfo contentInfo = new ContentInfo(PKCSObjectIdentifiers.envelopedData, enveloped);
    return contentInfo.toASN1Primitive();
}

private KeyTransRecipientInfo computeRecipientInfo(X509Certificate x509certificate, byte[] abyte0) throws IOException, CertificateEncodingException, InvalidKeyException, BadPaddingException, IllegalBlockSizeException {
    TBSCertificate certificate;
    try (ASN1InputStream input = new ASN1InputStream(x509certificate.getTBSCertificate())) {
        certificate = // PATH: Test should invoke the next new ASN1InputStream(...) [step in execution path]
        TBSCertificate.getInstance(input.readObject());
    }
    AlgorithmIdentifier algorithmId = certificate.getSubjectPublicKeyInfo().getAlgorithm();
    IssuerAndSerialNumber serial = new IssuerAndSerialNumber(certificate.getIssuer(), certificate.getSerialNumber().getValue());
    Cipher cipher;
    try {
        cipher = Cipher.getInstance(algorithmId.getAlgorithm().getId(), SecurityProvider.getProvider());
    } catch (NoSuchAlgorithmException | NoSuchPaddingException e) {
        // should never happen, if this happens throw IOException instead
        throw new RuntimeException("Could not find a suitable javax.crypto provider", e);
    }
    cipher.init(1, x509certificate.getPublicKey());
    DEROctetString octets = new DEROctetString(cipher.doFinal(abyte0));
    RecipientIdentifier recipientId = new RecipientIdentifier(serial);
    return new KeyTransRecipientInfo(recipientId, algorithmId, octets);
}

