/**
 * This will take a document and split into several other documents.
 *
 * @param document
 * 		The document to split.
 * @return A list of all the split documents. These should all be saved before closing any
documents, including the source document. Any further operations should be made after
reloading them, to avoid problems due to resource sharing. For the same reason, they should
not be saved with encryption.
 * @throws IOException
 * 		If there is an IOError
 */
public List<PDDocument> split(PDDocument document) throws IOException {
    // reset the currentPageNumber for a case if the split method will be used several times
    currentPageNumber = 0;
    destinationDocuments = new ArrayList<>();
    sourceDocument = document;
    pageDictMaps = new ArrayList<>();
    annotDictMaps = new ArrayList<>();
    destToFixMap = new HashMap<>();
    idSet = new HashSet<>();
    roleSet = new HashSet<>();
    processPages();
    for (int i = 0; i < destinationDocuments.size(); ++i) // PATH: Test should invoke the next Splitter.cloneStructureTree(...) [step in execution path]
    {
        PDDocument destinationDocument = destinationDocuments.get(i);
        pageDictMap = pageDictMaps.get(i);
        annotDictMap = annotDictMaps.get(i);
        cloneStructureTree(destinationDocument);
        fixDestinations(destinationDocument);
    }
    return destinationDocuments;
}

/**
 * Clone the structure tree from the source to the current destination document. This must be
 * called after all pages are processed.
 *
 * @param destinationDocument
 * @throws IOException
 */
private void cloneStructureTree(PDDocument destinationDocument) throws IOException {
    PDStructureTreeRoot srcStructureTreeRoot = sourceDocument.getDocumentCatalog().getStructureTreeRoot();
    if (srcStructureTreeRoot == null) {
        return;
    }
    structDictMap = new HashMap<>();
    PDStructureTreeRoot dstStructureTreeRoot = new PDStructureTreeRoot();
    PDPageTree dstPageTree = destinationDocument.getPages();
    // clone /K, also fills dictMap
    COSBase k1 = srcStructureTreeRoot.getK();
    COSBase k2 = new KCloner(dstPageTree).createClone(k1, dstStructureTreeRoot.getCOSObject(), null);
    dstStructureTreeRoot.setK(k2);
    // transfer ParentTree using the map because the dictionaries are all found in the /K structure.
    PDNumberTreeNode srcParentTree = srcStructureTreeRoot.getParentTree();
    Map<Integer, COSObjectable> srcNumberTreeAsMap = PDFMergerUtility.getNumberTreeAsMap(srcParentTree);
    Map<Integer, COSObjectable> dstNumberTreeAsMap = new LinkedHashMap<>();
    for (int p = 0; p < dstPageTree.getCount(); ++p) {
        // PATH: Test should invoke the next PDPageTree.get(...) [step in execution path]
        PDPage page = dstPageTree.get(p);
        int sp1 = page.getStructParents();
        if (sp1 != (-1)) {
            cloneTreeElement(srcNumberTreeAsMap, dstNumberTreeAsMap, sp1);
        }
        for (PDAnnotation ann : page.getAnnotations()) {
            int sp2 = ann.getStructParent();
            if (sp2 != (-1)) {
                cloneTreeElement(srcNumberTreeAsMap, dstNumberTreeAsMap, sp2);
            }
            PDAppearanceStream normalAppearanceStream = ann.getNormalAppearanceStream();
            if (normalAppearanceStream != null) {
                processResources(normalAppearanceStream.getResources(), srcNumberTreeAsMap, dstNumberTreeAsMap, new HashSet<>());
            }
        }
        processResources(page.getResources(), srcNumberTreeAsMap, dstNumberTreeAsMap, new HashSet<>());
    }
    PDNumberTreeNode dstNumberTreeNode = new PDNumberTreeNode(PDParentTreeValue.class);
    dstNumberTreeNode.setNumbers(dstNumberTreeAsMap);
    dstStructureTreeRoot.setParentTree(dstNumberTreeNode);
    Integer upperLimit = dstNumberTreeNode.getUpperLimit();
    if (upperLimit != null) {
        dstStructureTreeRoot.setParentTreeNextKey(upperLimit + 1);
    }
    dstStructureTreeRoot.setClassMap(srcStructureTreeRoot.getClassMap());
    cloneRoleMap(srcStructureTreeRoot, dstStructureTreeRoot);
    cloneIDTree(srcStructureTreeRoot, dstStructureTreeRoot);
    destinationDocument.getDocumentCatalog().setStructureTreeRoot(dstStructureTreeRoot);
}

/**
 * Returns the page at the given index.
 *
 * @param index
 * 		zero-based index
 * @return the page at the given index
 * @throws IllegalStateException
 * 		if the requested index isn't found or doesn't point to a valid page dictionary
 * @throws IndexOutOfBoundsException
 * 		if the requested index is higher than the page count
 */
public PDPage get(int index) {
    // PATH: Test should invoke the next PDPageTree.get(...) [step in execution path]
    COSDictionary dict = get(index + 1, root, 0);
    sanitizeType(dict);
    ResourceCache resourceCache = (document != null) ? document.getResourceCache() : null;
    return new PDPage(dict, resourceCache);
}

/**
 * Returns the given COS page using a depth-first search.
 *
 * @param pageNum
 * 		1-based page number
 * @param node
 * 		page tree node to search
 * @param encountered
 * 		number of pages encountered so far
 * @return COS dictionary of the Page object
 * @throws IllegalStateException
 * 		if the requested page number isn't found
 * @throws IndexOutOfBoundsException
 * 		if the requested page number is higher than the page count
 */
private COSDictionary get(int pageNum, COSDictionary node, int encountered) {
    if (pageNum < 1) {
        throw new IndexOutOfBoundsException("Index out of bounds: " + pageNum);
    }
    if (pageSet.contains(node)) {
        pageSet.clear();
        throw new IllegalStateException("Possible recursion found when searching for page " + pageNum);
    } else {
        // collect already processed pages to detect possible recursions
        // to avoid a StackOverflowError
        pageSet.add(node);
    }
    if (isPageTreeNode(node)) {
        int count = node.getInt(COSName.COUNT, 0);
        if (pageNum <= (encountered + count)) {
            // it's a kid of this node
            // PATH: Test should invoke the next PDPageTree.getKids(...) [step in execution path]
            for (COSDictionary kid : getKids(node)) {
                // which kid?
                if (isPageTreeNode(kid)) {
                    int kidCount = kid.getInt(COSName.COUNT, 0);
                    if (pageNum <= (encountered + kidCount)) {
                        // it's this kid
                        return get(pageNum, kid, encountered);
                    } else {
                        encountered += kidCount;
                    }
                } else {
                    // single page
                    encountered++;
                    if (pageNum == encountered) {
                        // it's this page
                        return get(pageNum, kid, encountered);
                    }
                }
            }
            throw new IllegalStateException("1-based index not found: " + pageNum);
        } else {
            throw new IndexOutOfBoundsException("1-based index out of bounds: " + pageNum);
        }
    } else if (encountered == pageNum) {
        pageSet.clear();
        return node;
    } else {
        throw new IllegalStateException("1-based index not found: " + pageNum);
    }
}

/**
 * Helper to get kids from malformed PDFs.
 *
 * @param node
 * 		page tree node
 * @return list of kids
 */
private List<COSDictionary> getKids(COSDictionary node) {
    COSArray kids = node.getCOSArray(COSName.KIDS);
    if (kids == null) {
        // probably a malformed PDF
        return Collections.emptyList();
    }
    int size = kids.size();
    List<COSDictionary> result = new ArrayList<>(size);
    for (int i = 0; i < size; i++) {
        COSBase base = kids.getObject(i);
        if (base instanceof COSDictionary) {
            result.add(((COSDictionary) (base)));
        } else if (base == null) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
        {
            LOG.warn("replaced null entry with an empty page");
            COSDictionary emptyPage = new COSDictionary();
            emptyPage.setItem(COSName.TYPE, COSName.PAGE);
            kids.set(i, emptyPage);
            result.add(emptyPage);
        } else {
            LOG.warn("COSDictionary expected, but got " + base.getClass().getSimpleName());
        }
    }
    return result;
}

