 */
public void writeText(PDDocument doc, Writer outputStream) throws IOException // PATH: Test should invoke the next PDFTextStripper.processPages(...) [step in execution path]
{
    resetEngine();
    document = doc;
    output = outputStream;
    if (getAddMoreFormatting()) {
        paragraphEnd = lineSeparator;
        pageStart = lineSeparator;
        articleStart = lineSeparator;
        articleEnd = lineSeparator;
    }
    startDocument(document);
    processPages(document.getPages());
    endDocument(document);
}

/**
 * This will process all of the pages and the text that is in them.
 *
 * @param pages
 * 		The pages object in the document.
 * @throws IOException
 * 		If there is an error parsing the text.
 */
protected void processPages(PDPageTree pages) throws IOException {
    // PATH: Test should invoke the next PDOutlineItem.findDestinationPage(...) [step in execution path]
    PDPage startBookmarkPage = (startBookmark == null) ? null : startBookmark.findDestinationPage(document);
    if (startBookmarkPage != null) {
        startBookmarkPageNumber = pages.indexOf(startBookmarkPage) + 1;
    } else {
        // -1 = undefined
        startBookmarkPageNumber = -1;
    }
    PDPage endBookmarkPage = (endBookmark == null) ? null : endBookmark.findDestinationPage(document);
    if (endBookmarkPage != null) {
        endBookmarkPageNumber = pages.indexOf(endBookmarkPage) + 1;
    } else {
        // -1 = undefined
        endBookmarkPageNumber = -1;
    }
    if (((((startBookmarkPageNumber == (-1)) && (startBookmark != null)) && (endBookmarkPageNumber == (-1))) && (endBookmark != null)) && (startBookmark.getCOSObject() == endBookmark.getCOSObject())) {
        // this is a special case where both the start and end bookmark
        // are the same but point to nothing. In this case
        // we will not extract any text.
        startBookmarkPageNumber = 0;
        endBookmarkPageNumber = 0;
    }
    for (PDPage page : pages) {
        if (page.hasContents()) {
            processPage(page);
        }
        currentPageNo++;
    }
}

/**
 * This method will attempt to find the page in this PDF document that this outline points to.
 * If the outline does not point to anything then this method will return null. If the outline
 * is an action that is not a GoTo action then this method will also return null.
 *
 * @param doc
 * 		The document to get the page from.
 * @return The page that this outline will go to when activated or null if it does not point to
anything.
 * @throws IOException
 * 		If there is an error when trying to find the page.
 */
public PDPage findDestinationPage(PDDocument doc) throws IOException {
    PDDestination dest = getDestination();
    if (dest == null) {
        PDAction outlineAction = getAction();
        if (outlineAction instanceof PDActionGoTo) {
            dest = ((PDActionGoTo) (outlineAction)).getDestination();
        }
    }
    if (dest == null) {
        return null;
    }
    PDPageDestination pageDestination = null;
    if (dest instanceof PDNamedDestination) {
        // PATH: Test should invoke the next PDDocumentCatalog.findNamedDestinationPage(...) [step in execution path]
        pageDestination = doc.getDocumentCatalog().findNamedDestinationPage(((PDNamedDestination) (dest)));
        if (pageDestination == null) {
            return null;
        }
    } else if (dest instanceof PDPageDestination) {
        pageDestination = ((PDPageDestination) (dest));
    } else {
        throw new IOException("Error: Unknown destination type " + dest);
    }
    PDPage page = pageDestination.getPage();
    if (page == null) {
        // Malformed PDF: local destinations must have a page object,
        // not a page number, these are meant for remote destinations.
        int pageNumber = pageDestination.getPageNumber();
        if (pageNumber != (-1)) {
            page = doc.getPage(pageNumber);
        }
    }
    return page;
}

/**
 * Find the page destination from a named destination.
 *
 * @param namedDest
 * 		the named destination.
 * @return a PDPageDestination object or null if not found.
 * @throws IOException
 * 		if there is an error creating the PDPageDestination object.
 */
public PDPageDestination findNamedDestinationPage(PDNamedDestination namedDest) throws IOException {
    PDPageDestination pageDestination = null;
    PDDocumentNameDictionary namesDict = getNames();
    if (namesDict != null) {
        PDDestinationNameTreeNode destsTree = namesDict.getDests();
        if (destsTree != null) {
            // PATH: Test should invoke the next PDNameTreeNode.getValue(...) [step in execution path]
            pageDestination = destsTree.getValue(namedDest.getNamedDestination());
        }
    }
    if (pageDestination == null) {
        // Look up /Dests dictionary from catalog
        PDDocumentNameDestinationDictionary nameDestDict = getDests();
        if (nameDestDict != null) {
            String name = namedDest.getNamedDestination();
            pageDestination = ((PDPageDestination) (nameDestDict.getDestination(name)));
        }
    }
    return pageDestination;
}

/**
 * The name to retrieve.
 *
 * @param name
 * 		The name in the tree.
 * @return The value of the name in the tree.
 * @throws IOException
 * 		If there is a problem creating the destinations.
 */
public T getValue(String name) throws IOException {
    Map<String, T> names = getNames();
    if (names != null) {
        return names.get(name);
    }
    List<PDNameTreeNode<T>> kids = getKids();
    if (kids != null) {
        for (int i = 0; i < kids.size(); i++) {
            PDNameTreeNode<T> childNode = kids.get(i);
            String upperLimit = childNode.getUpperLimit();
            String lowerLimit = childNode.getLowerLimit();
            if ((((upperLimit == null) || (lowerLimit == null)) || (upperLimit.compareTo(lowerLimit) < 0)) || ((lowerLimit.compareTo(name) <= 0) && (upperLimit.compareTo(name) >= 0))) {
                return childNode.getValue(name);
            }
        }
    } else // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn("NameTreeNode does not have \"names\" nor \"kids\" objects.");
    }
    return null;
}

