public void showTransparencyGroup(PDTransparencyGroup form) throws IOException // PATH: Test should invoke the next PageDrawer.showTransparencyGroupOnGraphics(...) [step in execution path]
{
    showTransparencyGroupOnGraphics(form, graphics);
