private static FontType getFontTypeFromFont(COSDictionary fontDescriptor, COSName fontType) throws IOException {
    // PATH: Test should invoke the next PDFontFactory.getFontHeader(...) [step in execution path]
    byte[] fontHeader = getFontHeader(fontDescriptor);
    if (fontHeader == null) {
        return null;
    }
    boolean isComposite = COSName.TYPE0.equals(fontType);
    if (isTrueTypeFile(fontHeader) || isTrueTypeCollectionFile(fontHeader)) {
        return isComposite// 
         ? new FontType(COSName.TYPE0, COSName.TRUE_TYPE.getName()) : new FontType(COSName.TRUE_TYPE);
    }
    if (isOpenTypeFile(fontHeader)) {
        return isComposite// 
         ? new FontType(COSName.TYPE0, COSName.OPEN_TYPE.getName()) : new FontType(COSName.OPEN_TYPE);
    }
    if (isType1File(fontHeader) || isPfbFile(fontHeader)) {
        if (isComposite) {
            return new FontType(COSName.TYPE0, COSName.TYPE1.getName());
        }
        return fontType.equals(COSName.MM_TYPE1) ? new FontType(COSName.MM_TYPE1, COSName.TYPE1.getName()) : new FontType(COSName.TYPE1);
    }
    // CFF fonts have a more or less variable header so that the check should be done
    // after all others to avoid wrong classifications
    if (isCFFFile(fontHeader)) {
        if (isComposite) {
            return new FontType(COSName.TYPE0, FONT_TYPE1C);
        }
        return fontType.equals(COSName.MM_TYPE1)// 
         ? new FontType(COSName.MM_TYPE1, FONT_TYPE1C) : new FontType(COSName.TYPE1, FONT_TYPE1C);
    }
    return null;
}

private static byte[] getFontHeader(COSDictionary fontDescriptor) throws IOException {
    if (fontDescriptor == null) {
        return null;
    }
    COSStream fontFile = fontDescriptor.getCOSStream(COSName.FONT_FILE);
    if (fontFile == null) {
        fontFile = fontDescriptor.getCOSStream(COSName.FONT_FILE2);
    }
    if (fontFile == null) {
        fontFile = fontDescriptor.getCOSStream(COSName.FONT_FILE3);
    }
    byte[] header = null;
    if (fontFile != null) {
        try (RandomAccessRead fontView = fontFile.createView()) {
            int headerLength = 4;
            header = new byte[headerLength];
            int remainingBytes = headerLength;
            int amountRead;
            while ((amountRead = fontView.read(header, headerLength - remainingBytes, remainingBytes)) > 0) {
                remainingBytes -= amountRead;
            } 
        } catch (IOException ex) // PATH: Test should invoke the next Log.error(...) [step in execution path]
        {
            LOG.error(ex.getMessage(), ex);
        }
    }
    return header;
}

