/**
 * Draws the page to the requested context.
 *
 * @param g
 * 		The graphics context to draw onto.
 * @param pageSize
 * 		The size of the page to draw.
 * @throws IOException
 * 		If there is an IO error while drawing the page.
 */
public void drawPage(Graphics2D g, PDRectangle pageSize) throws IOException {
    graphics = g;
    xform = graphics.getTransform();
    Matrix m = new Matrix(xform);
    xformScalingFactorX = Math.abs(m.getScalingFactorX());
    xformScalingFactorY = Math.abs(m.getScalingFactorY());
    initialClip = graphics.getClip();
    this.pageSize = pageSize;
    setRenderingHints();
    graphics.translate(0, pageSize.getHeight());
    graphics.scale(1, -1);
    // adjust for non-(0,0) crop box
    graphics.translate(-pageSize.getLowerLeftX(), -pageSize.getLowerLeftY());
    processPage(getPage());
    for (PDAnnotation annotation : getPage().getAnnotations(annotationFilter)) // PATH: Test should invoke the next PageDrawer.showAnnotation(...) [step in execution path]
    {
        showAnnotation(annotation);
    }
    graphics = null;
}

@Override
public void showAnnotation(PDAnnotation annotation) throws IOException {
    lastClips = null;
    if (shouldSkipAnnotation(annotation)) {
        return;
    }
    // TODO support NoZoom, example can be found in p5 of PDFBOX-2348
    PDAppearanceDictionary appearance = annotation.getAppearance();
    if ((appearance == null) || (appearance.getNormalAppearance() == null)) // PATH: Test should invoke the next PDAnnotationCircle.constructAppearances(...) [step in execution path]
    {
        annotation.constructAppearances(renderer.document);
    }
    if (annotation.isNoRotate() && (getCurrentPage().getRotation() != 0)) {
        appearance = annotation.getAppearance();
        if (appearance != null) {
            PDAppearanceEntry appearanceEntry = appearance.getNormalAppearance();
            if (((appearanceEntry != null) && appearanceEntry.isStream()) && hasTransparency(appearanceEntry.getAppearanceStream())) {
                // PDFBOX-4744: avoid appearances with transparency groups until we have fixed
                // the rendering. A real solution should probably be
                // in PDFStreamEngine.processAnnotation().
                annotation.constructAppearances();
            }
        }
        PDRectangle rect = annotation.getRectangle();
        AffineTransform savedTransform = graphics.getTransform();
        // "The upper-left corner of the annotation remains at the same point in
        // default user space; the annotation pivots around that point."
        graphics.rotate(Math.toRadians(getCurrentPage().getRotation()), rect.getLowerLeftX(), rect.getUpperRightY());
        super.showAnnotation(annotation);
        graphics.setTransform(savedTransform);
        annotation.setAppearance(appearance);// restore

    } else {
        super.showAnnotation(annotation);
    }
}

@Override
public void constructAppearances() // PATH: Test should invoke the next PDAnnotationCircle.constructAppearances(...) [step in execution path]
{
    this.constructAppearances(null);
}

@Override
public void constructAppearances(PDDocument document) {
    if (customAppearanceHandler == null) {
        PDCircleAppearanceHandler appearanceHandler = new PDCircleAppearanceHandler(this, document);
        appearanceHandler.generateAppearanceStreams();
    } else {
        customAppearanceHandler.generateAppearanceStreams();
    }
}

