/**
 * Draws the page to the requested context.
 *
 * @param g
 * 		The graphics context to draw onto.
 * @param pageSize
 * 		The size of the page to draw.
 * @throws IOException
 * 		If there is an IO error while drawing the page.
 */
public void drawPage(Graphics2D g, PDRectangle pageSize) throws IOException {
    graphics = g;
    xform = graphics.getTransform();
    Matrix m = new Matrix(xform);
    xformScalingFactorX = Math.abs(m.getScalingFactorX());
    xformScalingFactorY = Math.abs(m.getScalingFactorY());
    initialClip = graphics.getClip();
    this.pageSize = pageSize;
    setRenderingHints();
    graphics.translate(0, pageSize.getHeight());
    graphics.scale(1, -1);
    // adjust for non-(0,0) crop box
    graphics.translate(-pageSize.getLowerLeftX(), -pageSize.getLowerLeftY());
    processPage(getPage());
    for (PDAnnotation annotation : getPage().getAnnotations(annotationFilter)) // PATH: Test should invoke the next PageDrawer.showAnnotation(...) [step in execution path]
    {
        showAnnotation(annotation);
    }
    graphics = null;
}

@Override
public void showAnnotation(PDAnnotation annotation) throws IOException {
    lastClips = null;
    if (shouldSkipAnnotation(annotation)) {
        return;
    }
    // TODO support NoZoom, example can be found in p5 of PDFBOX-2348
    PDAppearanceDictionary appearance = annotation.getAppearance();
    if ((appearance == null) || (appearance.getNormalAppearance() == null)) // PATH: Test should invoke the next PDAnnotationFileAttachment.constructAppearances(...) [step in execution path]
    {
        annotation.constructAppearances(renderer.document);
    }
    if (annotation.isNoRotate() && (getCurrentPage().getRotation() != 0)) {
        appearance = annotation.getAppearance();
        if (appearance != null) {
            PDAppearanceEntry appearanceEntry = appearance.getNormalAppearance();
            if (((appearanceEntry != null) && appearanceEntry.isStream()) && hasTransparency(appearanceEntry.getAppearanceStream())) {
                // PDFBOX-4744: avoid appearances with transparency groups until we have fixed
                // the rendering. A real solution should probably be
                // in PDFStreamEngine.processAnnotation().
                annotation.constructAppearances();
            }
        }
        PDRectangle rect = annotation.getRectangle();
        AffineTransform savedTransform = graphics.getTransform();
        // "The upper-left corner of the annotation remains at the same point in
        // default user space; the annotation pivots around that point."
        graphics.rotate(Math.toRadians(getCurrentPage().getRotation()), rect.getLowerLeftX(), rect.getUpperRightY());
        super.showAnnotation(annotation);
        graphics.setTransform(savedTransform);
        annotation.setAppearance(appearance);// restore

    } else {
        super.showAnnotation(annotation);
    }
}

@Override
public void constructAppearances() // PATH: Test should invoke the next PDAnnotationFileAttachment.constructAppearances(...) [step in execution path]
{
    this.constructAppearances(null);
}

@Override
public void constructAppearances(PDDocument document) {
    if (customAppearanceHandler == null) // PATH: Test should invoke the next PDAppearanceHandler.generateAppearanceStreams(...) [step in execution path]
    {
        PDFileAttachmentAppearanceHandler appearanceHandler = new PDFileAttachmentAppearanceHandler(this, document);
        appearanceHandler.generateAppearanceStreams();
    } else {
        customAppearanceHandler.generateAppearanceStreams();
    }
}

default void generateAppearanceStreams() // PATH: Test should invoke the next PDCircleAppearanceHandler.generateNormalAppearance(...) [step in execution path]
{
    generateNormalAppearance();
    generateRolloverAppearance();
    generateDownAppearance();
}

@Override
public void generateNormalAppearance() {
    float lineWidth = getLineWidth();
    PDAnnotationCircle annotation = ((PDAnnotationCircle) (getAnnotation()));
    try (PDAppearanceContentStream contentStream = getNormalAppearanceAsContentStream()) {
        boolean hasStroke = contentStream.setStrokingColorOnDemand(getColor());
        boolean hasBackground = contentStream.setNonStrokingColorOnDemand(annotation.getInteriorColor());
        setOpacity(contentStream, annotation.getConstantOpacity());
        contentStream.setBorderLine(lineWidth, annotation.getBorderStyle(), annotation.getBorder());
        PDBorderEffectDictionary borderEffect = annotation.getBorderEffect();
        if ((borderEffect != null) && borderEffect.getStyle().equals(PDBorderEffectDictionary.STYLE_CLOUDY)) {
            CloudyBorder cloudyBorder = new CloudyBorder(contentStream, borderEffect.getIntensity(), lineWidth, getRectangle());
            cloudyBorder.createCloudyEllipse(annotation.getRectDifference());
            annotation.setRectangle(cloudyBorder.getRectangle());
            annotation.setRectDifference(cloudyBorder.getRectDifference());
            PDAppearanceStream appearanceStream = annotation.getNormalAppearanceStream();
            appearanceStream.setBBox(cloudyBorder.getBBox());
            appearanceStream.setMatrix(cloudyBorder.getMatrix());
        } else {
            // Acrobat applies a padding to each side of the bbox so the line is completely within
            // the bbox.
            PDRectangle borderBox = handleBorderBox(annotation, lineWidth);
            // lower left corner
            float x0 = borderBox.getLowerLeftX();
            float y0 = borderBox.getLowerLeftY();
            // upper right corner
            float x1 = borderBox.getUpperRightX();
            float y1 = borderBox.getUpperRightY();
            // mid points
            float xm = x0 + (borderBox.getWidth() / 2);
            float ym = y0 + (borderBox.getHeight() / 2);
            // see http://spencermortensen.com/articles/bezier-circle/
            // the below number was calculated from sampling content streams
            // generated using Adobe Reader
            float magic = 0.55555415F;
            // control point offsets
            float vOffset = (borderBox.getHeight() / 2) * magic;
            float hOffset = (borderBox.getWidth() / 2) * magic;
            contentStream.moveTo(xm, y1);
            contentStream.curveTo(xm + hOffset, y1, x1, ym + vOffset, x1, ym);
            contentStream.curveTo(x1, ym - vOffset, xm + hOffset, y0, xm, y0);
            contentStream.curveTo(xm - hOffset, y0, x0, ym - vOffset, x0, ym);
            contentStream.curveTo(x0, ym + vOffset, xm - hOffset, y1, xm, y1);
            contentStream.closePath();
        }
        contentStream.drawShape(lineWidth, hasStroke, hasBackground);
    } catch (IOException e) // PATH: Test should invoke the next Log.error(...) [step in execution path]
    {
        LOG.error(e);
    }
}

