/**
 * Process the given annotation with the specified appearance stream.
 *
 * @param annotation
 * 		The annotation containing the appearance stream to process.
 * @param appearance
 * 		The appearance stream to process.
 * @throws IOException
 * 		If there is an error reading or parsing the appearance content stream.
 */
protected void processAnnotation(PDAnnotation annotation, PDAppearanceStream appearance) throws IOException {
    PDRectangle bbox = appearance.getBBox();
    PDRectangle rect = annotation.getRectangle();
    // zero-sized rectangles are not valid
    if ((((((rect != null) && (rect.getWidth() > 0)) && (rect.getHeight() > 0)) && (bbox != null)) && (bbox.getWidth() > 0)) && (bbox.getHeight() > 0)) {
        PDResources parent = pushResources(appearance);
        Deque<PDGraphicsState> savedStack = saveGraphicsStack();
        Matrix matrix = appearance.getMatrix();
        // transformed appearance box  fixme: may be an arbitrary shape
        Rectangle2D transformedBox = bbox.transform(matrix).getBounds2D();
        // compute a matrix which scales and translates the transformed appearance box to align
        // with the edges of the annotation's rectangle
        Matrix a = Matrix.getTranslateInstance(rect.getLowerLeftX(), rect.getLowerLeftY());
        a.scale(((float) (rect.getWidth() / transformedBox.getWidth())), ((float) (rect.getHeight() / transformedBox.getHeight())));
        a.translate(((float) (-transformedBox.getX())), ((float) (-transformedBox.getY())));
        // Matrix shall be concatenated with A to form a matrix AA that maps from the appearance's
        // coordinate system to the annotation's rectangle in default user space
        // 
        // HOWEVER only the opposite order works for rotated pages with
        // filled fields / annotations that have a matrix in the appearance stream, see PDFBOX-3083
        Matrix aa = Matrix.concatenate(a, matrix);
        // make matrix AA the CTM
        getGraphicsState().setCurrentTransformationMatrix(aa);
        // clip to bounding box
        clipToRect(bbox);
        // needed for patterns in appearance streams, e.g. PDFBOX-2182
        initialMatrix = aa.clone();
        try // PATH: Test should invoke the next PDFStreamEngine.processStreamOperators(...) [step in execution path]
        {
            processStreamOperators(appearance);
        } finally {
            restoreGraphicsStack(savedStack);
            popResources(parent);
        }
    }
}

/**
 * Processes the operators of the given content stream.
 *
 * @param contentStream
 * 		to content stream to parse.
 * @throws IOException
 * 		if there is an error reading or parsing the content stream.
 */
private void processStreamOperators(PDContentStream contentStream) throws IOException {
    List<COSBase> arguments = new ArrayList<>();
    PDFStreamParser parser = new PDFStreamParser(contentStream);
    Object token = parser.parseNextToken();
    boolean isFirstOperator = true;
    boolean oldShouldProcessColorOperators = shouldProcessColorOperators;
    shouldProcessColorOperators = true;
    if ((contentStream instanceof PDTilingPattern) && (((PDTilingPattern) (contentStream)).getPaintType() == PDTilingPattern.PAINT_UNCOLORED)) {
        shouldProcessColorOperators = false;
    }
    try {
        while (token != null) {
            if (token instanceof Operator) // PATH: Test should invoke the next PDFStreamEngine.processOperator(...) [step in execution path]
            {
                if ((isFirstOperator && (contentStream instanceof PDType3CharProc)) && OperatorName.TYPE3_D1.equals(((Operator) (token)).getName())) {
                    shouldProcessColorOperators = false;
                }
                isFirstOperator = false;
                processOperator(((Operator) (token)), arguments);
                arguments.clear();
            } else {
                arguments.add(((COSBase) (token)));
            }
            token = parser.parseNextToken();
        } 
    } finally {
        shouldProcessColorOperators = oldShouldProcessColorOperators;
    }
}

/**
 * This is used to handle an operation.
 *
 * @param operator
 * 		The operation to perform.
 * @param operands
 * 		The list of arguments.
 * @throws IOException
 * 		If there is an error processing the operation.
 */
protected void processOperator(Operator operator, List<COSBase> operands) throws IOException {
    String name = operator.getName();
    OperatorProcessor processor = operators.get(name);
    if (processor != null) {
        try // PATH: Test should invoke the next LineTo.process(...) [step in execution path]
        {
            processor.process(operator, operands);
        } catch (IOException e) {
            operatorException(operator, operands, e);
        }
    } else {
        unsupportedOperator(operator, operands);
    }
}

@Override
public void process(Operator operator, List<COSBase> operands) throws IOException {
    if (operands.size() < 2) {
        throw new MissingOperandException(operator, operands);
    }
    COSBase base0 = operands.get(0);
    if (!(base0 instanceof COSNumber)) {
        return;
    }
    COSBase base1 = operands.get(1);
    if (!(base1 instanceof COSNumber)) {
        return;
    }
    // append straight line segment from the current point to the point
    COSNumber x = ((COSNumber) (base0));
    COSNumber y = ((COSNumber) (base1));
    PDFGraphicsStreamEngine context = getGraphicsContext();
    Point2D.Float pos = context.transformedPoint(x.floatValue(), y.floatValue());
    if (context.getCurrentPoint() == null) {
        LOG.warn(((("LineTo (" + pos.x) + ",") + pos.y) + ") without initial MoveTo");
        context.moveTo(pos.x, pos.y);
    } else {
        context.lineTo(pos.x, pos.y);
    }
}

