@Override
public int print(Graphics graphics, PageFormat pageFormat, int pageIndex) throws PrinterException {
    if ((pageIndex < 0) || (pageIndex >= pageTree.getCount())) {
        return NO_SUCH_PAGE;
    }
    try // PATH: Test should invoke the next PDFRenderer.renderPageToGraphics(...) [step in execution path]
    {
        Graphics2D graphics2D = ((Graphics2D) (graphics));
        // capture the DPI that will be used for rasterizing the image
        // if rasterizing is specified
        float rasterDpi = dpi;
        if (rasterDpi == RASTERIZE_DPI_AUTO) {
            rasterDpi = ((float) (graphics2D.getTransform().getScaleX())) * 72.0F;
            LOG.debug("auto raster dpi: " + rasterDpi);
        }
        PDPage page = pageTree.get(pageIndex);
        PDRectangle cropBox = getRotatedCropBox(page);
        // the imageable area is the area within the page margins
        final double imageableWidth = pageFormat.getImageableWidth();
        final double imageableHeight = pageFormat.getImageableHeight();
        double scale = 1;
        if (scaling != Scaling.ACTUAL_SIZE) {
            // scale to fit
            double scaleX = imageableWidth / cropBox.getWidth();
            double scaleY = imageableHeight / cropBox.getHeight();
            scale = Math.min(scaleX, scaleY);
            // only shrink to fit when enabled
            if ((scale > 1) && (scaling == Scaling.SHRINK_TO_FIT)) {
                scale = 1;
            }
            // only stretch to fit when enabled
            if ((scale < 1) && (scaling == Scaling.STRETCH_TO_FIT)) {
                scale = 1;
            }
        }
        // set the graphics origin to the origin of the imageable area (i.e the margins)
        graphics2D.translate(pageFormat.getImageableX(), pageFormat.getImageableY());
        // center on page
        if (center) {
            double dx = (imageableWidth - (cropBox.getWidth() * scale)) / 2;
            double dy = (imageableHeight - (cropBox.getHeight() * scale)) / 2;
            if ((dx >= 0) && (dy >= 0)) {
                graphics2D.translate(dx, dy);
            } else {
                // PDFBOX-3117 and https://lists.apache.org/thread/12s9tc93ofgmjfq1dpqfps9p725l0wwr
                LOG.warn(((("Centering disabled because of negative translation value (" + dx) + ",") + dy) + ")");
            }
        }
        // rasterize to bitmap (optional)
        Graphics2D printerGraphics = null;
        BufferedImage image = null;
        if ((dpi > 0) || (dpi == RASTERIZE_DPI_AUTO)) {
            if (LOG.isDebugEnabled()) {
                LOG.debug("dpi set to " + rasterDpi);
            }
            float dpiScale = rasterDpi / 72;
            image = new BufferedImage(((int) ((imageableWidth * dpiScale) / scale)), ((int) ((imageableHeight * dpiScale) / scale)), BufferedImage.TYPE_INT_ARGB);
            printerGraphics = graphics2D;
            graphics2D = image.createGraphics();
            // rescale
            printerGraphics.scale(scale / dpiScale, scale / dpiScale);
            scale = dpiScale;
        }
        // draw to graphics using PDFRender
        AffineTransform transform = graphics2D.getTransform();
        graphics2D.setBackground(Color.WHITE);
        renderer.setSubsamplingAllowed(subsamplingAllowed);
        renderer.setRenderingHints(renderingHints);
        renderer.renderPageToGraphics(pageIndex, graphics2D, ((float) (scale)), ((float) (scale)), RenderDestination.PRINT);
        // draw crop box
        if (showPageBorder) {
            graphics2D.setTransform(transform);
            graphics2D.setClip(0, 0, ((int) (imageableWidth)), ((int) (imageableHeight)));
            graphics2D.scale(scale, scale);
            graphics2D.setColor(Color.GRAY);
            graphics2D.setStroke(new BasicStroke(0.5F));
            graphics.drawRect(0, 0, ((int) (cropBox.getWidth())), ((int) (cropBox.getHeight())));
        }
        // draw rasterized bitmap (optional)
        if (printerGraphics != null) {
            printerGraphics.setBackground(Color.WHITE);
            printerGraphics.clearRect(0, 0, image.getWidth(), image.getHeight());
            printerGraphics.drawImage(image, 0, 0, null);
            graphics2D.dispose();
        }
        return PAGE_EXISTS;
    } catch (IOException e) {
        throw new PrinterIOException(e);
    }
}

/**
 * Renders a given page to an AWT Graphics2D instance.
 * <p>
 * Known problems:
 * <ul>
 * <li>rendering of PDF files with transparencies is not supported on Ubuntu, see
 * <a href="https://issues.apache.org/jira/browse/PDFBOX-4581">PDFBOX-4581</a> and
 * <a href="https://bugs.openjdk.java.net/browse/JDK-6689349">JDK-6689349</a>. Rendering will
 * not abort, but the pages will be rendered incorrectly.</li>
 * <li>Clipping the Graphics2D will not work properly, see
 * <a href="https://issues.apache.org/jira/browse/PDFBOX-4583">PDFBOX-4583</a>.</li>
 * </ul>
