/**
 * Returns the packed RGB value for this color, if any.
 *
 * @return RGB
 * @throws IOException
 * 		if the color conversion fails
 * @throws UnsupportedOperationException
 * 		if this color value is a pattern.
 */
public int toRGB() throws IOException {
    // PATH: Test should invoke the next PDSeparation.toRGB(...) [step in execution path]
    float[] floats = colorSpace.toRGB(components);
    int r = Math.round(floats[0] * 255);
    int g = Math.round(floats[1] * 255);
    int b = Math.round(floats[2] * 255);
    int rgb = r;
    rgb = (rgb << 8) + g;
    rgb = (rgb << 8) + b;
    return rgb;
}

@Override
public float[] toRGB(float[] value) throws IOException {
    if (toRGBMap == null) {
        toRGBMap = new HashMap<>();
    }
    int key = ((int) (value[0] * 255));
    float[] retval = toRGBMap.get(key);
    if (retval != null) {
        return retval;
    }
    // PATH: Test should invoke the next PDFunctionType0.eval(...) [step in execution path]
    float[] altColor = tintTransform.eval(value);
    retval = alternateColorSpace.toRGB(altColor);
    toRGBMap.put(key, retval);
