/**
 * Creates a PDColor containing the given color value.
 *
 * @param array
 * 		a COS array containing the color value
 * @param colorSpace
 * 		color space in which the color value is defined
 */
public PDColor(COSArray array, PDColorSpace colorSpace) {
    if ((array.size() > 0) && (array.get(array.size() - 1) instanceof COSName)) {
        // color components (optional), for the color of an uncoloured tiling pattern
        components = new float[array.size() - 1];
        initComponents(array);
        // pattern name (required)
        COSBase base = array.get(array.size() - 1);
        if (base instanceof COSName) {
            patternName = ((COSName) (base));
        } else {
            LOG.warn(("pattern name in " + array) + " isn't a name, ignored");
            patternName = COSName.getPDFName("Unknown");
        }
    } else {
        // color components only
        components = new float[array.size()];
        initComponents(array);
        patternName = null;
    }
    this.colorSpace = colorSpace;
}

/**
 * Creates a PDColor containing the given color component values.
 *
 * @param components
 * 		array of color component values
 * @param colorSpace
 * 		color space in which the components are defined
 */
public PDColor(float[] components, PDColorSpace colorSpace) {
    this.components = components.clone();
    this.patternName = null;
    this.colorSpace = colorSpace;
    if ((colorSpace != null) && (colorSpace.getNumberOfComponents() != components.length)) {
        // PDFBOX-5882
        LOG.warn((("Colorspace component count " + colorSpace.getNumberOfComponents()) + " doesn't match components length ") + components.length);
    }
}

/**
 * Creates a PDColor containing the given pattern name.
 *
 * @param patternName
 * 		the name of a pattern in a pattern dictionary
 * @param colorSpace
 * 		color space in which the pattern is defined
 */
public PDColor(COSName patternName, PDColorSpace colorSpace) {
    this.components = new float[0];
    this.patternName = patternName;
    this.colorSpace = colorSpace;
}

/**
 * Creates a PDColor containing the given color component values and pattern name.
 *
 * @param components
 * 		array of color component values
 * @param patternName
 * 		the name of a pattern in a pattern dictionary
 * @param colorSpace
 * 		color space in which the pattern/components are defined
 */
public PDColor(float[] components, COSName patternName, PDColorSpace colorSpace) {
    this.components = components.clone();
    this.patternName = patternName;
    this.colorSpace = colorSpace;
    if (colorSpace instanceof PDPattern) {
        PDColorSpace ucs = ((PDPattern) (colorSpace)).getUnderlyingColorSpace();
        if ((ucs != null) && (ucs.getNumberOfComponents() != components.length)) {
            // PDFBOX-5882
            LOG.warn((("Pattern colorspace component count " + ucs.getNumberOfComponents()) + " doesn't match components length ") + components.length);
        }
    }
}

