        array.toList().stream().map(o -> o instanceof COSObject ? ((COSObject) (o)).getObject() : o).filter(COSStream.class::isInstance).map(b -> ((COSStream) (b))).collect(Collectors.toList());
        List<RandomAccessRead> inputStreams = new ArrayList<>();
