/**
 * This will parse the stream and populate the FDFDocument object.
 *
 * @return the parsed FDFDocument
 * @throws IOException
 * 		If there is an error reading from the stream or corrupt data is found.
 */
public FDFDocument parse() throws IOException {
    // set to false if all is processed
    boolean exceptionOccurred = true;
    try // PATH: Test should invoke the next FDFParser.initialParse(...) [step in execution path]
    {
        if (!parseFDFHeader()) {
            throw new IOException("Error: Header doesn't contain versioninfo");
        }
        initialParse();
        exceptionOccurred = false;
        return new FDFDocument(document, source);
    } finally {
        if (exceptionOccurred && (document != null)) {
