/**
 * This will flatten the specified form fields.
 *
 * <p>
 * Flattening a form field will take the current appearance and make that part of the pages content stream. All form
 * fields and annotations associated are removed.
 * </p>
 *
 * <p>
 * Invisible and hidden fields will be skipped and will not become part of the page content stream
 * </p>
 *
 * @param fields
 * 		a list of fields to be flattened
 * @param refreshAppearances
 * 		if set to true the appearances for the form field widgets will be updated
 * @throws IOException
 * 		if something went wrong flattening the fields
 */
public void flatten(List<PDField> fields, boolean refreshAppearances) throws IOException {
    // Nothing to flatten if there are no fields provided
    if (fields.isEmpty()) {
        return;
    }
    if ((!refreshAppearances) && getNeedAppearances()) {
        LOG.warn("acroForm.getNeedAppearances() returns true, " + "visual field appearances may not have been set");
        LOG.warn("call acroForm.refreshAppearances() or " + "use the flatten() method with refreshAppearances parameter");
    }
    // for dynamic XFA forms there is no flatten as this would mean to do a rendering
    // from the XFA content into a static PDF.
    if (xfaIsDynamic()) {
        LOG.warn("Flatten for a dynamix XFA form is not supported");
        return;
    }
    // refresh the appearances if set
    if (refreshAppearances) // PATH: Test should invoke the next PDAcroForm.refreshAppearances(...) [step in execution path]
    {
        refreshAppearances(fields);
    }
    PDPageTree pages = document.getPages();
    Map<COSDictionary, Set<COSDictionary>> pagesWidgetsMap = buildPagesWidgetsMap(fields, pages);
    // preserve all non widget annotations
    for (PDPage page : pages) {
        Set<COSDictionary> widgetsForPageMap = pagesWidgetsMap.get(page.getCOSObject());
        // indicates if the original content stream
        // has been wrapped in a q...Q pair.
        boolean isContentStreamWrapped = false;
        List<PDAnnotation> annotations = new ArrayList<>();
        for (PDAnnotation annotation : page.getAnnotations()) {
            if ((widgetsForPageMap == null) || (!widgetsForPageMap.contains(annotation.getCOSObject()))) {
                annotations.add(annotation);
            } else if (isVisibleAnnotation(annotation)) {
                try (PDPageContentStream contentStream = new PDPageContentStream(document, page, AppendMode.APPEND, true, !isContentStreamWrapped)) {
                    isContentStreamWrapped = true;
                    PDAppearanceStream appearanceStream = annotation.getNormalAppearanceStream();
                    PDFormXObject fieldObject = new PDFormXObject(appearanceStream.getCOSObject());
                    contentStream.saveGraphicsState();
                    // see https://stackoverflow.com/a/54091766/1729265 for an explanation
                    // of the steps required
                    // this will transform the appearance stream form object into the rectangle of the
                    // annotation bbox and map the coordinate systems
                    Matrix transformationMatrix = resolveTransformationMatrix(annotation, appearanceStream);
                    contentStream.transform(transformationMatrix);
                    contentStream.drawForm(fieldObject);
                    contentStream.restoreGraphicsState();
                }
            }
        }
        page.setAnnotations(annotations);
    }
    // remove the fields
    removeFields(fields);
    // remove XFA for hybrid forms
    dictionary.removeItem(COSName.XFA);
    // remove SigFlags if no signature left
    if (this.document.getSignatureDictionaries().isEmpty()) {
        this.getCOSObject().removeItem(COSName.SIG_FLAGS);
    }
}

/**
 * Refreshes the appearance streams and appearance dictionaries for the widget annotations of the specified fields.
 *
 * @param fields
 * 		a list of fields to be refreshed
 * @throws IOException
 * 		if the appearance streams could not be refreshed
 */
public void refreshAppearances(List<PDField> fields) throws IOException {
    for (PDField field : fields) {
        if (field instanceof PDTerminalField) // PATH: Test should invoke the next PDComboBox.constructAppearances(...) [step in execution path]
        {
            ((PDTerminalField) (field)).constructAppearances();
        }
    }
}

@Override
void constructAppearances() throws IOException {
    AppearanceGeneratorHelper apHelper;
    apHelper = new AppearanceGeneratorHelper(this);
    List<String> values = getValue();
    if (!values.isEmpty()) // PATH: Test should invoke the next AppearanceGeneratorHelper.setAppearanceValue(...) [step in execution path]
    {
        apHelper.setAppearanceValue(values.get(0));
    } else {
        apHelper.setAppearanceValue("");
    }
}

/**
 * This is the public method for setting the appearance stream.
 *
 * @param apValue
 * 		the String value which the appearance should represent
 * @throws IOException
 * 		If there is an error creating the stream.
 */
public void setAppearanceValue(String apValue) throws IOException {
    value = getFormattedValue(apValue);
    // Treat multiline field values in single lines as single lime values.
    // This is in line with how Adobe Reader behaves when entering text
    // interactively but NOT how it behaves when the field value has been
    // set programmatically and Reader is forced to generate the appearance
    // using PDAcroForm.setNeedAppearances
    // see PDFBOX-3911
    if ((field instanceof PDTextField) && (!((PDTextField) (field)).isMultiline())) {
        value = value.replaceAll("\\u000D\\u000A|[\\u000A\\u000B\\u000C\\u000D\\u0085\\u2028\\u2029]", " ");
    }
    for (PDAnnotationWidget widget : field.getWidgets()) {
        if (widget.getCOSObject().containsKey("PMD")) {
            LOG.warn(("widget of field " + field.getFullyQualifiedName()) + " is a PaperMetaData widget, no appearance stream created");
            continue;
        }
        // some fields have the /Da at the widget level if the
        // widgets differ in layout.
        PDDefaultAppearanceString acroFormAppearance = defaultAppearance;
        if (widget.getCOSObject().getDictionaryObject(COSName.DA) != null) {
            defaultAppearance = getWidgetDefaultAppearanceString(widget);
        }
        PDRectangle rect = widget.getRectangle();
        if (rect == null) {
            widget.getCOSObject().removeItem(COSName.AP);
            LOG.warn(("widget of field " + field.getFullyQualifiedName()) + " has no rectangle, no appearance stream created");
            continue;
        }
        PDAppearanceDictionary appearanceDict = widget.getAppearance();
        if (appearanceDict == null) {
            appearanceDict = new PDAppearanceDictionary();
            widget.setAppearance(appearanceDict);
        }
        PDAppearanceEntry appearance = appearanceDict.getNormalAppearance();
        // TODO support appearances other than "normal"
        PDAppearanceStream appearanceStream;
        if (isValidAppearanceStream(appearance)) {
            appearanceStream = appearance.getAppearanceStream();
        } else {
            appearanceStream = prepareNormalAppearanceStream(widget);
            appearanceDict.setNormalAppearance(appearanceStream);
            // TODO support appearances other than "normal"
        }
        PDAppearanceCharacteristicsDictionary appearanceCharacteristics = widget.getAppearanceCharacteristics();
        /* Adobe Acrobat always recreates the complete appearance stream if there is an appearance characteristics
        entry (the widget dictionaries MK entry). In addition if there is no content yet also create the appearance
        stream from the entries.
         */
        if ((appearanceCharacteristics != null) || (appearanceStream.getContentStream().getLength() == 0)) // PATH: Test should invoke the next AppearanceGeneratorHelper.initializeAppearanceContent(...) [step in execution path]
        {
            initializeAppearanceContent(widget, appearanceCharacteristics, appearanceStream);
        }
        setAppearanceContent(widget, appearanceStream);
        // restore the field level appearance
        defaultAppearance = acroFormAppearance;
    }
}

/**
 * Initialize the content of the appearance stream.
 *
 * Get settings like border style, border width and colors to be used to draw a rectangle and background color
 * around the widget
 *
 * @param widget
 * 		the field widget
 * @param appearanceCharacteristics
 * 		the appearance characteristics dictionary from the widget or
 * 		null
 * @param appearanceStream
 * 		the appearance stream to be used
 * @throws IOException
 * 		in case we can't write to the appearance stream
 */
private void initializeAppearanceContent(PDAnnotationWidget widget, PDAppearanceCharacteristicsDictionary appearanceCharacteristics, PDAppearanceStream appearanceStream) throws IOException {
    try (ByteArrayOutputStream output = new ByteArrayOutputStream();PDAppearanceContentStream contents = new PDAppearanceContentStream(appearanceStream, output)) {
        // TODO: support more entries like patterns, etc.
        if (appearanceCharacteristics != null) {
            PDColor backgroundColour = appearanceCharacteristics.getBackground();
            if (backgroundColour != null) {
                contents.setNonStrokingColor(backgroundColour);
                PDRectangle bbox = resolveBoundingBox(widget, appearanceStream);
                contents.addRect(bbox.getLowerLeftX(), bbox.getLowerLeftY(), bbox.getWidth(), bbox.getHeight());
                contents.fill();
            }
            float lineWidth = 0.0F;
            PDColor borderColour = appearanceCharacteristics.getBorderColour();
            if (borderColour != null) {
                contents.setStrokingColor(borderColour);
                lineWidth = 1.0F;
            }
            PDBorderStyleDictionary borderStyle = widget.getBorderStyle();
            if ((borderStyle != null) && (borderStyle.getWidth() > 0)) {
                lineWidth = borderStyle.getWidth();
            }
            if ((lineWidth > 0) && (borderColour != null)) {
                if (Float.compare(lineWidth, 1) != 0) {
                    contents.setLineWidth(lineWidth);
                }
                PDRectangle bbox = resolveBoundingBox(widget, appearanceStream);
                PDRectangle clipRect = applyPadding(bbox, Math.max(DEFAULT_PADDING, lineWidth / 2));
                contents.addRect(clipRect.getLowerLeftX(), clipRect.getLowerLeftY(), clipRect.getWidth(), clipRect.getHeight());
                contents.closeAndStroke();
            }
            // draw the dividers for a comb field
            if ((borderColour != null) && shallComb()) {
                int maxLen = ((PDTextField) (field)).getMaxLen();
                PDRectangle bbox = resolveBoundingBox(widget, appearanceStream);
                PDRectangle clipRect = applyPadding(bbox, Math.max(DEFAULT_PADDING, lineWidth / 2));
                float lowerLeft = clipRect.getLowerLeftX();
                float height = clipRect.getHeight();
                float combWidth = bbox.getWidth() / maxLen;
                for (int i = 0; i < (maxLen - 1); i++) {
                    contents.moveTo(combWidth + (combWidth * i), height);
                    contents.lineTo(combWidth + (combWidth * i), lowerLeft);
                }
                contents.closeAndStroke();
            }
        }
        writeToStream(output.toByteArray(), appearanceStream);
    }
}

