/**
 * Creates a new PDFont instance with the appropriate subclass.
 *
 * @param dictionary
 * 		a font dictionary
 * @param resourceCache
 * 		resource cache, only useful for type 3 fonts, can be null
 * @return a PDFont instance, based on the SubType entry of the dictionary
 * @throws IOException
 * 		if something goes wrong
 */
public static PDFont createFont(COSDictionary dictionary, ResourceCache resourceCache) throws IOException {
    COSName type = dictionary.getCOSName(COSName.TYPE, COSName.FONT);
    if (!COSName.FONT.equals(type)) {
        LOG.error(("Expected 'Font' dictionary but found '" + type.getName()) + "'");
    }
    COSName subType = dictionary.getCOSName(COSName.SUBTYPE);
    if (COSName.TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDType1Font(dictionary);
    } else if (COSName.MM_TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDMMType1Font(dictionary);
    } else if (COSName.TRUE_TYPE.equals(subType)) {
        return new PDTrueTypeFont(dictionary);
    } else if (COSName.TYPE3.equals(subType)) {
        return new PDType3Font(dictionary, resourceCache);
    } else if (COSName.TYPE0.equals(subType)) {
        COSDictionary fontDescriptor = getFontDescriptor(dictionary);
        FontType fontTypeFromFont = getFontTypeFromFont(fontDescriptor, subType);
        if (fontTypeFromFont != null) {
            COSDictionary descendantFont = getDescendantFont(dictionary);
            COSName descFontType = (descendantFont != null) ? descendantFont.getCOSName(COSName.SUBTYPE) : null;
            if ((descFontType != null) && (!fontTypeFromFont.isCIDSubtype(descFontType))) {
                fixType0Subtype(descendantFont, fontDescriptor, fontTypeFromFont.getSubtype());
            }
        }
        return new PDType0Font(dictionary);
    } else if (COSName.CID_FONT_TYPE0.equals(subType)) {
        throw new IOException("Type 0 descendant font not allowed");
    } else if (COSName.CID_FONT_TYPE2.equals(subType)) {
        throw new IOException("Type 2 descendant font not allowed");
    } else {
        // assuming Type 1 font (see PDFBOX-1988) because it seems that Adobe Reader does this
        // however, we may need more sophisticated logic perhaps looking at the FontFile
        LOG.warn(("Invalid font subtype '" + subType) + "'");
        return new PDType1Font(dictionary);
    }
}

/**
 * Constructor for reading a Type0 font from a PDF file.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @throws IOException
 * 		if the descendant font is missing.
 */
public (COSDictionary fontDictionary) throws IOException {
    this(fontDictionary);
    gsubData = GsubData.NO_DATA_FOUND;
    cmapLookup = null;
    COSArray descendantFonts = dict.getCOSArray(COSName.DESCENDANT_FONTS);
    if (descendantFonts == null) {
        throw new IOException("Missing descendant font array");
    }
    if (descendantFonts.size() == 0) {
        throw new IOException("Descendant font array is empty");
    }
    COSBase descendantFontDictBase = descendantFonts.getObject(0);
    if (!(descendantFontDictBase instanceof COSDictionary)) {
        throw new IOException("Missing descendant font dictionary");
    }
    if (!COSName.FONT.equals(((COSDictionary) (descendantFontDictBase)).getCOSName(COSName.TYPE, COSName.FONT))) {
        throw new IOException("Missing or wrong type in descendant font dictionary");
    }
    // PATH: Test should invoke the next PDFontFactory.createDescendantFont(...) [step in execution path]
    descendantFont = PDFontFactory.createDescendantFont(((COSDictionary) (descendantFontDictBase)), this);
    readEncoding();
    fetchCMapUCS2();
}

/**
 * Creates a new PDCIDFont instance with the appropriate subclass.
 *
 * @param dictionary
 * 		descendant font dictionary
 * @return a PDCIDFont instance, based on the SubType entry of the dictionary
 * @throws IOException
 * 		if something goes wrong
 */
static PDCIDFont createDescendantFont(COSDictionary dictionary, PDType0Font parent) throws IOException {
    COSName type = dictionary.getCOSName(COSName.TYPE, COSName.FONT);
    if (!COSName.FONT.equals(type)) {
        throw new IOException(("Expected 'Font' dictionary but found '" + type.getName()) + "'");
    }
    COSName subType = dictionary.getCOSName(COSName.SUBTYPE);
    if (COSName.CID_FONT_TYPE0.equals(subType)) {
        return new PDCIDFontType0(dictionary, parent);
    } else if (COSName.CID_FONT_TYPE2.equals(subType)) {
        return new PDCIDFontType2(dictionary, parent);
    } else {
        throw new IOException("Invalid font type: " + type);
    }
}

/**
 * Constructor.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @param parent
 * 		The parent font.
 * @param trueTypeFont
 * 		The true type font used to create the parent font
 * @throws IOException
 * 		if the font could not be read
 */
public (COSDictionary fontDictionary, PDType0Font parent, TrueTypeFont trueTypeFont) throws IOException {
    this(fontDictionary, parent);
    PDFontDescriptor fd = getFontDescriptor();
    if (trueTypeFont != null) {
        ttf = trueTypeFont;
        otf = ((trueTypeFont instanceof OpenTypeFont) && ((OpenTypeFont) (trueTypeFont)).isSupportedOTF()) ? ((OpenTypeFont) (trueTypeFont)) : null;
        isEmbedded = true;
        isDamaged = false;
    } else {
        boolean fontIsDamaged = false;
        TrueTypeFont ttfFont = null;
        PDStream stream = null;
        if (fd != null) {
            stream = fd.getFontFile2();
            if (stream == null) {
                stream = fd.getFontFile3();
            }
            if (stream == null) {
                // Acrobat looks in FontFile too, even though it is not in the spec, see PDFBOX-2599
                stream = fd.getFontFile();
            }
        }
        if (stream != null) {
            try {
                // embedded OTF or TTF
                RandomAccessRead view = stream.getCOSObject().createView();
                TTFParser ttfParser = getParser(view, true);
                ttfFont = ttfParser.parse(view);
                ttfFont.close();
            } catch (IOException e) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
            {
                fontIsDamaged = true;
                LOG.warn("Could not read embedded OTF for font " + getBaseFont(), e);
            }
            if ((ttfFont instanceof OpenTypeFont) && (!((OpenTypeFont) (ttfFont)).isSupportedOTF())) {
                // the OpenType font contains CFF2 outlines which are not supported yet
                ttfFont = null;
                fontIsDamaged = true;
                LOG.warn("Found an OpenType font using CFF2 outlines which are not supported " + fd.getFontName());
            }
        }
        isEmbedded = ttfFont != null;
        isDamaged = fontIsDamaged;
        if (ttfFont == null) {
            ttfFont = findFontOrSubstitute();
        }
        otf = ((ttfFont instanceof OpenTypeFont) && ((OpenTypeFont) (ttfFont)).isSupportedOTF()) ? ((OpenTypeFont) (ttfFont)) : null;
        ttf = ttfFont;
    }
    cmap = ttf.getUnicodeCmapLookup(false);
    cid2gid = readCIDToGIDMap();
}

