/**
 * This will write the pdf document. If signature should be created externally,
 * {@link #writeExternalSignature(byte[])} should be invoked to set signature after calling this method.
 *
 * @param doc
 * 		The document to write.
 * @param signInterface
 * 		class to be used for signing; {@code null} if external signing would be performed
 * 		or there will be no signing at all
 * @throws IOException
 * 		If an error occurs while generating the data.
 * @throws IllegalStateException
 * 		If the document has an encryption dictionary but no protection
 * 		policy.
 */
public void write(PDDocument doc, SignatureInterface signInterface) throws IOException {
    pdDocument = doc;
    COSDocument cosDoc = pdDocument.getDocument();
    COSDictionary trailer = cosDoc.getTrailer();
    if (incrementalUpdate) {
        trailer.toIncrement().exclude(trailer).forEach(base -> {
            objectsToWrite.add(base);
            if (base instanceof COSObject) {
                actualsAdded.add(((COSObject) (base)).getObject());
            } else {
                actualsAdded.add(base);
            }
        });
    }
    signatureInterface = signInterface;
    number = pdDocument.getDocument().getHighestXRefObjectNumber();
    if (incrementalUpdate) {
        prepareIncrement();
    }
    long idTime = (pdDocument.getDocumentId() == null) ? System.currentTimeMillis() : pdDocument.getDocumentId();
    // if the document says we should remove encryption, then we shouldn't encrypt
    if (doc.isAllSecurityToBeRemoved()) {
        willEncrypt = false;
        // also need to get rid of the "Encrypt" in the trailer so readers
        // don't try to decrypt a document which is not encrypted
        trailer.removeItem(COSName.ENCRYPT);
    } else if (pdDocument.getEncryption() != null) {
        if (!incrementalUpdate) // PATH: Test should invoke the next StandardSecurityHandler.prepareDocumentForEncryption(...) [step in execution path]
        {
            SecurityHandler<? extends ProtectionPolicy> securityHandler = pdDocument.getEncryption().getSecurityHandler();
            if (!securityHandler.hasProtectionPolicy()) {
                throw new IllegalStateException("PDF contains an encryption dictionary, please remove it with " + "setAllSecurityToBeRemoved() or set a protection policy with protect()");
            }
            securityHandler.prepareDocumentForEncryption(pdDocument);
        }
        willEncrypt = true;
    } else {
        willEncrypt = false;
    }
    COSArray idArray;
    boolean missingID = true;
    COSBase base = trailer.getDictionaryObject(COSName.ID);
    if (base instanceof COSArray) {
        idArray = ((COSArray) (base));
        if (idArray.size() == 2) {
            missingID = false;
        }
    } else {
        idArray = new COSArray();
    }
    if (missingID || incrementalUpdate) {
        MessageDigest sha256;
        try {
            sha256 = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            // should never happen
            throw new RuntimeException(e);
        }
        // algorithm says to use time/path/size/values in doc to generate the id.
        // we don't have path or size, so do the best we can
        sha256.update(Long.toString(idTime).getBytes(StandardCharsets.ISO_8859_1));
        COSDictionary info = trailer.getCOSDictionary(COSName.INFO);
        if (info != null) {
            for (COSBase cosBase : info.getValues()) {
                sha256.update(cosBase.toString().getBytes(StandardCharsets.ISO_8859_1));
            }
        }
        // reuse origin documentID if available as first value
        COSString firstID = (missingID) ? new COSString(sha256.digest()) : ((COSString) (idArray.get(0)));
        // it's ok to use the same ID for the second part if the ID is created for the first time
        COSString secondID = (missingID) ? firstID : new COSString(sha256.digest());
        idArray = new COSArray();
        idArray.add(firstID);
        idArray.add(secondID);
        trailer.setItem(COSName.ID, idArray);
    }
    cosDoc.accept(this);
    if (!incrementalUpdate) {
        cosDoc.setHighestXRefObjectNumber(number);
    }
}

/**
 * Prepare document for encryption.
 *
 * @param document
 * 		The document to encrypt.
 * @throws IOException
 * 		If there is an error accessing data.
 */
@Override
public void prepareDocumentForEncryption(PDDocument document) throws IOException {
    PDEncryption encryptionDictionary = document.getEncryption();
    if (encryptionDictionary == null) {
        encryptionDictionary = new PDEncryption();
    }
    int version = computeVersionNumber();
    int revision = computeRevisionNumber(version);
    encryptionDictionary.setFilter(FILTER);
    encryptionDictionary.setVersion(version);
    if ((version != REVISION_4) && (version != REVISION_5)) {
        // remove CF, StmF, and StrF entries that may be left from a previous encryption
        encryptionDictionary.removeV45filters();
    }
    encryptionDictionary.setRevision(revision);
    encryptionDictionary.setLength(getKeyLength());
    StandardProtectionPolicy protectionPolicy = getProtectionPolicy();
    String ownerPassword = protectionPolicy.getOwnerPassword();
    String userPassword = protectionPolicy.getUserPassword();
    if (ownerPassword == null) {
        ownerPassword = "";
    }
    if (userPassword == null) {
        userPassword = "";
    }
    // If no owner password is set, use the user password instead.
    if (ownerPassword.isEmpty()) {
        ownerPassword = userPassword;
    }
    int permissionInt = protectionPolicy.getPermissions().getPermissionBytes();
    encryptionDictionary.setPermissions(permissionInt);
    int length = getKeyLength() / 8;
    if (revision == REVISION_6) {
        // PDFBOX-4155
        ownerPassword = SaslPrep.saslPrepStored(ownerPassword);
        userPassword = SaslPrep.saslPrepStored(userPassword);
        prepareEncryptionDictRev6(ownerPassword, userPassword, encryptionDictionary, permissionInt);
    } else // PATH: Test should invoke the next StandardSecurityHandler.prepareEncryptionDictRev234(...) [step in execution path]
    {
        prepareEncryptionDictRev234(ownerPassword, userPassword, encryptionDictionary, permissionInt, document, revision, length);
    }
    document.setEncryptionDictionary(encryptionDictionary);
    document.getDocument().setEncryptionDictionary(encryptionDictionary.getCOSObject());
}

private void prepareEncryptionDictRev234(String ownerPassword, String userPassword, PDEncryption encryptionDictionary, int permissionInt, PDDocument document, int revision, int length) throws IOException {
    COSArray idArray = document.getDocument().getDocumentID();
    // check if the document has an id yet.  If it does not then generate one
    if ((idArray == null) || (idArray.size() < 2)) {
        MessageDigest md = MessageDigests.getMD5();
        BigInteger time = BigInteger.valueOf(System.currentTimeMillis());
        md.update(time.toByteArray());
        md.update(ownerPassword.getBytes(StandardCharsets.ISO_8859_1));
        md.update(userPassword.getBytes(StandardCharsets.ISO_8859_1));
        md.update(document.getDocument().toString().getBytes(StandardCharsets.ISO_8859_1));
        byte[] id = md.digest(this.toString().getBytes(StandardCharsets.ISO_8859_1));
        COSString idString = new COSString(id);
        idArray = new COSArray();
        idArray.add(idString);
        idArray.add(idString);
        document.getDocument().setDocumentID(idArray);
    }
    COSString id = ((COSString) (idArray.getObject(0)));
    byte[] ownerBytes = computeOwnerPassword(ownerPassword.getBytes(StandardCharsets.ISO_8859_1), userPassword.getBytes(StandardCharsets.ISO_8859_1), revision, length);
    // PATH: Test should invoke the next StandardSecurityHandler.computeUserPassword(...) [step in execution path]
    byte[] userBytes = computeUserPassword(userPassword.getBytes(StandardCharsets.ISO_8859_1), ownerBytes, permissionInt, id.getBytes(), revision, length, true);
    setEncryptionKey(computeEncryptedKeyRev234(userPassword.getBytes(StandardCharsets.ISO_8859_1), ownerBytes, permissionInt, id.getBytes(), true, length, revision));
    encryptionDictionary.setOwnerKey(ownerBytes);
    encryptionDictionary.setUserKey(userBytes);
    if (revision == REVISION_4) {
        prepareEncryptionDictAES(encryptionDictionary, COSName.AESV2);
    }
}

/**
 * This will compute the user password hash.
 *
 * @param password
 * 		The plain text password.
 * @param owner
 * 		The owner password hash.
 * @param permissions
 * 		The document permissions.
 * @param id
 * 		The document id.
 * @param encRevision
 * 		The revision of the encryption.
 * @param keyLengthInBytes
 * 		The length of the encryption key in bytes.
 * @param encryptMetadata
 * 		The encryption metadata
 * @return The user password.
 * @throws IOException
 * 		if the password could not be computed
 */
public byte[] computeUserPassword(byte[] password, byte[] owner, int permissions, byte[] id, int encRevision, int keyLengthInBytes, boolean encryptMetadata) throws IOException {
    // TODO!?!?
    if ((encRevision == REVISION_5) || (encRevision == REVISION_6)) {
        return new byte[0];
    }
    ByteArrayOutputStream result = new ByteArrayOutputStream();
    byte[] encKey = computeEncryptedKeyRev234(password, owner, permissions, id, encryptMetadata, keyLengthInBytes, encRevision);
    if (encRevision == REVISION_2) {
        encryptDataRC4(encKey, ENCRYPT_PADDING, result);
    } else if ((encRevision == REVISION_3) || (encRevision == REVISION_4)) {
        MessageDigest md = MessageDigests.getMD5();
        md.update(ENCRYPT_PADDING);
        md.update(id);
        result.write(md.digest());
        byte[] iterationKey = new byte[encKey.length];
        for (int i = 0; i < 20; i++) {
            System.arraycopy(encKey, 0, iterationKey, 0, iterationKey.length);
            for (int j = 0; j < iterationKey.length; j++) {
                iterationKey[j] = ((byte) (iterationKey[j] ^ i));
            }
            ByteArrayInputStream input = new ByteArrayInputStream(result.toByteArray());
            result.reset();
            encryptDataRC4(iterationKey, input, result);
        }
        byte[] finalResult = new byte[32];
        System.arraycopy(result.toByteArray(), 0, finalResult, 0, 16);
        System.arraycopy(ENCRYPT_PADDING, 0, finalResult, 16, 16);
        result.reset();
        result.write(finalResult);
    }
    return result.toByteArray();
}

