            return cached;
        }
    }
    initJPXValues();
    // get RGB image w/o reference because applyMask might modify it, take long time and a lot of memory.
    final BufferedImage image;
    final PDImageXObject softMask = getSoftMask();
    final PDImageXObject mask = getMask();
    if (jpxSMask != null) {
