        image = applyMask(SampledImageReader.getRGBImage(this, region, subsampling, getColorKeyMask()), jpxSMask, false, true, null);
    } else if (softMask != null) {
        image = applyMask(SampledImageReader.getRGBImage(this, region, subsampling, getColorKeyMask()), softMask.getOpaqueImage(region, subsampling), softMask.getInterpolate(), true, extractMatte(softMask));
    } else if ((mask != null) && mask.isStencil()) {
        image = applyMask(SampledImageReader.getRGBImage(this, region, subsampling, getColorKeyMask()), mask.getOpaqueImage(region, subsampling), mask.getInterpolate(), false, null);
    } else {
