 * is shown if the level is below 0. This can happen if the level is not decreased after an
 * operation is done, e.g. by using a "finally" block.
 */
public void decreaseLevel() {
    --level;
    if (level < 0) {
        LOG.error("level is " + level);
    }
}

/**
