 */
private void initPage(PDPage page) {
    if (page == null) {
        throw new IllegalArgumentException("Page cannot be null");
    }
    currentPage = page;
    graphicsStack.clear();
    graphicsStack.push(new PDGraphicsState(page.getCropBox()));
    resources = null;
    initialMatrix = page.getMatrix();
}

/**
