/**
 * This will parse the stream and populate the PDDocument object. This will close the keystore stream when it is
 * done parsing.
 *
 * @param lenient
 * 		activate leniency if set to true
 * @return the populated PDDocument
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If there is an error reading from the stream or corrupt data is found.
 */
public PDDocument parse(boolean lenient) throws IOException {
    setLenient(lenient);
    // set to false if all is processed
    boolean exceptionOccurred = true;
    try {
        // PDFBOX-1922 read the version header and rewind
        if ((!parsePDFHeader()) && (!parseFDFHeader())) {
            if (lenient) {
                LOG.warn("Error: Header doesn't contain versioninfo");
            } else {
                throw new IOException("Error: Header doesn't contain versioninfo");
            }
        }
        if (!initialParseDone) // PATH: Test should invoke the next PDFParser.initialParse(...) [step in execution path]
        {
            initialParse();
        }
        exceptionOccurred = false;
        PDDocument pdDocument = createDocument();
        pdDocument.setEncryptionDictionary(getEncryption());
        return pdDocument;
    } finally {
        if (exceptionOccurred && (document != null)) {
            IOUtils.closeQuietly(document);
            document = null;
        }
    }
}

/**
 * The initial parse will first parse only the trailer, the xrefstart and all xref tables to have a pointer (offset)
 * to all the pdf's objects. It can handle linearized pdfs, which will have an xref at the end pointing to an xref
 * at the beginning of the file. Last the root object is parsed.
 *
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If something went wrong.
 */
protected void initialParse() throws IOException {
    // PATH: Test should invoke the next COSParser.retrieveTrailer(...) [step in execution path]
    COSDictionary trailer = retrieveTrailer();
    COSDictionary root = trailer.getCOSDictionary(COSName.ROOT);
    if (root == null) {
        throw new IOException("Missing root object specification in trailer.");
    }
    // in some pdfs the type value "Catalog" is missing in the root object
    if (isLenient() && (!root.containsKey(COSName.TYPE))) {
        root.setItem(COSName.TYPE, COSName.CATALOG);
    }
    // check pages dictionaries
    checkPages(root);
    document.setDecrypted();
    initialParseDone = true;
}

/**
 * Read the trailer information and provide a COSDictionary containing the trailer information.
 *
 * @return a COSDictionary containing the trailer information
 * @throws IOException
 * 		if something went wrong
 */
protected COSDictionary retrieveTrailer() throws IOException {
    COSDictionary trailer = null;
    boolean rebuildTrailer = false;
    try {
        // parse startxref
        // TODO FDF files don't have a startxref value, so that rebuildTrailer is triggered
        long startXRefOffset = getStartxrefOffset();
        if (startXRefOffset > (-1)) {
            trailer = parseXref(startXRefOffset);
        } else {
            rebuildTrailer = isLenient();
        }
    } catch (IOException exception) {
        if (isLenient()) {
            rebuildTrailer = true;
        } else {
            throw exception;
        }
    }
    // check if the trailer contains a Root object
    if ((trailer != null) && (trailer.getItem(COSName.ROOT) == null)) {
        rebuildTrailer = isLenient();
    }
    if (rebuildTrailer) {
        // PATH: Test should invoke the next BruteForceParser.rebuildTrailer(...) [step in execution path]
        trailer = getBruteForceParser().rebuildTrailer(xrefTrailerResolver, null);
        trailerWasRebuild = true;
        // transfer encryption information from BruteForceParser
        encryption = getBruteForceParser().getEncryption();
        if (encryption != null) {
            securityHandler = encryption.getSecurityHandler();
            accessPermission = securityHandler.getCurrentAccessPermission();
        }
    } else {
        // prepare decryption if necessary
        prepareDecryption();
        // don't use the getter as it creates an instance of BruteForceParser
        if ((bruteForceParser != null) && bruteForceParser.bfSearchTriggered()) {
            getBruteForceParser().bfSearchForObjStreams(xrefTrailerResolver, securityHandler);
        }
    }
    if (resetTrailerResolver()) {
        xrefTrailerResolver.reset();
        xrefTrailerResolver = null;
    }
    return trailer;
}

/**
 * Rebuild the trailer dictionary if startxref can't be found.
 *
 * @param trailerResolver
 * 		the trailer resolver of the document
 * @param securityHandler
 * 		security handler to be used to decrypt encrypted documents
 * @return the rebuild trailer dictionary
 * @throws IOException
 * 		if something went wrong
 */
protected COSDictionary rebuildTrailer(XrefTrailerResolver trailerResolver, SecurityHandler<? extends ProtectionPolicy> securityHandler) throws IOException // PATH: Test should invoke the next COSParser.prepareDecryption(...) [step in execution path]
{
    // update security handler
    this.securityHandler = securityHandler;
    // reset trailer resolver
    trailerResolver.reset();
    // use the found objects to rebuild the trailer resolver
    trailerResolver.nextXrefObj(0, XRefType.TABLE);
    getBFCOSObjectOffsets().forEach(trailerResolver::setXRef);
    trailerResolver.setStartxref(0);
    // transfer xref-table to document
    document.getXrefTable().clear();
    document.addXRefTable(trailerResolver.getXrefTable());
    // remember the highest XRef object number to avoid it being reused in incremental saving
    Long maxValue = // 
    // 
    // 
    document.getXrefTable().keySet().stream().map(COSObjectKey::getNumber).reduce(Long::max).orElse(0L);
    document.setHighestXRefObjectNumber(maxValue);
    COSDictionary trailer = trailerResolver.getTrailer();
    document.setTrailer(trailer);
    boolean searchForObjStreamsDone = false;
    if ((!bfSearchForTrailer(trailer)) && (!searchForTrailerItems(trailer))) {
        // root entry wasn't found, maybe it is part of an object stream
        // brute force search for all object streams.
        bfSearchForObjStreams(trailerResolver, securityHandler);
        searchForObjStreamsDone = true;
        // search again for the root entry
        searchForTrailerItems(trailer);
    }
    // prepare decryption if necessary
    prepareDecryption();
    if (!searchForObjStreamsDone) {
        // brute force search for all object streams.
        bfSearchForObjStreams(trailerResolver, securityHandler);
    }
    return trailer;
}

/**
 * Prepare for decryption.
 *
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		if something went wrong
 */
protected void prepareDecryption() throws IOException {
    if (encryption != null) {
        return;
    }
    COSDictionary encryptionDictionary = document.getEncryptionDictionary();
    if (encryptionDictionary == null) {
        return;
    }
    try // PATH: Test should invoke the next StandardSecurityHandler.prepareForDecryption(...) [step in execution path]
    {
        encryption = new PDEncryption(encryptionDictionary);
        DecryptionMaterial decryptionMaterial;
        if (keyStoreInputStream != null) {
            KeyStore ks = KeyStore.getInstance("PKCS12");
            ks.load(keyStoreInputStream, password.toCharArray());
            decryptionMaterial = new PublicKeyDecryptionMaterial(ks, keyAlias, password);
        } else {
            decryptionMaterial = new StandardDecryptionMaterial(password);
        }
        securityHandler = encryption.getSecurityHandler();
        securityHandler.prepareForDecryption(encryption, document.getDocumentID(), decryptionMaterial);
        accessPermission = securityHandler.getCurrentAccessPermission();
    } catch (IOException e) {
        throw e;
    } catch (GeneralSecurityException e) {
        throw new IOException(("Error (" + e.getClass().getSimpleName()) + ") while creating security handler for decryption", e);
    } finally {
        if (keyStoreInputStream != null) {
            IOUtils.closeQuietly(keyStoreInputStream);
        }
    }
}

/**
 * Prepares everything to decrypt the document.
 *
 * Only if decryption of single objects is needed this should be called.
 *
 * @param encryption
 * 		encryption dictionary
 * @param documentIDArray
 * 		document id
 * @param decryptionMaterial
 * 		Information used to decrypt the document.
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If there is an error accessing data.
 */
@Override
public void prepareForDecryption(PDEncryption encryption, COSArray documentIDArray, DecryptionMaterial decryptionMaterial) throws IOException {
    if (!(decryptionMaterial instanceof StandardDecryptionMaterial)) {
        throw new IOException("Decryption material is not compatible with the document");
    }
    // This is only used with security version 4 and 5.
    if (encryption.getVersion() >= REVISION_4) {
        setStreamFilterName(encryption.getStreamFilterName());
        setStringFilterName(encryption.getStringFilterName());
    }
    setDecryptMetadata(encryption.isEncryptMetaData());
    StandardDecryptionMaterial material = ((StandardDecryptionMaterial) (decryptionMaterial));
    String password = material.getPassword();
    if (password == null) {
        password = "";
    }
    int dicPermissions = encryption.getPermissions();
    int dicRevision = encryption.getRevision();
    int dicLength = (encryption.getVersion() == 1) ? 5 : encryption.getLength() / 8;
    if ((encryption.getVersion() == REVISION_4) || (encryption.getVersion() == REVISION_5)) {
        // detect whether AES encryption is used. This assumes that the encryption algo is
        // stored in the PDCryptFilterDictionary
        // However, crypt filters are used only when V is 4 or 5.
        PDCryptFilterDictionary stdCryptFilterDictionary = encryption.getStdCryptFilterDictionary();
        if (stdCryptFilterDictionary != null) {
            COSName cryptFilterMethod = stdCryptFilterDictionary.getCryptFilterMethod();
            if (COSName.AESV2.equals(cryptFilterMethod)) {
                dicLength = 128 / 8;
                setAES(true);
                if (encryption.getCOSObject().containsKey(COSName.LENGTH)) {
                    // PDFBOX-5345
                    int newLength = encryption.getLength() / 8;
                    if (newLength < dicLength) {
                        LOG.warn(((("Using " + newLength) + " bytes key length instead of ") + dicLength) + " in AESV2 encryption?!");
                        dicLength = newLength;
                    }
                }
            }
            if (COSName.AESV3.equals(cryptFilterMethod)) {
                dicLength = 256 / 8;
                setAES(true);
                if (encryption.getCOSObject().containsKey(COSName.LENGTH)) {
                    // PDFBOX-5345
                    int newLength = encryption.getLength() / 8;
                    if (newLength < dicLength) {
                        LOG.warn(((("Using " + newLength) + " bytes key length instead of ") + dicLength) + " in AESV3 encryption?!");
                        dicLength = newLength;
                    }
                }
            }
        }
    }
    byte[] documentIDBytes = getDocumentIDBytes(documentIDArray);
    // we need to know whether the meta data was encrypted for password calculation
    boolean encryptMetadata = encryption.isEncryptMetaData();
    byte[] userKey = encryption.getUserKey();
    byte[] ownerKey = encryption.getOwnerKey();
    byte[] ue = null;
    byte[] oe = null;
    Charset passwordCharset = StandardCharsets.ISO_8859_1;
    if ((dicRevision == REVISION_5) || (dicRevision == REVISION_6)) {
        passwordCharset = StandardCharsets.UTF_8;
        ue = encryption.getUserEncryptionKey();
        oe = encryption.getOwnerEncryptionKey();
    }
    if (dicRevision == REVISION_6) {
        password = SaslPrep.saslPrepQuery(password);// PDFBOX-4155

    }
    AccessPermission currentAccessPermission;
    byte[] encryptedKey;
    byte[] passwordBytes;
    boolean isOwnerPassword;
    if (isOwnerPassword(password.getBytes(passwordCharset), userKey, ownerKey, dicPermissions, documentIDBytes, dicRevision, dicLength, encryptMetadata)) {
        currentAccessPermission = AccessPermission.getOwnerAccessPermission();
        setCurrentAccessPermission(currentAccessPermission);
        if ((dicRevision == REVISION_5) || (dicRevision == REVISION_6)) {
            passwordBytes = password.getBytes(passwordCharset);
        } else {
            passwordBytes = getUserPassword234(password.getBytes(passwordCharset), ownerKey, dicRevision, dicLength);
        }
        isOwnerPassword = true;
    } else if (isUserPassword(password.getBytes(passwordCharset), userKey, ownerKey, dicPermissions, documentIDBytes, dicRevision, dicLength, encryptMetadata)) {
        currentAccessPermission = new AccessPermission(dicPermissions);
        currentAccessPermission.setReadOnly();
        setCurrentAccessPermission(currentAccessPermission);
        passwordBytes = password.getBytes(passwordCharset);
        isOwnerPassword = false;
    } else {
        throw new InvalidPasswordException("Cannot decrypt PDF, the password is incorrect");
    }
    encryptedKey = computeEncryptedKey(passwordBytes, ownerKey, userKey, oe, ue, dicPermissions, documentIDBytes, dicRevision, dicLength, encryptMetadata, isOwnerPassword);
    if ((dicRevision == REVISION_4) && (encryptedKey.length < 16)) // PATH: Test should invoke the next Log.info(...) [step in execution path]
    {
        LOG.info("PDFBOX-5955: padding RC4 key to length 16");
        encryptedKey = Arrays.copyOf(encryptedKey, 16);
    }
    setEncryptionKey(encryptedKey);
    if ((dicRevision == REVISION_5) || (dicRevision == REVISION_6)) {
        validatePerms(encryption, dicPermissions, encryptMetadata);
    }
}

