/**
 * Loads a TTF to be embedded and subset into a document as a Type 0 font. If you are loading a
 * font for AcroForm, then use the 3-parameter constructor instead.
 *
 * @param doc
 * 		The PDF document that will hold the embedded font.
 * @param file
 * 		A TrueType font.
 * @return A Type0 font with a CIDFontType2 descendant.
 * @throws IOException
 * 		If there is an error reading the font file.
 */
public static PDType0Font load(PDDocument doc, File file) throws IOException {
    // PATH: Test should invoke the next PDType0Font.load(...) [step in execution path]
    return PDType0Font.load(doc, new RandomAccessReadBufferedFile(file), true, false);
}

/**
 * Private. Creates a new PDType0Font font for embedding.
 *
 * @param document
 * @param ttf
 * @param embedSubset
 * @param closeTTF
 * 		whether to close the ttf parameter after embedding. Must be true when the ttf
 * 		parameter was created in the load() method, false when the ttf parameter was passed to the
 * 		load() method.
 * @param vertical
 * 		whether to enable vertical substitutions.
 * @throws IOException
 */
private (PDDocument document, TrueTypeFont ttf, boolean embedSubset, boolean closeTTF, boolean vertical) throws IOException {
    if (vertical) {
        ttf.enableVerticalSubstitutions();
    }
    gsubData = ttf.getGsubData();
    cmapLookup = ttf.getUnicodeCmapLookup();
    embedder = new PDCIDFontType2Embedder(document, dict, ttf, embedSubset, this, vertical);
    // PATH: Test should invoke the next new PDCIDFontType2Embedder(...) [step in execution path]
    descendantFont = embedder.getCIDFont();
    readEncoding();
    fetchCMapUCS2();
    if (closeTTF) {
        if (embedSubset) {
            this.ttf = ttf;
            document.registerTrueTypeFontForClosing(ttf);
        } else {
            // the TTF is fully loaded and it is safe to close the underlying data source
            ttf.close();
        }
    }
}

/**
 * Creates a new TrueType font embedder for the given TTF as a PDCIDFontType2.
 *
 * @param document
 * 		parent document
 * @param dict
 * 		font dictionary
 * @param ttf
 * 		True Type Font
 * @param parent
 * 		parent Type 0 font
 * @throws IOException
 * 		if the TTF could not be read
 */
(PDDocument document, COSDictionary dict, TrueTypeFont ttf, boolean embedSubset, PDType0Font parent, boolean vertical) throws IOException {
    this(document, dict, ttf, embedSubset);
    this.document = document;
    this.dict = dict;
    this.parent = parent;
    this.vertical = vertical;
    // parent Type 0 font
    dict.setItem(COSName.SUBTYPE, COSName.TYPE0);
    dict.setName(COSName.BASE_FONT, fontDescriptor.getFontName());
    dict.setItem(COSName.ENCODING, vertical ? COSName.IDENTITY_V : COSName.IDENTITY_H);// CID = GID

    // descendant CIDFont
    // PATH: Test should invoke the next PDCIDFontType2Embedder.createCIDFont(...) [step in execution path]
    cidFont = createCIDFont();
    COSArray descendantFonts = new COSArray();
    descendantFonts.add(cidFont);
    dict.setItem(COSName.DESCENDANT_FONTS, descendantFonts);
    if (!embedSubset) {
        // build GID -> Unicode map
        buildToUnicodeCMap(null);
    }
}

private COSDictionary createCIDFont() throws IOException {
    COSDictionary cidFont = new COSDictionary();
    // Type, Subtype
    cidFont.setItem(COSName.TYPE, COSName.FONT);
    cidFont.setItem(COSName.SUBTYPE, COSName.CID_FONT_TYPE2);
    // BaseFont
    cidFont.setName(COSName.BASE_FONT, fontDescriptor.getFontName());
    // CIDSystemInfo
    // PATH: Test should invoke the next PDCIDFontType2Embedder.toCIDSystemInfo(...) [step in execution path]
    COSDictionary info = toCIDSystemInfo("Adobe", "Identity", 0);
    cidFont.setItem(COSName.CIDSYSTEMINFO, info);
    // FontDescriptor
    cidFont.setItem(COSName.FONT_DESC, fontDescriptor.getCOSObject());
    // W - widths
    buildWidths(cidFont);
    // Vertical metrics
    if (vertical) {
        buildVerticalMetrics(cidFont);
    }
    // CIDToGIDMap
    cidFont.setItem(COSName.CID_TO_GID_MAP, COSName.IDENTITY);
    return cidFont;
}

private COSDictionary toCIDSystemInfo(String registry, String ordering, int supplement) {
    COSDictionary info = new COSDictionary();
    info.setString(COSName.REGISTRY, registry);
    info.setString(COSName.ORDERING, ordering);
    info.setInt(COSName.SUPPLEMENT, supplement);
    return info;
}

