    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    // PDFBOX-4985
    // build the visual appearance as there is none for the widgets
    if ((acroForm != null) && acroForm.getNeedAppearances()) // PATH: Test should invoke the next AcroFormGenerateAppearancesProcessor.process(...) [step in execution path]
