                        } else {
                            // interpolate to TYPE_BYTE
                            int outputByte = Math.round(((output - Math.min(dMin, dMax)) / Math.abs(dMax - dMin)) * 255.0F);
                            srcColorValues[c] = ((byte) (outputByte));
