/**
 * This is used to handle an operation.
 *
 * @param operator
 * 		The operation to perform.
 * @param operands
 * 		The list of arguments.
 * @throws IOException
 * 		If there is an error processing the operation.
 */
protected void processOperator(Operator operator, List<COSBase> operands) throws IOException {
    String name = operator.getName();
    OperatorProcessor processor = operators.get(name);
    if (processor != null) {
        try // PATH: Test should invoke the next StrokePath.process(...) [step in execution path]
        {
            processor.process(operator, operands);
        } catch (IOException e) {
            operatorException(operator, operands, e);
        }
    } else {
        unsupportedOperator(operator, operands);
    }
}

@Override
public void process(Operator operator, List<COSBase> operands) throws IOException // PATH: Test should invoke the next PageDrawer.strokePath(...) [step in execution path]
{
    getGraphicsContext().strokePath();
}

@Override
public void strokePath() throws IOException {
    if (isContentRendered()) {
        graphics.setComposite(getGraphicsState().getStrokingJavaComposite());
        // PATH: Test should invoke the next PageDrawer.getStrokingPaint(...) [step in execution path]
        graphics.setPaint(getStrokingPaint());
        graphics.setStroke(getStroke());
        setClip();
        graphics.draw(linePath);
    }
    linePath.reset();
}

// returns the stroking AWT Paint
private Paint getStrokingPaint() throws IOException {
    PDGraphicsState graphicsState = getGraphicsState();
    // PATH: Test should invoke the next PageDrawer.applySoftMaskToPaint(...) [step in execution path]
    return applySoftMaskToPaint(getPaint(graphicsState.getStrokingColor()), graphicsState.getSoftMask());
