/**
 * Creates a new COSInputStream from an encoded input stream.
 *
 * @param filters
 * 		Filters to be applied.
 * @param parameters
 * 		Filter parameters.
 * @param in
 * 		Encoded input stream.
 * @param options
 * 		decode options for the encoded stream
 * @return Decoded stream.
 * @throws IOException
 * 		If the stream could not be read.
 */
static COSInputStream create(List<Filter> filters, COSDictionary parameters, InputStream in, DecodeOptions options) throws IOException {
    if (filters.isEmpty()) {
        return new COSInputStream(in, Collections.emptyList());
    }
    List<DecodeResult> results = new ArrayList<>(filters.size());
    // PATH: Test should invoke the next Filter.decode(...) [step in execution path]
    RandomAccessRead decoded = Filter.decode(in, filters, parameters, options, results);
    return new COSInputStream(new RandomAccessInputStream(decoded), results);
}

/**
 * Decodes data, with optional DecodeOptions. Not all filters support all options, and so callers should check the
 * options' <code>honored</code> flag to test if they were applied.
 *
 * @param encoded
 * 		the input stream holding the encoded data
 * @param filterList
 * 		list of filters to be used for decoding
 * @param parameters
 * 		the parameters used for decoding
 * @param options
 * 		additional options for decoding
 * @param results
 * 		list of optional decoding results for each filter
 * @return the decoded stream data
 * @throws IOException
 * 		if the stream cannot be decoded
 * @throws IllegalArgumentException
 * 		if filterList is empty
 */
public static RandomAccessRead decode(InputStream encoded, List<Filter> filterList, COSDictionary parameters, DecodeOptions options, List<DecodeResult> results) throws IOException {
    long length = parameters.getLong(COSName.LENGTH, RandomAccessReadBuffer.DEFAULT_CHUNK_SIZE_4KB);
    if (filterList.isEmpty()) {
        throw new IllegalArgumentException("Empty filterList");
    }
    if (filterList.size() > 1) {
        Set<Filter> filterSet = new HashSet<>(filterList);
        if (filterSet.size() != filterList.size()) {
            List<Filter> reducedFilterList = new ArrayList<>();
            for (Filter filter : filterList) {
                if (!reducedFilterList.contains(filter)) {
                    reducedFilterList.add(filter);
                }
            }
            // replace origin list with the reduced one
            filterList = reducedFilterList;
            LOG.warn("Removed duplicated filter entries");
        }
    }
    InputStream input = encoded;
    RandomAccessReadWriteBuffer randomAccessWriteBuffer = null;
    OutputStream output = null;
    // apply filters
    for (int i = 0; i < filterList.size(); i++) {
        if (i > 0) {
            randomAccessWriteBuffer.seek(0);
            input = new RandomAccessInputStream(randomAccessWriteBuffer);
            length = randomAccessWriteBuffer.length();
        }
        // we don't know the size of the decoded stream, just estimate a 4 times bigger size than the encoded stream
        // use the estimated stream size as chunk size, use the default chunk size as limit to avoid to big values
        if ((length <= 0) || (length >= (RandomAccessReadBuffer.DEFAULT_CHUNK_SIZE_4KB / 4))) {
            length = RandomAccessReadBuffer.DEFAULT_CHUNK_SIZE_4KB;
        } else {
            length = length * 4;
        }
        randomAccessWriteBuffer = new RandomAccessReadWriteBuffer(((int) (length)));
        output = new RandomAccessOutputStream(randomAccessWriteBuffer);
        try {
            // PATH: Test should invoke the next JBIG2Filter.decode(...) [step in execution path]
            DecodeResult result = filterList.get(i).decode(input, output, parameters, i, options);
            if (results != null) {
                results.add(result);
            }
        } finally {
            IOUtils.closeQuietly(input);
        }
    }
    randomAccessWriteBuffer.seek(0);
    return randomAccessWriteBuffer;
}

@Override
public DecodeResult decode(InputStream encoded, OutputStream decoded, COSDictionary parameters, int index, DecodeOptions options) throws IOException {
    ImageReader reader = findImageReader("JBIG2", "jbig2-imageio is not installed");
    if (reader.getClass().getName().contains("levigo")) // PATH: Test should invoke the next JBIG2Filter.logLevigoDonated(...) [step in execution path]
    {
        logLevigoDonated();
    }
    int bits = parameters.getInt(COSName.BITS_PER_COMPONENT, 1);
    COSDictionary params = getDecodeParams(parameters, index);
    ImageReadParam irp = reader.getDefaultReadParam();
    irp.setSourceSubsampling(options.getSubsamplingX(), options.getSubsamplingY(), options.getSubsamplingOffsetX(), options.getSubsamplingOffsetY());
    irp.setSourceRegion(options.getSourceRegion());
    options.setFilterSubsampled(true);
    InputStream source = encoded;
    if (params != null) {
        COSStream globals = params.getCOSStream(COSName.JBIG2_GLOBALS);
        if (globals != null) {
            source = new SequenceInputStream(globals.createInputStream(), encoded);
        }
    }
    try (ImageInputStream iis = ImageIO.createImageInputStream(source)) {
        reader.setInput(iis);
        BufferedImage image;
        try {
            image = reader.read(0, irp);
        } catch (Exception e) {
            // wrap and rethrow any exceptions
            throw new IOException("Could not read JBIG2 image", e);
        }
        // I am assuming since JBIG2 is always black and white
        // depending on your renderer this might or might be needed
        if (image.getColorModel().getPixelSize() != bits) {
            if (bits != 1) {
                LOG.warn("Attempting to handle a JBIG2 with more than 1-bit depth");
            }
            BufferedImage packedImage = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_BYTE_BINARY);
            Graphics graphics = packedImage.getGraphics();
            graphics.drawImage(image, 0, 0, null);
            graphics.dispose();
            image = packedImage;
        }
        DataBuffer dBuf = image.getData().getDataBuffer();
        if (dBuf.getDataType() == DataBuffer.TYPE_BYTE) {
            decoded.write(((DataBufferByte) (dBuf)).getData());
        } else {
            throw new IOException("Unexpected image buffer type");
        }
    } finally {
        reader.dispose();
    }
    return new DecodeResult(parameters);
}

private static synchronized void logLevigoDonated() {
    if (!levigoLogged) {
        LOG.info("The Levigo JBIG2 plugin has been donated to the Apache Foundation");
        LOG.info("and an improved version is available for download at " + "https://pdfbox.apache.org/download.cgi");
        levigoLogged = true;
    }
}

