/**
 * This will add a signature to the document. If the 0-based page number in the options
 * parameter is smaller than 0 or larger than max, the nearest valid page number will be used
 * (i.e. 0 or max) and no exception will be thrown.
 * <p>
 * Only one signature may be added in a document. To sign several times,
 * load document, add signature, save incremental and close again.
 *
 * @param sigObject
 * 		is the PDSignatureField model
 * @param signatureInterface
 * 		is an interface whose implementation provides
 * 		signing capabilities. Can be null if external signing if used.
 * @param options
 * 		signature options
 * @throws IOException
 * 		if there is an error creating required fields
 * @throws IllegalStateException
 * 		if one attempts to add several signature
 * 		fields.
 */
public void addSignature(PDSignature sigObject, SignatureInterface signatureInterface, SignatureOptions options) throws IOException {
    if (signatureAdded) {
        throw new IllegalStateException("Only one signature may be added in a document");
    }
    signatureAdded = true;
    // Reserve content
    // We need to reserve some space for the signature. Some signatures including
    // big certificate chain and we need enough space to store it.
    int preferredSignatureSize = options.getPreferredSignatureSize();
    if (preferredSignatureSize > 0) {
        sigObject.setContents(new byte[preferredSignatureSize]);
    } else {
        sigObject.setContents(new byte[SignatureOptions.DEFAULT_SIGNATURE_SIZE]);
    }
    // Reserve ByteRange, will be overwritten in COSWriter
    sigObject.setByteRange(RESERVE_BYTE_RANGE);
    signInterface = signatureInterface;
    // Create SignatureForm for signature and append it to the document
    // Get the first valid page
    PDPageTree pageTree = getPages();
    int pageCount = pageTree.getCount();
    if (pageCount == 0) {
        throw new IllegalStateException("Cannot sign an empty document");
    }
    // Get the AcroForm from the Root-Dictionary and append the annotation
    PDDocumentCatalog catalog = getDocumentCatalog();
    // PATH: Test should invoke the next PDDocumentCatalog.getAcroForm(...) [step in execution path]
    PDAcroForm acroForm = catalog.getAcroForm(null);
    catalog.getCOSObject().setNeedToBeUpdated(true);
    if (acroForm == null) {
        acroForm = new PDAcroForm(this);
        catalog.setAcroForm(acroForm);
    } else {
        acroForm.getCOSObject().setNeedToBeUpdated(true);
    }
    PDSignatureField signatureField = null;
    COSArray fieldArray = acroForm.getCOSObject().getCOSArray(COSName.FIELDS);
    if (fieldArray != null) {
        fieldArray.setNeedToBeUpdated(true);
        signatureField = findSignatureField(acroForm.getFieldIterator(), sigObject);
    } else {
        acroForm.getCOSObject().setItem(COSName.FIELDS, new COSArray());
    }
    PDAnnotationWidget firstWidget;
    PDPage page;
    if (signatureField == null) {
        signatureField = new PDSignatureField(acroForm);
        // append the signature object
        signatureField.setValue(sigObject);
        firstWidget = signatureField.getWidgets().get(0);
        int startIndex = Math.min(Math.max(options.getPage(), 0), pageCount - 1);
        page = pageTree.get(startIndex);
        // backward linking
        firstWidget.setPage(page);
    } else {
        firstWidget = signatureField.getWidgets().get(0);
        sigObject.getCOSObject().setNeedToBeUpdated(true);
        page = null;
    }
    // TODO This "overwrites" the settings of the original signature field which might not be intended by the user
    // better make it configurable (not all users need/want PDF/A but their own setting):
    // to conform PDF/A-1 requirement:
    // The /F key's Print flag bit shall be set to 1 and
    // its Hidden, Invisible and NoView flag bits shall be set to 0
    firstWidget.setPrinted(true);
    // This may be troublesome if several form fields are signed,
    // see thread from PDFBox users mailing list 17.2.2021 - 19.2.2021
    // https://mail-archives.apache.org/mod_mbox/pdfbox-users/202102.mbox/thread
    // better set the printed flag in advance
    // Set the AcroForm Fields
    List<PDField> acroFormFields = acroForm.getFields();
    acroForm.getCOSObject().setDirect(true);
    acroForm.setSignaturesExist(true);
    acroForm.setAppendOnly(true);
    boolean checkFields = checkSignatureField(acroForm.getFieldIterator(), signatureField);
    if (checkFields) {
        signatureField.getCOSObject().setNeedToBeUpdated(true);
    } else {
        acroFormFields.add(signatureField);
    }
    // Get the object from the visual signature
    COSDocument visualSignature = options.getVisualSignature();
    // Distinction of case for visual and non-visual signature
    if (visualSignature == null) {
        prepareNonVisibleSignature(firstWidget);
    } else {
        prepareVisibleSignature(firstWidget, acroForm, visualSignature);
    }
    if (page != null) {
        // Create Annotation / Field for signature
        List<PDAnnotation> annotations = page.getAnnotations();
        // Get the annotations of the page and append the signature-annotation to it
        // take care that page and acroforms do not share the same array (if so, we don't need to add it twice)
        if (!(((checkFields && (annotations instanceof COSArrayList)) && (acroFormFields instanceof COSArrayList)) && ((COSArrayList) (annotations)).toList().equals(((COSArrayList) (acroFormFields)).toList()))) {
            // use check to prevent the annotation widget from appearing twice
            if (checkSignatureAnnotation(annotations, firstWidget)) {
                firstWidget.getCOSObject().setNeedToBeUpdated(true);
            } else {
                annotations.add(firstWidget);
            }
        }
        // Make /Annots a direct object by reassigning it,
        // to avoid problem if it is an existing indirect object:
        // it would not be updated in incremental save, and if we'd set the /Annots array "to be updated"
        // while keeping it indirect, Adobe Reader would claim that the document had been modified.
        page.setAnnotations(annotations);
        page.getCOSObject().setNeedToBeUpdated(true);
    }
}

/**
 * Get the documents AcroForm. This will return null if no AcroForm is part of the document.
 *
 * Dependent on setting <code>acroFormFixup</code> some fixing/changes will be done to the AcroForm.
 * If you need to ensure that there are no fixes applied call <code>getAcroForm</code> with <code>null</code>.
 *
 * Using <code>getAcroForm(PDDocumentFixup acroFormFixup)</code> might change the original content and
 * subsequent calls with <code>getAcroForm(null)</code> will return the changed content.
 *
 * @param acroFormFixup
 * 		the fix up action or null
 * @return The document's AcroForm.
 */
public PDAcroForm getAcroForm(PDDocumentFixup acroFormFixup) {
    if ((acroFormFixup != null) && (acroFormFixup != acroFormFixupApplied)) // PATH: Test should invoke the next AcroFormDefaultFixup.apply(...) [step in execution path]
    {
        acroFormFixup.apply();
        cachedAcroForm = null;
        acroFormFixupApplied = acroFormFixup;
    } else if (acroFormFixupApplied != null) {
        LOG.debug("AcroForm content has already been retrieved with fixes applied - original content changed because of that");
    }
    if (cachedAcroForm == null) {
        COSDictionary dict = root.getCOSDictionary(COSName.ACRO_FORM);
        cachedAcroForm = (dict == null) ? null : new PDAcroForm(document, dict);
    }
    return cachedAcroForm;
}

@Override
public void apply() {
    new AcroFormDefaultsProcessor(document).process();
    /* Get the AcroForm in it's current state.

    Also note: getAcroForm() applies a default fixup which this processor
    is part of. So keep the null parameter otherwise this will end
    in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    // PDFBOX-4985
    // build the visual appearance as there is none for the widgets
    if ((acroForm != null) && acroForm.getNeedAppearances()) {
        if (acroForm.getFields().isEmpty()) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.process(...) [step in execution path]
        {
            new AcroFormOrphanWidgetsProcessor(document).process();
        }
        // PDFBOX-4985
        // build the visual appearance as there is none for the widgets
        new AcroFormGenerateAppearancesProcessor(document).process();
    }
}

@Override
public void process() {
    /* Get the AcroForm in it's current state.

    Also note: getAcroForm() applies a default fixup which this processor
    is part of. So keep the null parameter otherwise this will end
    in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    if (acroForm != null) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.resolveFieldsFromWidgets(...) [step in execution path]
    {
        resolveFieldsFromWidgets(acroForm);
    }
}

private void resolveFieldsFromWidgets(PDAcroForm acroForm) {
    LOG.debug("rebuilding fields from widgets");
    PDResources resources = acroForm.getDefaultResources();
    if (resources == null) {
        // failsafe. Currently resources is never null because defaultfixup is called first.
        LOG.debug("AcroForm default resources is null");
        return;
    }
    List<PDField> fields = new ArrayList<>();
    Map<String, PDField> nonTerminalFieldsMap = new HashMap<>();
    for (PDPage page : document.getPages()) {
        try {
            handleAnnotations(acroForm, resources, fields, page.getAnnotations(), nonTerminalFieldsMap);
        } catch (IOException ioe) {
            LOG.debug("couldn't read annotations for page " + ioe.getMessage());
        }
    }
    acroForm.setFields(fields);
    for (PDField field : acroForm.getFieldTree()) {
        if (field instanceof PDVariableText) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.ensureFontResources(...) [step in execution path]
        {
            ensureFontResources(resources, ((PDVariableText) (field)));
        }
    }
}

/* Lookup the font used in the default appearance and if this is 
 not available try to find a suitable font and use that.
 This may not be the original font but a similar font replacement

 TODO: implement a font lookup similar as discussed in PDFBOX-2661 so that already existing
       font resources might be accepatble.
       In such case this must be implemented in PDDefaultAppearanceString too!
 */
private void ensureFontResources(PDResources defaultResources, PDVariableText field) {
    String daString = field.getDefaultAppearance();
    if (daString.startsWith("/") && (daString.length() > 1)) {
        COSName fontName = COSName.getPDFName(daString.substring(1, daString.indexOf(" ")));
        try {
            if (defaultResources.getFont(fontName) == null) {
                if (LOG.isDebugEnabled()) {
                    LOG.debug("trying to add missing font resource for field " + field.getFullyQualifiedName());
                }
                FontMapper mapper = FontMappers.instance();
                FontMapping<TrueTypeFont> fontMapping = mapper.getTrueTypeFont(fontName.getName(), null);
                if (fontMapping != null) {
                    PDType0Font pdFont = PDType0Font.load(document, fontMapping.getFont(), false);
                    if (LOG.isDebugEnabled()) {
                        LOG.debug((("looked up font for " + fontName.getName()) + " - found ") + fontMapping.getFont().getName());
                    }
                    defaultResources.put(fontName, pdFont);
                } else if (LOG.isDebugEnabled()) {
                    LOG.debug((("no suitable font found for field " + field.getFullyQualifiedName()) + " for font name ") + fontName.getName());
                }
            }
        } catch (IOException ioe) {
            LOG.debug((("unable to handle font resources for field " + field.getFullyQualifiedName()) + ": ") + ioe.getMessage());
        }
    }
}

