/**
 * This method will import an entire FDF document into the PDF document
 * that this acroform is part of.
 *
 * @param fdf
 * 		The FDF document to import.
 * @throws IOException
 * 		If there is an error doing the import.
 */
public void importFDF(FDFDocument fdf) throws IOException {
    List<FDFField> fields = fdf.getCatalog().getFDF().getFields();
    if (fields != null) {
        for (FDFField field : fields) {
            FDFField fdfField = field;
            PDField docField = getField(fdfField.getPartialFieldName());
            if (docField != null) // PATH: Test should invoke the next PDNonTerminalField.importFDF(...) [step in execution path]
            {
                docField.importFDF(fdfField);
            }
        }
    }
}

@Override
void importFDF(FDFField fdfField) throws IOException // PATH: Test should invoke the next PDField.importFDF(...) [step in execution path]
{
    super.importFDF(fdfField);
    List<FDFField> fdfKids = fdfField.getKids();
    if (fdfKids == null) {
        return;
    }
    List<PDField> children = getChildren();
    for (int i = 0; i < fdfKids.size(); i++) {
        for (PDField pdChild : children) {
            FDFField fdfChild = fdfKids.get(i);
            String fdfName = fdfChild.getPartialFieldName();
            if ((fdfName != null) && fdfName.equals(pdChild.getPartialName())) {
                pdChild.importFDF(fdfChild);
            }
        }
    }
}

/**
 * This will import a fdf field from a fdf document.
 *
 * @param fdfField
 * 		The fdf field to import.
 * @throws IOException
 * 		If there is an error importing the data for this field.
 */
void importFDF(FDFField fdfField) throws IOException {
    COSBase fieldValue = fdfField.getCOSValue();
    if ((fieldValue != null) && (this instanceof PDTerminalField)) {
        PDTerminalField currentField = ((PDTerminalField) (this));
        if (fieldValue instanceof COSName) // PATH: Test should invoke the next PDChoice.setValue(...) [step in execution path]
        {
            currentField.setValue(((COSName) (fieldValue)).getName());
        } else if (fieldValue instanceof COSString) {
            currentField.setValue(((COSString) (fieldValue)).getString());
        } else if (fieldValue instanceof COSStream) {
            currentField.setValue(((COSStream) (fieldValue)).toTextString());
        } else if ((fieldValue instanceof COSArray) && (this instanceof PDChoice)) {
            ((PDChoice) (this)).setValue(((COSArray) (fieldValue)).toCOSStringStringList());
        } else {
            throw new IOException("Error:Unknown type for field import" + fieldValue);
        }
    } else if (fieldValue != null) {
        dictionary.setItem(COSName.V, fieldValue);
    }
    Integer ff = fdfField.getFieldFlags();
    if (ff != null) {
        setFieldFlags(ff);
    } else {
        // these are suppose to be ignored if the Ff is set.
        Integer setFf = fdfField.getSetFieldFlags();
        int fieldFlags = getFieldFlags();
        if (setFf != null) {
            int setFfInt = setFf;
            fieldFlags = fieldFlags | setFfInt;
            setFieldFlags(fieldFlags);
        }
        Integer clrFf = fdfField.getClearFieldFlags();
        if (clrFf != null) {
            // we have to clear the bits of the document fields for every bit that is
            // set in this field.
            // 
            // Example:
            // docFf = 1011
            // clrFf = 1101
            // clrFfValue = 0010;
            // newValue = 1011 & 0010 which is 0010
            int clrFfValue = clrFf;
            clrFfValue ^= 0xffffffff;
            fieldFlags = fieldFlags & clrFfValue;
            setFieldFlags(fieldFlags);
        }
    }
}

/**
 * Sets the entry "V" to the given values. Requires {@link #isMultiSelect()} to be true.
 *
