 *
 * @param doc
 * 		The document to write the body for.
 * @throws IOException
 * 		If there is an error writing the data.
 */
protected void doWriteBody(COSDocument doc) throws IOException {
    COSDictionary trailer = doc.getTrailer();
    // get the COSObjects to preserve the origin object numbers
    COSBase root = trailer.getItem(COSName.ROOT);
    COSBase info = trailer.getItem(COSName.INFO);
    COSBase encrypt = trailer.getItem(COSName.ENCRYPT);
    if (root != null) // PATH: Test should invoke the next COSWriter.addObjectToWrite(...) [step in execution path]
    {
        addObjectToWrite(root);
    }
    if (info != null) {
        addObjectToWrite(info);
    }
    doWriteObjects();
    willEncrypt = false;
    if (encrypt != null) {
        addObjectToWrite(encrypt);
    }
    doWriteObjects();
}

private void addObjectToWrite(COSBase object) {
    if (blockAddingObject) {
        return;
    }
    COSBase actual = object;
    if (actual instanceof COSObject) {
        // PATH: Test should invoke the next COSObject.getObject(...) [step in execution path]
        actual = ((COSObject) (actual)).getObject();
    }
    if ((writtenObjects.contains(object)// 
     || actualsAdded.contains(actual))// 
     || objectsToWrite.contains(object)) {
        return;
    }
    COSBase cosBase = null;
    COSObjectKey cosObjectKey = null;
    if (actual != null) {
        cosObjectKey = objectKeys.get(actual);
        if (cosObjectKey != null) {
            cosBase = keyObject.get(cosObjectKey);
            if ((!isNeedToBeUpdated(object)) && (!isNeedToBeUpdated(cosBase))) {
                return;
            }
        }
    }
    objectsToWrite.add(object);
    if (actual != null) {
        actualsAdded.add(actual);
    }
}

/**
 * This will get the object that this object encapsulates.
 *
 * @return The encapsulated object.
 */
public COSBase getObject() {
    if ((!isDereferenced) && (parser != null)) {
        try {
            // mark as dereferenced to avoid endless recursions
            isDereferenced = true;
            baseObject = parser.dereferenceCOSObject(this);
            getUpdateState().dereferenceChild(baseObject);
        } catch (IOException e) {
            LOG.error("Can't dereference " + this, e);
        } finally {
            parser = null;
        }
    }
    return baseObject;
}

