        annotDictMap = annotDictMaps.get(i);
        cloneStructureTree(destinationDocument);
        fixDestinations(destinationDocument);
    }
    return destinationDocuments;
}

/**
 * Interface method to handle the start of the page processing.
 *
 * @throws IOException
 * 		If an IO error occurs.
 */
private void processPages() throws IOException {
    for (PDPage page : sourceDocument.getPages()) {
        if (((currentPageNumber + 1) >= startPage) && ((currentPageNumber + 1) <= endPage)) // PATH: Test should invoke the next Splitter.processPage(...) [step in execution path]
        {
            processPage(page);
            currentPageNumber++;
        } else if (currentPageNumber > endPage) {
            break;
        } else {
            currentPageNumber++;
        }
    }
}

/**
 * Interface to start processing a new page.
 *
 * @param page
 * 		The page that is about to get processed.
 * @throws IOException
 * 		If there is an error creating the new document.
 */
protected void processPage(PDPage page) throws IOException // PATH: Test should invoke the next Splitter.processAnnotations(...) [step in execution path]
{
    createNewDocumentIfNecessary();
    PDPage imported = getDestinationDocument().importPage(page);
    if ((page.getResources() != null) && (!page.getCOSObject().containsKey(COSName.RESOURCES))) {
        imported.setResources(page.getResources());
        LOG.info("Resources imported in Splitter");// follow-up to warning in importPage

    }
    if (imported.getCOSObject().containsKey(COSName.B)) {
        imported.getCOSObject().removeItem(COSName.B);
        LOG.warn("/B entry (beads) removed by splitter");
    }
    // remove page links to avoid copying not needed resources
    processAnnotations(imported);
    pageDictMap.put(page.getCOSObject(), imported.getCOSObject());
}

/**
 * Clone all annotations because of changes possibly made, and because the structure tree is
 * cloned.
 *
 * @param imported
 * @throws IOException
 */
private void processAnnotations(PDPage imported) throws IOException {
    List<PDAnnotation> annotations = imported.getAnnotations();
    if (annotations.isEmpty()) {
        return;
    }
    List<PDAnnotation> clonedAnnotations = new ArrayList<>(annotations.size());
    for (PDAnnotation annotation : annotations) {
        // create a shallow clone
        COSDictionary clonedDict = new COSDictionary(annotation.getCOSObject());
        PDAnnotation annotationClone = PDAnnotation.createAnnotation(clonedDict);
        annotDictMap.put(annotation.getCOSObject(), clonedDict);
        clonedAnnotations.add(annotationClone);
        if (annotationClone instanceof PDAnnotationLink) {
            PDAnnotationLink link = ((PDAnnotationLink) (annotationClone));
            PDDestination srcDestination = null;
            try {
                srcDestination = link.getDestination();
            } catch (IOException ex) {
                LOG.warn(("Incorrect destination in link annotation on page " + (currentPageNumber + 1)) + " is removed", ex);
                link.setDestination(null);
            }
            PDAction action = null;
            if (srcDestination == null) {
                action = link.getAction();
                if (action instanceof PDActionGoTo) {
                    PDActionGoTo goToAction = ((PDActionGoTo) (action));
                    try {
                        srcDestination = goToAction.getDestination();
                    } catch (IOException ex) {
                        LOG.warn(("GoToAction with incorrect destination in link annotation on page " + (currentPageNumber + 1)) + " is removed", ex);
                        link.setAction(null);
                    }
                }
            }
            if (srcDestination instanceof PDNamedDestination) {
                // PATH: Test should invoke the next PDDocumentCatalog.findNamedDestinationPage(...) [step in execution path]
                srcDestination = sourceDocument.getDocumentCatalog().findNamedDestinationPage(((PDNamedDestination) (srcDestination)));
                // we do not use the named destination anymore because names get modified, e.g.
                // 0xAD becomes 0, see file 410609.pdf where the name no longer matches with the
                // entry in the new name tree; plus the original solution was 40 additional loc
            }
            if (srcDestination instanceof PDPageDestination) {
                // preserve links to pages within the split result:
                // not fully possible here because we don't have the full target document yet.
                // However we're cloning as needed and remember what to do later.
                PDPage destinationPage = ((PDPageDestination) (srcDestination)).getPage();
                if (destinationPage != null) {
                    // clone destination
                    COSArray clonedDestinationArray = new COSArray(((PDPageDestination) (srcDestination)).getCOSObject().toList());
                    PDPageDestination dstDestination = ((PDPageDestination) (PDDestination.create(clonedDestinationArray)));
                    // remember the destination to adjust / remove page later
                    destToFixMap.put(dstDestination, imported);
                    if (action != null) {
                        // if action is not null, then the destination came from an action,
                        // thus clone action as well, then assign destination clone, then action
                        COSDictionary clonedActionDict = new COSDictionary(action.getCOSObject());
                        PDActionGoTo dstAction = ((PDActionGoTo) (PDActionFactory.createAction(clonedActionDict)));
                        dstAction.setDestination(dstDestination);
                        link.setAction(dstAction);
                    } else {
                        // just assign destination clone
                        link.setDestination(dstDestination);
                    }
                }
            }
        }
        if ((annotationClone instanceof PDAnnotationWidget) && annotationClone.getCOSObject().containsKey(COSName.PARENT)) {
            // remove non-terminal field /Parent reference, because this may lead to orphan pages
            annotationClone.getCOSObject().removeItem(COSName.PARENT);
        }
        if (annotation.getPage() != null) {
            annotationClone.setPage(imported);
        }
    }
    // Second loop for markup and popup annotations, which reference annotations themselves
    for (PDAnnotation annotation : clonedAnnotations) {
        if (annotation instanceof PDAnnotationMarkup) {
            PDAnnotationPopup annotationPopup = ((PDAnnotationMarkup) (annotation)).getPopup();
            if (annotationPopup == null) {
                continue;
            }
            COSDictionary clonedPopupDict = annotDictMap.get(annotationPopup.getCOSObject());
            if (clonedPopupDict != null) {
                annotation.getCOSObject().setItem(COSName.POPUP, clonedPopupDict);
            } else {
                // orphan popup (not in annotation list); clone it and fix references
                clonedPopupDict = new COSDictionary(annotationPopup.getCOSObject());
                annotDictMap.put(annotationPopup.getCOSObject(), clonedPopupDict);
                PDAnnotationPopup annotationPopupClone = ((PDAnnotationPopup) (PDAnnotation.createAnnotation(clonedPopupDict)));
                annotationPopupClone.setParent(((PDAnnotationMarkup) (annotation)));
                ((PDAnnotationMarkup) (annotation)).setPopup(annotationPopupClone);
                if (annotationPopupClone.getPage() != null) {
                    annotationPopupClone.setPage(imported);
                }
            }
        }
        if (annotation instanceof PDAnnotationPopup) {
            PDAnnotationMarkup annotationMarkup = ((PDAnnotationPopup) (annotation)).getParent();
            if (annotationMarkup == null) {
                continue;
            }
            COSDictionary clonedMarkupDict = annotDictMap.get(annotationMarkup.getCOSObject());
            // clonedMarkupDict will be null if markup annotation is an orphan (not in annotation list)
            annotation.getCOSObject().setItem(COSName.PARENT, clonedMarkupDict);
        }
    }
    imported.setAnnotations(clonedAnnotations);
}

/**
 * Find the page destination from a named destination.
 *
 * @param namedDest
 * 		the named destination.
 * @return a PDPageDestination object or null if not found.
 * @throws IOException
 * 		if there is an error creating the PDPageDestination object.
 */
public PDPageDestination findNamedDestinationPage(PDNamedDestination namedDest) throws IOException {
    PDPageDestination pageDestination = null;
    PDDocumentNameDictionary namesDict = getNames();
    if (namesDict != null) {
        PDDestinationNameTreeNode destsTree = namesDict.getDests();
        if (destsTree != null) {
            // PATH: Test should invoke the next PDNameTreeNode.getValue(...) [step in execution path]
            pageDestination = destsTree.getValue(namedDest.getNamedDestination());
        }
    }
    if (pageDestination == null) {
        // Look up /Dests dictionary from catalog
        PDDocumentNameDestinationDictionary nameDestDict = getDests();
        if (nameDestDict != null) {
            String name = namedDest.getNamedDestination();
            pageDestination = ((PDPageDestination) (nameDestDict.getDestination(name)));
        }
    }
    return pageDestination;
}

/**
 * The name to retrieve.
 *
 * @param name
 * 		The name in the tree.
 * @return The value of the name in the tree.
 * @throws IOException
 * 		If there is a problem creating the destinations.
 */
public T getValue(String name) throws IOException {
    // PATH: Test should invoke the next PDNameTreeNode.getNames(...) [step in execution path]
    Map<String, T> names = getNames();
    if (names != null) {
        return names.get(name);
    }
    List<PDNameTreeNode<T>> kids = getKids();
    if (kids != null) {
        for (int i = 0; i < kids.size(); i++) {
            PDNameTreeNode<T> childNode = kids.get(i);
            String upperLimit = childNode.getUpperLimit();
            String lowerLimit = childNode.getLowerLimit();
            if ((((upperLimit == null) || (lowerLimit == null)) || (upperLimit.compareTo(lowerLimit) < 0)) || ((lowerLimit.compareTo(name) <= 0) && (upperLimit.compareTo(name) >= 0))) {
                return childNode.getValue(name);
            }
        }
    } else {
        LOG.warn("NameTreeNode does not have \"names\" nor \"kids\" objects.");
    }
    return null;
}

/**
 * This will return a map of names on this level. The key will be a string,
 * and the value will depend on where this class is being used.
 *
 * @return ordered map of COS objects or <code>null</code> if the dictionary
contains no 'Names' entry on this level.
 * @throws IOException
 * 		If there is an error while creating the sub types.
 * @see #getKids()
 */
public Map<String, T> getNames() throws IOException {
    COSArray namesArray = node.getCOSArray(COSName.NAMES);
    if (namesArray != null) {
        int size = namesArray.size();
        Map<String, T> names = new LinkedHashMap<>(size);
        if ((namesArray.size() % 2) != 0) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
        {
            LOG.warn("Names array has odd size: " + size);
        }
        for (int i = 0; (i + 1) < size; i += 2) {
            COSBase base = namesArray.getObject(i);
            if (!(base instanceof COSString)) {
                throw new IOException((("Expected string, found " + base) + " in name tree at index ") + i);
            }
            COSString key = ((COSString) (base));
            COSBase cosValue = namesArray.getObject(i + 1);
            names.put(key.getString(), convertCOSToPD(cosValue));
        }
        return Collections.unmodifiableMap(names);
    } else {
        return null;
    }
}

