/**
 * Creates a new GlyphList from a glyph list file.
 *
 * @param numberOfEntries
 * 		number of expected values used to preallocate the correct amount of memory
 * @param input
 * 		glyph list in Adobe format
 * @throws IOException
 * 		if the glyph list could not be read
 */
public (InputStream input, int numberOfEntries) throws IOException // PATH: Test should invoke the next GlyphList.loadList(...) [step in execution path]
{
    nameToUnicode = new HashMap<>(numberOfEntries);
    unicodeToName = new HashMap<>(numberOfEntries);
    loadList(input);
}

private void loadList(InputStream input) throws IOException {
    try (BufferedReader in = new BufferedReader(new InputStreamReader(input, StandardCharsets.ISO_8859_1))) {
        while (in.ready()) {
            String line = in.readLine();
            if ((line != null) && (!line.startsWith("#"))) {
                String[] parts = line.split(";");
                if (parts.length < 2) {
                    throw new IOException("Invalid glyph list entry: " + line);
                }
                String name = parts[0];
                String[] unicodeList = parts[1].split(" ");
                int[] codePoints = new int[unicodeList.length];
                int index = 0;
                for (String hex : unicodeList) {
                    codePoints[index++] = Integer.parseInt(hex, 16);
                }
                String string = new String(codePoints, 0, codePoints.length);
                // forward mapping
                String oldMapping = nameToUnicode.put(name, string);
                if (oldMapping != null) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
                {
                    LOG.warn((((("duplicate value for " + name) + " -> ") + parts[1]) + " ") + nameToUnicode.get(name));
                }
                // reverse mapping
                // PDFBOX-3884: take the various standard encodings as canonical,
                // e.g. tilde over ilde
                final boolean forceOverride = (((WinAnsiEncoding.INSTANCE.contains(name) || MacRomanEncoding.INSTANCE.contains(name)) || MacExpertEncoding.INSTANCE.contains(name)) || SymbolEncoding.INSTANCE.contains(name)) || ZapfDingbatsEncoding.INSTANCE.contains(name);
                if (forceOverride) {
                    unicodeToName.put(string, name);
                } else {
                    unicodeToName.putIfAbsent(string, name);
                }
            }
        } 
    }
}

