    if (srcDests != null) {
        PDDocumentNameDestinationDictionary destDests = destCatalog.getDests();
        if (destDests == null) {
            destCatalog.getCOSObject().setItem(COSName.DESTS, cloner.cloneForNewDocument(srcDests.getCOSObject()));
        } else {
            cloner.cloneMerge(srcDests, destDests);
        }
