/**
 * Returns the given page as an RGB or ARGB image at the given scale.
 *
 * @param pageIndex
 * 		the zero-based index of the page to be converted
 * @param scale
 * 		the scaling factor, where 1 = 72 DPI
 * @param imageType
 * 		the type of image to return
 * @param destination
 * 		controlling visibility of optional content groups
 * @return the rendered page image
 * @throws IOException
 * 		if the PDF cannot be read
 * @throws IllegalStateException
 * 		if the requested index isn't found or doesn't point to a valid
 * 		page dictionary
 * @throws IndexOutOfBoundsException
 * 		if the requested index is higher than the page count
 */
public BufferedImage renderImage(int pageIndex, float scale, ImageType imageType, RenderDestination destination) throws IOException // PATH: Test should invoke the next PageDrawer.drawPage(...) [step in execution path]
{
    PDPage page = pageTree.get(pageIndex);
    PDRectangle cropBox = page.getCropBox();
    float widthPt = cropBox.getWidth();
    float heightPt = cropBox.getHeight();
    // PDFBOX-4306 avoid single blank pixel line on the right or on the bottom
    int widthPx = ((int) (Math.max(Math.floor(widthPt * scale), 1)));
    int heightPx = ((int) (Math.max(Math.floor(heightPt * scale), 1)));
    // PDFBOX-4518 the maximum size (w*h) of a buffered image is limited to Integer.MAX_VALUE
    if ((((long) (widthPx)) * ((long) (heightPx))) > Integer.MAX_VALUE) {
        throw new IOException((((((("Maximum size of image exceeded (w * h * scale ^ 2) = "// 
         + widthPt) + " * ") + heightPt) + " * ") + scale) + " ^ 2 > ") + Integer.MAX_VALUE);
    }
    int rotationAngle = page.getRotation();
    int bimType;
    if ((imageType != ImageType.ARGB) && hasBlendMode(page)) {
        // PDFBOX-4095: if the PDF has blending on the top level, draw on transparent background
        // Inspired from PDF.js: if a PDF page uses any blend modes other than Normal,
        // PDF.js renders everything on a fully transparent RGBA canvas.
        // Finally when the page has been rendered, PDF.js draws the RGBA canvas on a white canvas.
        bimType = BufferedImage.TYPE_INT_ARGB;
    } else {
        bimType = imageType.toBufferedImageType();
    }
    // swap width and height
    BufferedImage image;
    if ((rotationAngle == 90) || (rotationAngle == 270)) {
        image = new BufferedImage(heightPx, widthPx, bimType);
    } else {
        image = new BufferedImage(widthPx, heightPx, bimType);
    }
    pageImage = image;
    // use a transparent background if the image type supports alpha
    Graphics2D g = image.createGraphics();
    if (image.getType() == BufferedImage.TYPE_INT_ARGB) {
        g.setBackground(new Color(0, 0, 0, 0));
    } else {
        g.setBackground(Color.WHITE);
    }
    g.clearRect(0, 0, image.getWidth(), image.getHeight());
    transform(g, page.getRotation(), cropBox, scale, scale);
    // the end-user may provide a custom PageDrawer
    RenderingHints actualRenderingHints = (renderingHints == null) ? createDefaultRenderingHints(g) : renderingHints;
    PageDrawerParameters parameters = new PageDrawerParameters(this, page, subsamplingAllowed, destination, actualRenderingHints, imageDownscalingOptimizationThreshold);
    PageDrawer drawer = createPageDrawer(parameters);
    drawer.drawPage(g, cropBox);
    g.dispose();
    if (image.getType() != imageType.toBufferedImageType()) {
        // PDFBOX-4095: draw temporary transparent image on white background
        BufferedImage newImage = new BufferedImage(image.getWidth(), image.getHeight(), imageType.toBufferedImageType());
        Graphics2D dstGraphics = newImage.createGraphics();
        dstGraphics.setBackground(Color.WHITE);
        dstGraphics.clearRect(0, 0, image.getWidth(), image.getHeight());
        dstGraphics.drawImage(image, 0, 0, null);
        dstGraphics.dispose();
        image = newImage;
    }
    return image;
}

/**
 * Draws the page to the requested context.
 *
 * @param g
 * 		The graphics context to draw onto.
 * @param pageSize
 * 		The size of the page to draw.
 * @throws IOException
 * 		If there is an IO error while drawing the page.
 */
public void drawPage(Graphics2D g, PDRectangle pageSize) throws IOException {
    graphics = g;
    xform = graphics.getTransform();
    Matrix m = new Matrix(xform);
    xformScalingFactorX = Math.abs(m.getScalingFactorX());
    xformScalingFactorY = Math.abs(m.getScalingFactorY());
    initialClip = graphics.getClip();
    this.pageSize = pageSize;
    setRenderingHints();
    graphics.translate(0, pageSize.getHeight());
    graphics.scale(1, -1);
    // adjust for non-(0,0) crop box
    graphics.translate(-pageSize.getLowerLeftX(), -pageSize.getLowerLeftY());
    processPage(getPage());
    for (PDAnnotation annotation : getPage().getAnnotations(annotationFilter)) // PATH: Test should invoke the next PageDrawer.showAnnotation(...) [step in execution path]
    {
        showAnnotation(annotation);
    }
    graphics = null;
}

@Override
public void showAnnotation(PDAnnotation annotation) throws IOException {
    lastClips = null;
    if (shouldSkipAnnotation(annotation)) {
        return;
    }
    // TODO support NoZoom, example can be found in p5 of PDFBOX-2348
    PDAppearanceDictionary appearance = annotation.getAppearance();
    if ((appearance == null) || (appearance.getNormalAppearance() == null)) // PATH: Test should invoke the next PDAnnotationFreeText.constructAppearances(...) [step in execution path]
    {
        annotation.constructAppearances(renderer.document);
    }
    if (annotation.isNoRotate() && (getCurrentPage().getRotation() != 0)) {
        appearance = annotation.getAppearance();
        if (appearance != null) {
            PDAppearanceEntry appearanceEntry = appearance.getNormalAppearance();
            if (((appearanceEntry != null) && appearanceEntry.isStream()) && hasTransparency(appearanceEntry.getAppearanceStream())) {
                // PDFBOX-4744: avoid appearances with transparency groups until we have fixed
                // the rendering. A real solution should probably be
                // in PDFStreamEngine.processAnnotation().
                annotation.constructAppearances();
            }
        }
        PDRectangle rect = annotation.getRectangle();
        AffineTransform savedTransform = graphics.getTransform();
        // "The upper-left corner of the annotation remains at the same point in
        // default user space; the annotation pivots around that point."
        graphics.rotate(Math.toRadians(getCurrentPage().getRotation()), rect.getLowerLeftX(), rect.getUpperRightY());
        super.showAnnotation(annotation);
        graphics.setTransform(savedTransform);
        annotation.setAppearance(appearance);// restore

    } else {
        super.showAnnotation(annotation);
    }
}

