@Override
public void constructAppearances(PDDocument document) {
    if (customAppearanceHandler == null) // PATH: Test should invoke the next PDAppearanceHandler.generateAppearanceStreams(...) [step in execution path]
    {
        PDFreeTextAppearanceHandler appearanceHandler = new PDFreeTextAppearanceHandler(this, document);
        appearanceHandler.generateAppearanceStreams();
    } else {
        customAppearanceHandler.generateAppearanceStreams();
    }
}

default void generateAppearanceStreams() // PATH: Test should invoke the next PDFileAttachmentAppearanceHandler.generateNormalAppearance(...) [step in execution path]
{
    generateNormalAppearance();
    generateRolloverAppearance();
    generateDownAppearance();
}

@Override
public void generateNormalAppearance() {
    PDAnnotationFileAttachment annotation = ((PDAnnotationFileAttachment) (getAnnotation()));
    PDRectangle rect = getRectangle();
    if (rect == null) {
        return;
    }
    try (PDAppearanceContentStream contentStream = getNormalAppearanceAsContentStream()) {
        setOpacity(contentStream, annotation.getConstantOpacity());
        // minimum code of PDTextAppearanceHandler.adjustRectAndBBox()
        int size = 18;
        rect.setUpperRightX(rect.getLowerLeftX() + size);
        rect.setLowerLeftY(rect.getUpperRightY() - size);
        annotation.setRectangle(rect);
        annotation.getNormalAppearanceStream().setBBox(new PDRectangle(size, size));
        // test case: pdf_commenting_new.pdf page 7
        String attachmentName = annotation.getAttachmentName();
        switch (attachmentName) {
            case "Paperclip" :
                drawPaperclip(contentStream);
                break;
            case "Graph" :
                drawGraph(contentStream);
                break;
            case "Tag" :
                drawTag(contentStream);
                break;
            default :
                drawPushPin(contentStream);
                break;
        }
    } catch (IOException e) {
        LOG.error(e);
    }
}

