        if ((ucs != null) && (ucs.getNumberOfComponents() != components.length)) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
        {
            // PDFBOX-5882
            LOG.warn((("Pattern colorspace component count " + ucs.getNumberOfComponents()) + " doesn't match components length ") + components.length);
        }
    }
}

