 */
public static FDFDocument loadFDF(String filename) throws IOException {
    // PATH: Test should invoke the next Loader.loadFDF(...) [step in execution path]
    return Loader.loadFDF(new File(filename));
}

/**
 * This will load a document from a file.
 *
 * @param file
 * 		The name of the file to load. {@link org.apache.pdfbox.io.RandomAccessReadBufferedFile} is used to
 * 		read the file.
 * @return The document that was loaded.
 * @throws IOException
 * 		If there is an error reading from the stream.
 */
public static FDFDocument loadFDF(File file) throws IOException {
    RandomAccessRead raFile = null;
    try {
        // PDFBOX-5894: RandomAccessRead is not closed here
        raFile = new RandomAccessReadBufferedFile(file);
        FDFParser parser = new FDFParser(raFile);
        // PATH: Test should invoke the next FDFParser.parse(...) [step in execution path]
        return parser.parse();
    } catch (IOException ioe) {
        IOUtils.closeQuietly(raFile);
        throw ioe;
    }
}

/**
 * This will parse the stream and populate the FDFDocument object.
 *
 * @return the parsed FDFDocument
 * @throws IOException
 * 		If there is an error reading from the stream or corrupt data is found.
 */
public FDFDocument parse() throws IOException {
    // set to false if all is processed
    boolean exceptionOccurred = true;
    try // PATH: Test should invoke the next FDFParser.initialParse(...) [step in execution path]
    {
        if (!parseFDFHeader()) {
            throw new IOException("Error: Header doesn't contain versioninfo");
        }
        initialParse();
        exceptionOccurred = false;
        return new FDFDocument(document, source);
    } finally {
        if (exceptionOccurred && (document != null)) {
            IOUtils.closeQuietly(document);
            document = null;
        }
    }
}

/**
 * The initial parse will first parse only the trailer, the xrefstart and all xref tables to have a pointer (offset)
 * to all the pdf's objects. It can handle linearized pdfs, which will have an xref at the end pointing to an xref
 * at the beginning of the file. Last the root object is parsed.
 *
 * @throws IOException
 * 		If something went wrong.
 */
private void initialParse() throws IOException {
    // PATH: Test should invoke the next COSParser.retrieveTrailer(...) [step in execution path]
    COSDictionary trailer = retrieveTrailer();
    COSDictionary root = trailer.getCOSDictionary(COSName.ROOT);
    if (root == null) {
        throw new IOException("Missing root object specification in trailer.");
    }
    initialParseDone = true;
}

/**
 * Read the trailer information and provide a COSDictionary containing the trailer information.
 *
 * @return a COSDictionary containing the trailer information
 * @throws IOException
 * 		if something went wrong
 */
protected COSDictionary retrieveTrailer() throws IOException {
    COSDictionary trailer = null;
    boolean rebuildTrailer = false;
    try {
        // parse startxref
        // TODO FDF files don't have a startxref value, so that rebuildTrailer is triggered
        long startXRefOffset = getStartxrefOffset();
        if (startXRefOffset > (-1)) {
            trailer = parseXref(startXRefOffset);
        } else {
            rebuildTrailer = isLenient();
        }
    } catch (IOException exception) {
        if (isLenient()) {
            rebuildTrailer = true;
        } else {
            throw exception;
        }
    }
    // check if the trailer contains a Root object
    if ((trailer != null) && (trailer.getItem(COSName.ROOT) == null)) {
        rebuildTrailer = isLenient();
    }
    if (rebuildTrailer) {
        trailer = getBruteForceParser().rebuildTrailer(xrefTrailerResolver, null);
        trailerWasRebuild = true;
        // transfer encryption information from BruteForceParser
        encryption = getBruteForceParser().getEncryption();
        if (encryption != null) {
            securityHandler = encryption.getSecurityHandler();
            accessPermission = securityHandler.getCurrentAccessPermission();
        }
    } else {
        // prepare decryption if necessary
        prepareDecryption();
        // don't use the getter as it creates an instance of BruteForceParser
        if ((bruteForceParser != null) && bruteForceParser.bfSearchTriggered()) // PATH: Test should invoke the next BruteForceParser.bfSearchForObjStreams(...) [step in execution path]
        {
            getBruteForceParser().bfSearchForObjStreams(xrefTrailerResolver, securityHandler);
        }
    }
    if (resetTrailerResolver()) {
        xrefTrailerResolver.reset();
        xrefTrailerResolver = null;
    }
    return trailer;
}

/**
 * Brute force search for all objects streams of a pdf.
 *
 * @param trailerResolver
 * 		the trailer resolver of the document
 * @param securityHandler
 * 		security handler to be used to decrypt encrypted documents
 * @throws IOException
 * 		if something went wrong
 */
protected void bfSearchForObjStreams(XrefTrailerResolver trailerResolver, SecurityHandler<? extends ProtectionPolicy> securityHandler) throws IOException {
    // update security handler
    this.securityHandler = securityHandler;
    // save origin offset
    long originOffset = source.getPosition();
    Map<Long, COSObjectKey> bfSearchForObjStreamOffsets = bfSearchForObjStreamOffsets();
    Map<COSObjectKey, Long> bfCOSObjectOffsets = getBFCOSObjectOffsets();
    // log warning about skipped stream
    // 
    // 
    bfSearchForObjStreamOffsets.entrySet().stream().filter(o -> bfCOSObjectOffsets.get(o.getValue()) == null).forEach(o -> LOG.warn((("Skipped incomplete object stream:" + o.getValue()) + " at ") + o.getKey()));
    // collect all stream offsets
    List<Long> objStreamOffsets = // 
    // 
    // 
    // 
    bfSearchForObjStreamOffsets.entrySet().stream().filter(o -> bfCOSObjectOffsets.get(o.getValue()) != null).filter(o -> o.getKey().equals(bfCOSObjectOffsets.get(o.getValue()))).map(Map.Entry::getKey).collect(Collectors.toList());
    // add all found compressed objects to the brute force search result
    for (Long offset : objStreamOffsets) {
        source.seek(offset);
        long stmObjNumber = readObjectNumber();
        int stmGenNumber = readGenerationNumber();
        readExpectedString(OBJ_MARKER, true);
        COSStream stream = null;
        try {
            COSDictionary dict = parseCOSDictionary(false);
            // PATH: Test should invoke the next COSParser.parseCOSStream(...) [step in execution path]
            stream = parseCOSStream(dict);
            if (securityHandler != null) {
                securityHandler.decryptStream(stream, stmObjNumber, stmGenNumber);
            }
            PDFObjectStreamParser objStreamParser = new PDFObjectStreamParser(stream, document);
            Map<Long, Integer> objectNumbers = objStreamParser.readObjectNumbers();
            Map<COSObjectKey, Long> xrefOffset = trailerResolver.getXrefTable();
            for (Long objNumber : objectNumbers.keySet()) {
                COSObjectKey objKey = new COSObjectKey(objNumber, 0);
                Long existingOffset = bfCOSObjectOffsets.get(objKey);
                if ((existingOffset != null) && (existingOffset < 0)) {
                    // translate stream object key to its offset
                    COSObjectKey objStmKey = new COSObjectKey(Math.abs(existingOffset), 0);
                    existingOffset = bfCOSObjectOffsets.get(objStmKey);
                }
                if ((existingOffset == null) || (offset > existingOffset)) {
                    bfCOSObjectOffsets.put(objKey, -stmObjNumber);
                    xrefOffset.put(objKey, -stmObjNumber);
                }
            }
        } catch (IOException exception) {
            LOG.debug((("Skipped corrupt stream: (" + stmObjNumber) + " 0 at offset ") + offset, exception);
        } finally {
            if (stream != null) {
                stream.close();
            }
        }
    }
    // restore origin offset
    source.seek(originOffset);
}

/**
 * This will read a COSStream from the input stream using length attribute within dictionary. If
 * length attribute is a indirect reference it is first resolved to get the stream length. This
 * means we copy stream data without testing for 'endstream' or 'endobj' and thus it is no
 * problem if these keywords occur within stream. We require 'endstream' to be found after
 * stream data is read.
 *
 * @param dic
 * 		dictionary that goes with this stream.
 * @return parsed pdf stream.
 * @throws IOException
 * 		if an error occurred reading the stream, like problems with reading
 * 		length attribute, stream does not end with 'endstream' after data read, stream too short etc.
 */
protected COSStream parseCOSStream(COSDictionary dic) throws IOException {
    // read 'stream'; this was already tested in parseObjectsDynamically()
    readString();
    skipWhiteSpaces();
    /* This needs to be dic.getItem because when we are parsing, the underlying object might still be null. */
    COSNumber streamLengthObj = getLength(dic.getItem(COSName.LENGTH));
    if (streamLengthObj == null) {
        if (isLenient) {
            LOG.warn("The stream doesn't provide any stream length, using fallback readUntilEnd, at offset " + source.getPosition());
        } else {
            throw new IOException("Missing length for stream.");
        }
    }
    long streamStartPosition = source.getPosition();
    long streamLength;
    if ((streamLengthObj != null) && validateStreamLength(streamLengthObj.longValue())) {
        streamLength = streamLengthObj.longValue();
        // skip stream
        source.seek(source.getPosition() + streamLengthObj.intValue());
    } else {
        // PATH: Test should invoke the next COSParser.readUntilEndStream(...) [step in execution path]
        streamLength = readUntilEndStream(new EndstreamFilterStream());
        if ((streamLengthObj == null) || (streamLengthObj.longValue() != streamLength)) {
            dic.setLong(COSName.LENGTH, streamLength);
        }
    }
    String endStream = readString();
    if (endStream.equals("endobj") && isLenient) {
        LOG.warn("stream ends with 'endobj' instead of 'endstream' at offset " + source.getPosition());
        // avoid follow-up warning about missing endobj
        source.rewind(ENDOBJ.length);
    } else if (((endStream.length() > 9) && isLenient) && endStream.startsWith(ENDSTREAM_STRING)) {
        LOG.warn((("stream ends with '" + endStream) + "' instead of 'endstream' at offset ") + source.getPosition());
        // unread the "extra" bytes
        source.rewind(endStream.substring(9).getBytes(StandardCharsets.ISO_8859_1).length);
    } else if (!endStream.equals(ENDSTREAM_STRING)) {
        throw new IOException((("Error reading stream, expected='endstream' actual='" + endStream) + "' at offset ") + source.getPosition());
    }
    return document.createCOSStream(dic, streamStartPosition, streamLength);
}

/**
 * This method will read through the current stream object until
 * we find the keyword "endstream" meaning we're at the end of this
 * object. Some pdf files, however, forget to write some endstream tags
 * and just close off objects with an "endobj" tag so we have to handle
 * this case as well.
 *
 * This method is optimized using buffered IO and reduced number of
 * byte compare operations.
 *
 * @param out
 * 		stream we write out to.
 * @throws IOException
 * 		if something went wrong
 */
private long readUntilEndStream(final EndstreamFilterStream out) throws IOException {
    int bufSize;
    int charMatchCount = 0;
    byte[] keyw = ENDSTREAM;
    // last character position of shortest keyword ('endobj')
    final int quickTestOffset = 5;
    // read next chunk into buffer; already matched chars are added to beginning of buffer
    while ((bufSize = source.read(strmBuf, charMatchCount, STRMBUFLEN - charMatchCount)) > 0) {
        bufSize += charMatchCount;
        int bIdx = charMatchCount;
        int quickTestIdx;
        // iterate over buffer, trying to find keyword match
        for (int maxQuicktestIdx = bufSize - quickTestOffset; bIdx < bufSize; bIdx++) {
            // reduce compare operations by first test last character we would have to
            // match if current one matches; if it is not a character from keywords
            // we can move behind the test character; this shortcut is inspired by the
            // Boyer-Moore string search algorithm and can reduce parsing time by approx. 20%
            quickTestIdx = bIdx + quickTestOffset;
            if ((charMatchCount == 0) && (quickTestIdx < maxQuicktestIdx)) {
                final byte ch = strmBuf[quickTestIdx];
                if ((ch > 't') || (ch < 'a')) {
                    // last character we would have to match if current character would match
                    // is not a character from keywords -> jump behind and start over
                    bIdx = quickTestIdx;
                    continue;
                }
            }
            // could be negative - but we only compare to ASCII
            final byte ch = strmBuf[bIdx];
            if (ch == keyw[charMatchCount]) {
                if ((++charMatchCount) == keyw.length) {
                    // match found
                    bIdx++;
                    break;
                }
            } else if ((charMatchCount == 3) && (ch == ENDOBJ[charMatchCount])) {
                // maybe ENDSTREAM is missing but we could have ENDOBJ
                keyw = ENDOBJ;
                charMatchCount++;
            } else {
                // no match; incrementing match start by 1 would be dumb since we already know
                // matched chars depending on current char read we may already have beginning
                // of a new match: 'e': first char matched; 'n': if we are at match position
                // idx 7 we already read 'e' thus 2 chars matched for each other char we have
                // to start matching first keyword char beginning with next read position
                charMatchCount = (ch == E) ? 1 : (ch == N) && (charMatchCount == 7) ? 2 : 0;
                // search again for 'endstream'
                keyw = ENDSTREAM;
            }
        }
        int contentBytes = Math.max(0, bIdx - charMatchCount);
        // write buffer content until first matched char to output stream
        if (contentBytes > 0) {
            out.filter(strmBuf, 0, contentBytes);
        }
        if (charMatchCount == keyw.length) {
            // keyword matched; unread matched keyword (endstream/endobj) and following buffered content
            source.rewind(bufSize - contentBytes);
            break;
        } else {
            // copy matched chars at start of buffer
            System.arraycopy(keyw, 0, strmBuf, 0, charMatchCount);
        }
    } 
    // this writes a lonely CR or drops trailing CR LF and LF
    return out.calculateLength();
}

