/**
 * Parses a PDF.
 *
 * @param input
 * 		byte array that contains the document. {@link org.apache.pdfbox.io.RandomAccessReadBuffer} is used
 * 		to read the data.
 * @param password
 * 		password to be used for decryption
 * @param keyStore
 * 		key store to be used for decryption when using public key security
 * @param alias
 * 		alias to be used for decryption when using public key security
 * @param streamCacheCreateFunction
 * 		a function to create an instance of a stream cache to be used for buffering
 * 		new/altered PDF streams
 * @return loaded document
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		In case of a reading or parsing error.
 */
public static PDDocument loadPDF(byte[] input, String password, InputStream keyStore, String alias, StreamCacheCreateFunction streamCacheCreateFunction) throws IOException {
    RandomAccessRead source = null;
    try {
        // RandomAccessRead is not closed here, may be needed for signing
        source = new RandomAccessReadBuffer(input);
        PDFParser parser = new PDFParser(source, password, keyStore, alias, streamCacheCreateFunction);
        // PATH: Test should invoke the next PDFParser.parse(...) [step in execution path]
        return parser.parse();
    } catch (IOException ioe) {
        IOUtils.closeQuietly(source);
        throw ioe;
    }
}

/**
 * This will parse the stream and populate the PDDocument object. This will close the keystore stream when it is
 * done parsing. Lenient mode is active by default.
 *
 * @return the populated PDDocument
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If there is an error reading from the stream or corrupt data is found.
 */
public PDDocument parse() throws IOException {
    // PATH: Test should invoke the next PDFParser.parse(...) [step in execution path]
    return parse(true);
}

/**
 * This will parse the stream and populate the PDDocument object. This will close the keystore stream when it is
 * done parsing.
 *
 * @param lenient
 * 		activate leniency if set to true
 * @return the populated PDDocument
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If there is an error reading from the stream or corrupt data is found.
 */
public PDDocument parse(boolean lenient) throws IOException {
    setLenient(lenient);
    // set to false if all is processed
    boolean exceptionOccurred = true;
    try {
        // PDFBOX-1922 read the version header and rewind
        if ((!parsePDFHeader()) && (!parseFDFHeader())) {
            if (lenient) {
                LOG.warn("Error: Header doesn't contain versioninfo");
            } else {
                throw new IOException("Error: Header doesn't contain versioninfo");
            }
        }
        if (!initialParseDone) // PATH: Test should invoke the next PDFParser.initialParse(...) [step in execution path]
        {
            initialParse();
        }
        exceptionOccurred = false;
        PDDocument pdDocument = createDocument();
        pdDocument.setEncryptionDictionary(getEncryption());
        return pdDocument;
    } finally {
        if (exceptionOccurred && (document != null)) {
            IOUtils.closeQuietly(document);
            document = null;
        }
    }
}

/**
 * The initial parse will first parse only the trailer, the xrefstart and all xref tables to have a pointer (offset)
 * to all the pdf's objects. It can handle linearized pdfs, which will have an xref at the end pointing to an xref
 * at the beginning of the file. Last the root object is parsed.
 *
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If something went wrong.
 */
protected void initialParse() throws IOException {
    // PATH: Test should invoke the next COSParser.retrieveTrailer(...) [step in execution path]
    COSDictionary trailer = retrieveTrailer();
    COSDictionary root = trailer.getCOSDictionary(COSName.ROOT);
    if (root == null) {
        throw new IOException("Missing root object specification in trailer.");
    }
    // in some pdfs the type value "Catalog" is missing in the root object
    if (isLenient() && (!root.containsKey(COSName.TYPE))) {
        root.setItem(COSName.TYPE, COSName.CATALOG);
    }
    // check pages dictionaries
    checkPages(root);
    document.setDecrypted();
    initialParseDone = true;
}

/**
 * Read the trailer information and provide a COSDictionary containing the trailer information.
 *
 * @return a COSDictionary containing the trailer information
 * @throws IOException
 * 		if something went wrong
 */
protected COSDictionary retrieveTrailer() throws IOException {
    COSDictionary trailer = null;
    boolean rebuildTrailer = false;
    try {
        // parse startxref
        // TODO FDF files don't have a startxref value, so that rebuildTrailer is triggered
        long startXRefOffset = getStartxrefOffset();
        if (startXRefOffset > (-1)) {
            // PATH: Test should invoke the next COSParser.parseXref(...) [step in execution path]
            trailer = parseXref(startXRefOffset);
        } else {
            rebuildTrailer = isLenient();
        }
    } catch (IOException exception) {
        if (isLenient()) {
            rebuildTrailer = true;
        } else {
            throw exception;
        }
    }
    // check if the trailer contains a Root object
    if ((trailer != null) && (trailer.getItem(COSName.ROOT) == null)) {
        rebuildTrailer = isLenient();
    }
    if (rebuildTrailer) {
        trailer = getBruteForceParser().rebuildTrailer(xrefTrailerResolver, null);
        trailerWasRebuild = true;
        // transfer encryption information from BruteForceParser
        encryption = getBruteForceParser().getEncryption();
        if (encryption != null) {
            securityHandler = encryption.getSecurityHandler();
            accessPermission = securityHandler.getCurrentAccessPermission();
        }
    } else {
        // prepare decryption if necessary
        prepareDecryption();
        // don't use the getter as it creates an instance of BruteForceParser
        if ((bruteForceParser != null) && bruteForceParser.bfSearchTriggered()) {
            getBruteForceParser().bfSearchForObjStreams(xrefTrailerResolver, securityHandler);
        }
    }
    if (resetTrailerResolver()) {
        xrefTrailerResolver.reset();
        xrefTrailerResolver = null;
    }
    return trailer;
}

/**
 * Parses cross reference tables.
 *
 * @param startXRefOffset
 * 		start offset of the first table
 * @return the trailer dictionary
 * @throws IOException
 * 		if something went wrong
 */
private COSDictionary parseXref(long startXRefOffset) throws IOException {
    source.seek(startXRefOffset);
    long startXrefOffset = Math.max(0, parseStartXref());
    // check the startxref offset
    long fixedOffset = checkXRefOffset(startXrefOffset);
    if (fixedOffset > (-1)) {
        startXrefOffset = fixedOffset;
    }
    document.setStartXref(startXrefOffset);
    long prev = startXrefOffset;
    // ---- parse whole chain of xref tables/object streams using PREV reference
    Set<Long> prevSet = new HashSet<>();
    COSDictionary trailer = null;
    while (prev > 0) {
        // save expected position for loop detection
        prevSet.add(prev);
        // seek to xref table
        source.seek(prev);
        // skip white spaces
        skipSpaces();
        // save current position as well due to skipped spaces
        prevSet.add(source.getPosition());
        // -- parse xref
        if (source.peek() == X) {
            // xref table and trailer
            // use existing parser to parse xref table
            if ((!parseXrefTable(prev)) || // PATH: Test should invoke the next COSParser.parseTrailer(...) [step in execution path]
            (!parseTrailer())) {
                throw new IOException("Expected trailer object at offset " + source.getPosition());
            }
            trailer = xrefTrailerResolver.getCurrentTrailer();
            // check for a XRef stream, it may contain some object ids of compressed objects
            if (trailer.containsKey(COSName.XREF_STM)) {
                int streamOffset = trailer.getInt(COSName.XREF_STM);
                // check the xref stream reference
                fixedOffset = checkXRefOffset(streamOffset);
                if ((fixedOffset > (-1)) && (fixedOffset != streamOffset)) {
                    LOG.warn((("/XRefStm offset " + streamOffset) + " is incorrect, corrected to ") + fixedOffset);
                    streamOffset = ((int) (fixedOffset));
                    trailer.setInt(COSName.XREF_STM, streamOffset);
                }
                if (streamOffset > 0) {
                    source.seek(streamOffset);
                    skipSpaces();
                    try {
                        parseXrefObjStream(prev, false);
                        document.setHasHybridXRef();
                    } catch (IOException ex) {
                        if (isLenient) {
                            LOG.error("Failed to parse /XRefStm at offset " + streamOffset, ex);
                        } else {
                            throw ex;
                        }
                    }
                } else if (isLenient) {
                    LOG.error("Skipped XRef stream due to a corrupt offset:" + streamOffset);
                } else {
                    throw new IOException("Skipped XRef stream due to a corrupt offset:" + streamOffset);
                }
            }
            prev = trailer.getLong(COSName.PREV);
        } else {
            // parse xref stream
            prev = parseXrefObjStream(prev, true);
            trailer = xrefTrailerResolver.getCurrentTrailer();
        }
        if (prev > 0) {
            // check the xref table reference
            fixedOffset = checkXRefOffset(prev);
            if ((fixedOffset > (-1)) && (fixedOffset != prev)) {
                prev = fixedOffset;
                trailer.setLong(COSName.PREV, prev);
            }
        }
        if (prevSet.contains(prev)) {
            throw new IOException("/Prev loop at offset " + prev);
        }
    } 
    // ---- build valid xrefs out of the xref chain
    xrefTrailerResolver.setStartxref(startXrefOffset);
    trailer = xrefTrailerResolver.getTrailer();
    document.setTrailer(trailer);
    document.setIsXRefStream(XRefType.STREAM == xrefTrailerResolver.getXrefType());
    // check the offsets of all referenced objects
    if (isLenient) {
        checkXrefOffsets();
    }
    // copy xref table
    document.addXRefTable(xrefTrailerResolver.getXrefTable());
    // remember the highest XRef object number to avoid it being reused in incremental saving
    Optional<Long> maxValue = // 
    // 
    document.getXrefTable().keySet().stream().map(COSObjectKey::getNumber).reduce(Long::max);
    document.setHighestXRefObjectNumber(maxValue.isPresent() ? maxValue.get() : 0);
    return trailer;
}

/**
 * This will parse the trailer from the stream and add it to the state.
 *
 * @return false on parsing error
 * @throws IOException
 * 		If an IO error occurs.
 */
private boolean parseTrailer() throws IOException // PATH: Test should invoke the next XrefTrailerResolver.setTrailer(...) [step in execution path]
{
    // parse the last trailer.
    long trailerOffset = source.getPosition();
    // PDFBOX-1739 skip extra xref entries in RegisSTAR documents
    if (isLenient) {
        int nextCharacter = source.peek();
        while ((nextCharacter != 't') && isDigit(nextCharacter)) {
            if (source.getPosition() == trailerOffset) {
                // warn only the first time
                LOG.warn(("Expected trailer object at offset " + trailerOffset) + ", keep trying");
            }
            readLine();
            nextCharacter = source.peek();
        } 
    }
    if (source.peek() != 't') {
        return false;
    }
    // read "trailer"
    long currentOffset = source.getPosition();
    String nextLine = readLine();
    if (!nextLine.trim().equals("trailer")) {
        // in some cases the EOL is missing and the trailer immediately
        // continues with "<<" or with a blank character
        // even if this does not comply with PDF reference we want to support as many PDFs as possible
        // Acrobat reader can also deal with this.
        if (nextLine.startsWith("trailer")) {
            // we can't just unread a portion of the read data as we don't know if the EOL consist of 1 or 2 bytes
            int len = "trailer".length();
            // jump back right after "trailer"
            source.seek(currentOffset + len);
        } else {
            return false;
        }
    }
    // in some cases the EOL is missing and the trailer continues with " <<"
    // even if this does not comply with PDF reference we want to support as many PDFs as possible
    // Acrobat reader can also deal with this.
    skipSpaces();
    COSDictionary parsedTrailer = parseCOSDictionary(true);
    xrefTrailerResolver.setTrailer(parsedTrailer);
    skipSpaces();
    return true;
}

/**
