/**
 * Create a PDImageXObject from an image byte array. This overloaded version allows providing
 * a custom factory to handle specific image formats, such as BMP and GIF, or to act as a
 * fallback strategy when the default converters (e.g., for PNG or TIFF) fail.
 *
 * @param document
 * 		the document that shall use this PDImageXObject.
 * @param byteArray
 * 		bytes from an image file.
 * @param name
 * 		name of image file for exception messages, can be null.
 * @param customFactory
 * 		optional factory used to handle BMP, GIF, or fallback cases
 * 		(e.g., for PNG or TIFF). If {@code null}, this method delegates to
 * 		{@link #createFromByteArray(PDDocument, byte[], String)}.
 * @return a PDImageXObject.
 * @throws IOException
 * 		if there is an error when reading the file or creating the
 * 		PDImageXObject.
 * @throws IllegalArgumentException
 * 		if the image type is not supported.
 */
public static PDImageXObject createFromByteArray(PDDocument document, byte[] byteArray, String name, CustomFactory customFactory) throws IOException {
    FileType fileType = FileTypeDetector.detectFileType(byteArray);
    if (fileType == null) {
        throw new IllegalArgumentException("Image type not supported: " + name);
    }
    if (fileType == FileType.JPEG) {
        return JPEGFactory.createFromByteArray(document, byteArray);
    }
    if (fileType == FileType.PNG) {
        // Try to directly convert the image without recoding it.
        // PATH: Test should invoke the next PNGConverter.convertPNGImage(...) [step in execution path]
        PDImageXObject image = PNGConverter.convertPNGImage(document, byteArray);
        if (image != null) {
            return image;
        }
    }
    if (fileType == FileType.TIFF) {
        try {
            return CCITTFactory.createFromByteArray(document, byteArray);
        } catch (IOException ex) {
            LOG.debug("Reading as TIFF failed, setting fileType to PNG", ex);
            // Plan B: try reading with ImageIO
            // common exception:
            // First image in tiff is not CCITT T4 or T6 compressed
            fileType = FileType.PNG;
        }
    }
    if (((fileType == FileType.BMP) || (fileType == FileType.GIF)) || (fileType == FileType.PNG)) {
        if (customFactory != null) {
            return customFactory.createFromByteArray(document, byteArray);
        }
        ByteArrayInputStream bais = new ByteArrayInputStream(byteArray);
        BufferedImage bim = ImageIO.read(bais);
        return LosslessFactory.createFromImage(document, bim);
    }
    throw new IllegalArgumentException((("Image type " + fileType) + " not supported: ") + name);
}

/**
 * Try to convert a PNG into a PDImageXObject. If for any reason the PNG can not
 * be converted, null is returned.
 * <p>
 * This usually means the PNG structure is damaged (CRC error, etc.) or it uses
 * some features which can not be mapped to PDF.
 *
 * @param doc
 * 		the document to put the image in
 * @param imageData
 * 		the byte data of the PNG
 * @return null or the PDImageXObject built from the png
 */
static PDImageXObject convertPNGImage(PDDocument doc, byte[] imageData) throws IOException {
    PNGConverterState state = parsePNGChunks(imageData);
    if (!checkConverterState(state)) {
        // There is something wrong, we can't convert this PNG
        return null;
    }
    // PATH: Test should invoke the next PNGConverter.convertPng(...) [step in execution path]
    return convertPng(doc, state);
}

/**
 * Convert the image using the state.
 *
 * @param doc
 * 		the document to put the image in
 * @param state
 * 		the parser state containing the PNG chunks.
 * @return null or the converted image
 */
private static PDImageXObject convertPng(PDDocument doc, PNGConverterState state) throws IOException {
    Chunk ihdr = state.IHDR;
    int ihdrStart = ihdr.start;
    int width = readInt(ihdr.bytes, ihdrStart);
    int height = readInt(ihdr.bytes, ihdrStart + 4);
    int bitDepth = ihdr.bytes[ihdrStart + 8] & 0xff;
    int colorType = ihdr.bytes[ihdrStart + 9] & 0xff;
    int compressionMethod = ihdr.bytes[ihdrStart + 10] & 0xff;
    int filterMethod = ihdr.bytes[ihdrStart + 11] & 0xff;
    int interlaceMethod = ihdr.bytes[ihdrStart + 12] & 0xff;
    if (((((bitDepth != 1) && (bitDepth != 2)) && (bitDepth != 4)) && (bitDepth != 8)) && (bitDepth != 16)) {
        LOG.error(String.format("Invalid bit depth %d.", bitDepth));
        return null;
    }
    if ((width <= 0) || (height <= 0)) {
        LOG.error(String.format("Invalid image size %d x %d", width, height));
        return null;
    }
    if (compressionMethod != 0) {
        LOG.error(String.format("Unknown PNG compression method %d.", compressionMethod));
        return null;
    }
    if (filterMethod != 0) {
        LOG.error(String.format("Unknown PNG filtering method %d.", compressionMethod));
        return null;
    }
    if (interlaceMethod != 0) {
        LOG.debug(String.format("Can't handle interlace method %d.", interlaceMethod));
        return null;
    }
    state.width = width;
    state.height = height;
    state.bitsPerComponent = bitDepth;
    switch (colorType) {
        case 0 :
            // Grayscale
            LOG.debug("Can't handle grayscale yet.");
            return null;
        case 2 :
            // Truecolor
            if (state.tRNS != null) {
                LOG.debug("Can't handle images with transparent colors.");
                return null;
            }
            return buildImageObject(doc, state);
        case 3 :
            // Indexed image
            // PATH: Test should invoke the next PNGConverter.buildIndexImage(...) [step in execution path]
            return buildIndexImage(doc, state);
        case 4 :
            // Grayscale with alpha.
            LOG.debug("Can't handle grayscale with alpha, would need to separate alpha from image data");
            return null;
        case 6 :
            // Truecolor with alpha.
            LOG.debug("Can't handle truecolor with alpha, would need to separate alpha from image data");
            return null;
        default :
            LOG.error("Unknown PNG color type " + colorType);
            return null;
    }
}

/**
 * Build a indexed image
 */
private static PDImageXObject buildIndexImage(PDDocument doc, PNGConverterState state) throws IOException {
    Chunk plte = state.PLTE;
    if (plte == null) {
        LOG.error("Indexed image without PLTE chunk.");
        return null;
    }
    if ((plte.length % 3) != 0) {
        LOG.error("PLTE table corrupted, last (r,g,b) tuple is not complete.");
        return null;
    }
    if (state.bitsPerComponent > 8) {
        LOG.debug(String.format("Can only convert indexed images with bit depth <= 8, not %d.", state.bitsPerComponent));
        return null;
    }
    // PATH: Test should invoke the next PNGConverter.buildImageObject(...) [step in execution path]
    PDImageXObject image = buildImageObject(doc, state);
    if (image == null) {
        return null;
    }
    int highVal = (plte.length / 3) - 1;
    if (highVal > 255) {
        LOG.error(String.format("Too much colors in PLTE, only 256 allowed, found %d colors.", highVal + 1));
        return null;
    }
    setupIndexedColorSpace(doc, plte, image, highVal);
    if (state.tRNS != null) {
        image.getCOSObject().setItem(COSName.SMASK, buildTransparencyMaskFromIndexedData(doc, image, state));
    }
    return image;
}

/**
 * Build the base image object from the IDATs and profile information
 */
private static PDImageXObject buildImageObject(PDDocument document, PNGConverterState state) throws IOException {
    InputStream encodedByteStream = getIDATInputStream(state);
    PDColorSpace colorSpace = PDDeviceRGB.INSTANCE;
    PDImageXObject imageXObject = new PDImageXObject(document, encodedByteStream, COSName.FLATE_DECODE, state.width, state.height, state.bitsPerComponent, colorSpace);
    COSDictionary decodeParams = buildDecodeParams(state, colorSpace);
    imageXObject.getCOSObject().setItem(COSName.DECODE_PARMS, decodeParams);
    // We ignore gAMA and cHRM chunks if we have a ICC profile, as the ICC profile
    // takes preference
    boolean hasICCColorProfile = (state.sRGB != null) || (state.iCCP != null);
    if ((state.gAMA != null) && (!hasICCColorProfile)) {
        if (state.gAMA.length != 4) {
            LOG.error("Invalid gAMA chunk length " + state.gAMA.length);
            return null;
        }
        float gamma = readPNGFloat(state.gAMA.bytes, state.gAMA.start);
        // If the gamma is 2.2 for sRGB everything is fine. Otherwise bail out.
        // The gamma is stored as 1 / gamma.
        if (Math.abs(gamma - (1 / 2.2F)) > 1.0E-5) {
            LOG.debug(String.format("We can't handle gamma of %f yet.", gamma));
            return null;
        }
    }
    if (state.sRGB != null) {
        if (state.sRGB.length != 1) {
            LOG.error(String.format("sRGB chunk has an invalid length of %d", state.sRGB.length));
            return null;
        }
        // Store the specified rendering intent
        int renderIntent = state.sRGB.bytes[state.sRGB.start];
        COSName value = mapPNGRenderIntent(renderIntent);
        imageXObject.getCOSObject().setItem(COSName.INTENT, value);
    }
    if ((state.cHRM != null) && (!hasICCColorProfile)) {
        if (state.cHRM.length != 32) {
            LOG.error("Invalid cHRM chunk length " + state.cHRM.length);
            return null;
        }
        LOG.debug("We can not handle cHRM chunks yet.");
        return null;
    }
    // If possible we prefer a ICCBased color profile, just because its way faster
    // to decode ...
    if ((state.iCCP != null) || (state.sRGB != null)) {
        // We have got a color profile, which we must attach
        COSStream cosStream = createCOSStreamwithIccProfile(document, colorSpace, state);
        if (cosStream == null) {
            return null;
        }
        COSArray array = new COSArray();
        array.add(COSName.ICCBASED);
        array.add(cosStream);
        // PATH: Test should invoke the next PDICCBased.create(...) [step in execution path]
        PDICCBased profile = PDICCBased.create(array, null);
        imageXObject.setColorSpace(profile);
    }
    return imageXObject;
}

/**
 * Creates a new ICC color space using the PDF array, optionally using a resource cache.
 *
 * @param iccArray
 * 		the ICC stream object.
 * @param resources
 * 		resources to use as cache, or null for no caching.
 * @return an ICC color space.
 * @throws IOException
 * 		if there is an error reading the ICC profile or if the parameter is
 * 		invalid.
 */
public static PDICCBased create(COSArray iccArray, PDResources resources) throws IOException // PATH: Test should invoke the next new PDICCBased(...) [step in execution path]
{
    checkArray(iccArray);
    COSBase base = iccArray.get(1);
    if ((base instanceof COSObject) && (resources != null)) {
        ResourceCache resourceCache = resources.getResourceCache();
        if (resourceCache != null) {
            COSObject indirect = ((COSObject) (base));
            PDColorSpace space = resourceCache.getColorSpace(indirect);
            if (space instanceof PDICCBased) {
                return ((PDICCBased) (space));
            } else {
                PDICCBased newSpace = new PDICCBased(iccArray);
                resourceCache.put(indirect, newSpace);
                return newSpace;
            }
        }
    }
    return new PDICCBased(iccArray);
}

/**
 * Creates a new ICC color space with an empty stream.
 *
 * @param doc
 * 		the document to store the ICC data
 */
public PDICCBased(PDDocument doc) {
    array = new COSArray();
    array.add(COSName.ICCBASED);
    stream = new PDStream(doc);
    array.add(stream);
}

/**
 * Load the ICC profile, or init alternateColorSpace color space.
 */
private void loadICCProfile() throws IOException {
    if (useOnlyAlternateColorSpace) {
        try {
            fallbackToAlternateColorSpace(null);
            return;
        } catch (IOException e) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
        {
            LOG.warn("Error initializing alternate color space: " + e.getLocalizedMessage());
        }
    }
    try (InputStream input = this.stream.createInputStream()) {
        // if the embedded profile is sRGB then we can use Java's built-in profile, which
        // results in a large performance gain as it's our native color space, see PDFBOX-2587
        ICC_Profile profile;
        synchronized(LOG) {
            profile = ICC_Profile.getInstance(input);
            if (is_sRGB(profile)) {
                isRGB = true;
                awtColorSpace = ((ICC_ColorSpace) (ColorSpace.getInstance(ColorSpace.CS_sRGB)));
                iccProfile = awtColorSpace.getProfile();
            } else {
                profile = ensureDisplayProfile(profile);
                awtColorSpace = new ICC_ColorSpace(profile);
                iccProfile = profile;
            }
            // set initial colour
            int numOfComponents = getNumberOfComponents();
            float[] initial = new float[numOfComponents];
            for (int c = 0; c < initial.length; c++) {
                initial[c] = Math.max(0, getRangeForComponent(c).getMin());
            }
            initialColor = new PDColor(initial, this);
            // do things that trigger a ProfileDataException
            // or CMMException due to invalid profiles, see PDFBOX-1295 and PDFBOX-1740 (ü-file)
            // or ArrayIndexOutOfBoundsException, see PDFBOX-3610
            // also triggers "CMMException: LCMS error 13" for PDFBOX-5563 with LCMS, but
            // calling "new ComponentColorModel" doesn't
            awtColorSpace.toRGB(new float[numOfComponents]);
            // PDFBOX-4015: this one triggers "CMMException: LCMS error 13" with LCMS
            new ComponentColorModel(awtColorSpace, false, false, Transparency.OPAQUE, DataBuffer.TYPE_BYTE);
        }
    } catch (ProfileDataException | CMMException | IllegalArgumentException | ArrayIndexOutOfBoundsException | IOException e) {
        fallbackToAlternateColorSpace(e);
    }
}

