/* Adobe Reader/Acrobat are adding resources which are at the field/widget level
to the AcroForm level.
 */
private void validateAndEnsureAcroFormResources() {
    // add font resources which might be available at the field
    // level but are not at the AcroForm level to the AcroForm
    // to match Adobe Reader/Acrobat behavior
    PDResources acroFormResources = field.getAcroForm().getDefaultResources();
    if (acroFormResources == null) {
        return;
    }
    for (PDAnnotationWidget widget : field.getWidgets()) {
        PDAppearanceStream stream = widget.getNormalAppearanceStream();
        if (stream == null) {
            continue;
        }
        PDResources widgetResources = stream.getResources();
        if (widgetResources == null) {
            continue;
        }
        COSDictionary widgetFontDict = widgetResources.getCOSObject().getCOSDictionary(COSName.FONT);
        COSDictionary acroFormFontDict = acroFormResources.getCOSObject().getCOSDictionary(COSName.FONT);
        for (COSName fontResourceName : widgetResources.getFontNames()) {
            try {
                // PATH: Test should invoke the next PDResources.getFont(...) [step in execution path]
                if (acroFormResources.getFont(fontResourceName) == null) {
                    LOG.debug(("Adding font resource " + fontResourceName) + " from widget to AcroForm");
                    // use the COS-object to preserve a possible indirect object reference
                    acroFormFontDict.setItem(fontResourceName, widgetFontDict.getItem(fontResourceName));
                }
            } catch (IOException e) {
                LOG.warn("Unable to match field level font with AcroForm font", e);
            }
        }
    }
}

/**
 * Returns the font resource with the given name, or null if none exists.
 *
 * @param name
 * 		Name of the font resource.
 * @return the font with the given name or null
 * @throws IOException
 * 		if something went wrong.
 */
public PDFont getFont(COSName name) throws IOException {
    COSObject indirect = getIndirect(COSName.FONT, name);
    if ((cache != null) && (indirect != null)) {
        PDFont cached = cache.getFont(indirect);
        if (cached != null) {
            return cached;
        }
    } else if (indirect == null) {
        SoftReference<PDFont> ref = directFontCache.get(name);
        if (ref != null) {
            PDFont cached = ref.get();
            if (cached != null) {
                return cached;
            }
        }
    }
    PDFont font = null;
    COSBase base = get(COSName.FONT, name);
    if (base instanceof COSDictionary) {
        // PATH: Test should invoke the next PDFontFactory.createFont(...) [step in execution path]
        font = PDFontFactory.createFont(((COSDictionary) (base)), cache);
    }
    if ((cache != null) && (indirect != null)) {
        cache.put(indirect, font);
    } else if (indirect == null) {
        directFontCache.put(name, new SoftReference<>(font));
    }
    return font;
}

/**
 * Creates a new PDFont instance with the appropriate subclass.
 *
 * @param dictionary
 * 		a font dictionary
 * @param resourceCache
 * 		resource cache, only useful for type 3 fonts, can be null
 * @return a PDFont instance, based on the SubType entry of the dictionary
 * @throws IOException
 * 		if something goes wrong
 */
public static PDFont createFont(COSDictionary dictionary, ResourceCache resourceCache) throws IOException {
    COSName type = dictionary.getCOSName(COSName.TYPE, COSName.FONT);
    if (!COSName.FONT.equals(type)) {
        LOG.error(("Expected 'Font' dictionary but found '" + type.getName()) + "'");
    }
    COSName subType = dictionary.getCOSName(COSName.SUBTYPE);
    if (COSName.TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDType1Font(dictionary);
    } else if (COSName.MM_TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDMMType1Font(dictionary);
    } else if (COSName.TRUE_TYPE.equals(subType)) {
        return new PDTrueTypeFont(dictionary);
    } else if (COSName.TYPE3.equals(subType)) {
        return new PDType3Font(dictionary, resourceCache);
    } else if (COSName.TYPE0.equals(subType)) {
        COSDictionary fontDescriptor = getFontDescriptor(dictionary);
        FontType fontTypeFromFont = getFontTypeFromFont(fontDescriptor, subType);
        if (fontTypeFromFont != null) {
            COSDictionary descendantFont = getDescendantFont(dictionary);
            COSName descFontType = (descendantFont != null) ? descendantFont.getCOSName(COSName.SUBTYPE) : null;
            if ((descFontType != null) && (!fontTypeFromFont.isCIDSubtype(descFontType))) {
                fixType0Subtype(descendantFont, fontDescriptor, fontTypeFromFont.getSubtype());
            }
        }
        return new PDType0Font(dictionary);
    } else if (COSName.CID_FONT_TYPE0.equals(subType)) {
        throw new IOException("Type 0 descendant font not allowed");
    } else if (COSName.CID_FONT_TYPE2.equals(subType)) {
        throw new IOException("Type 2 descendant font not allowed");
    } else {
        // assuming Type 1 font (see PDFBOX-1988) because it seems that Adobe Reader does this
        // however, we may need more sophisticated logic perhaps looking at the FontFile
        LOG.warn(("Invalid font subtype '" + subType) + "'");
        return new PDType1Font(dictionary);
    }
}

/**
 * Constructor for reading a Type0 font from a PDF file.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @throws IOException
 * 		if the descendant font is missing.
 */
public (COSDictionary fontDictionary) throws IOException {
    this(fontDictionary);
    gsubData = GsubData.NO_DATA_FOUND;
    cmapLookup = null;
    COSArray descendantFonts = dict.getCOSArray(COSName.DESCENDANT_FONTS);
    if (descendantFonts == null) {
        throw new IOException("Missing descendant font array");
    }
    if (descendantFonts.size() == 0) {
        throw new IOException("Descendant font array is empty");
    }
    COSBase descendantFontDictBase = descendantFonts.getObject(0);
    if (!(descendantFontDictBase instanceof COSDictionary)) {
        throw new IOException("Missing descendant font dictionary");
    }
    if (!COSName.FONT.equals(((COSDictionary) (descendantFontDictBase)).getCOSName(COSName.TYPE, COSName.FONT))) {
        throw new IOException("Missing or wrong type in descendant font dictionary");
    }
    // PATH: Test should invoke the next PDFontFactory.createDescendantFont(...) [step in execution path]
    descendantFont = PDFontFactory.createDescendantFont(((COSDictionary) (descendantFontDictBase)), this);
    readEncoding();
    fetchCMapUCS2();
}

/**
 * Creates a new PDCIDFont instance with the appropriate subclass.
 *
 * @param dictionary
 * 		descendant font dictionary
 * @return a PDCIDFont instance, based on the SubType entry of the dictionary
 * @throws IOException
 * 		if something goes wrong
 */
static PDCIDFont createDescendantFont(COSDictionary dictionary, PDType0Font parent) throws IOException {
    COSName type = dictionary.getCOSName(COSName.TYPE, COSName.FONT);
    if (!COSName.FONT.equals(type)) {
        throw new IOException(("Expected 'Font' dictionary but found '" + type.getName()) + "'");
    }
    COSName subType = dictionary.getCOSName(COSName.SUBTYPE);
    if (COSName.CID_FONT_TYPE0.equals(subType)) {
        return new PDCIDFontType0(dictionary, parent);
    } else if (COSName.CID_FONT_TYPE2.equals(subType)) {
        return new PDCIDFontType2(dictionary, parent);
    } else {
        throw new IOException("Invalid font type: " + type);
    }
}

/**
 * Constructor.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @param parent
 * 		The parent font.
 * @throws IOException
 * 		if the font could not be read
 */
public (COSDictionary fontDictionary, PDType0Font parent) throws IOException {
    this(fontDictionary, parent);
    boolean fontIsDamaged = false;
    CFFFont cffFont = null;
    PDFontDescriptor fd = getFontDescriptor();
    if (fd != null) {
        PDStream ff3Stream = fd.getFontFile3();
        if (ff3Stream != null) {
            try (RandomAccessRead randomAccessRead = ff3Stream.getCOSObject().createView()) {
                if ((randomAccessRead.length() > 0) && (randomAccessRead.peek() == '%')) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
                {
                    // PDFBOX-2642 contains a corrupt PFB font instead of a CFF
                    LOG.warn("Found PFB but expected embedded CFF font " + fd.getFontName());
                    fontIsDamaged = true;
                } else {
                    CFFParser cffParser = new CFFParser();
                    cffFont = cffParser.parse(randomAccessRead).get(0);
                }
            } catch (IOException e) {
                LOG.error("Can't read the embedded CFF font " + fd.getFontName(), e);
                fontIsDamaged = true;
            }
        }
    }
    if (cffFont != null) {
        // embedded
        if (cffFont instanceof CFFCIDFont) {
            cidFont = ((CFFCIDFont) (cffFont));
            t1Font = null;
        } else {
            cidFont = null;
            t1Font = cffFont;
        }
        cid2gid = readCIDToGIDMap();
        isEmbedded = true;
        isDamaged = false;
    } else {
        // find font or substitute
        CIDFontMapping mapping = FontMappers.instance().getCIDFont(getBaseFont(), getFontDescriptor(), getCIDSystemInfo());
        FontBoxFont font;
        if (mapping.isCIDFont()) {
            cffFont = mapping.getFont().getCFF().getFont();
            if (cffFont instanceof CFFCIDFont) {
                cidFont = ((CFFCIDFont) (cffFont));
                t1Font = null;
                font = cidFont;
            } else {
                // PDFBOX-3515: OpenType fonts are loaded as CFFType1Font
                CFFType1Font f = ((CFFType1Font) (cffFont));
                cidFont = null;
                t1Font = f;
                font = f;
            }
        } else {
            cidFont = null;
            t1Font = mapping.getTrueTypeFont();
            font = t1Font;
        }
        if (mapping.isFallback()) {
            LOG.warn((("Using fallback " + font.getName()) + " for CID-keyed font ") + getBaseFont());
        }
        isEmbedded = false;
        isDamaged = fontIsDamaged;
    }
    fontMatrixTransform = getFontMatrix().createAffineTransform();
    fontMatrixTransform.scale(1000, 1000);
}

