}

/**
 * This will process all of the pages and the text that is in them.
 *
 * @param pages
 * 		The pages object in the document.
 * @throws IOException
 * 		If there is an error parsing the text.
 */
protected void processPages(PDPageTree pages) throws IOException {
    PDPage startBookmarkPage = (startBookmark == null) ? null : startBookmark.findDestinationPage(document);
    if (startBookmarkPage != null) {
        startBookmarkPageNumber = pages.indexOf(startBookmarkPage) + 1;
    } else {
        // -1 = undefined
        startBookmarkPageNumber = -1;
    }
    PDPage endBookmarkPage = (endBookmark == null) ? null : endBookmark.findDestinationPage(document);
    if (endBookmarkPage != null) {
        endBookmarkPageNumber = pages.indexOf(endBookmarkPage) + 1;
    } else {
        // -1 = undefined
        endBookmarkPageNumber = -1;
    }
    if (((((startBookmarkPageNumber == (-1)) && (startBookmark != null)) && (endBookmarkPageNumber == (-1))) && (endBookmark != null)) && (startBookmark.getCOSObject() == endBookmark.getCOSObject())) {
        // this is a special case where both the start and end bookmark
        // are the same but point to nothing. In this case
        // we will not extract any text.
        startBookmarkPageNumber = 0;
        endBookmarkPageNumber = 0;
    }
    for (PDPage page : pages) {
        if (page.hasContents()) // PATH: Test should invoke the next PDFTextStripper.processPage(...) [step in execution path]
        {
            processPage(page);
        }
        currentPageNo++;
    }
}

/**
 * This will process the contents of a page.
 *
 * @param page
 * 		The page to process.
 * @throws IOException
 * 		If there is an error processing the page.
 */
@Override
public void processPage(PDPage page) throws IOException {
    if ((((currentPageNo >= startPage) && (currentPageNo <= endPage)) && ((startBookmarkPageNumber == (-1)) || (currentPageNo >= startBookmarkPageNumber))) && ((endBookmarkPageNumber == (-1)) || (currentPageNo <= endBookmarkPageNumber))) // PATH: Test should invoke the next PDFTextStripperByArea.writePage(...) [step in execution path]
    {
        startPage(page);
        int numberOfArticleSections = 1;
        if (shouldSeparateByBeads) {
            fillBeadRectangles(page);
            numberOfArticleSections += beadRectangles.size() * 2;
        }
        int originalSize = charactersByArticle.size();
        charactersByArticle.ensureCapacity(numberOfArticleSections);
        int lastIndex = Math.max(numberOfArticleSections, originalSize);
        for (int i = 0; i < lastIndex; i++) {
            if (i < originalSize) {
                charactersByArticle.get(i).clear();
            } else if (numberOfArticleSections < originalSize) {
                // TODO Looks like decrement (--i) needed because next value will be ignored.
                // This segment is never reached in tests?!
                charactersByArticle.remove(i);
            } else {
                charactersByArticle.add(new ArrayList<>());
            }
        }
        characterListMapping.clear();
        super.processPage(page);
        writePage();
        endPage(page);
        page.removePageResourceFromCache();
    }
}

