 */
public (COSDictionary fontDictionary, PDType0Font parent, TrueTypeFont trueTypeFont) throws IOException {
    this(fontDictionary, parent);
    PDFontDescriptor fd = getFontDescriptor();
    if (trueTypeFont != null) {
        ttf = trueTypeFont;
        otf = ((trueTypeFont instanceof OpenTypeFont) && ((OpenTypeFont) (trueTypeFont)).isSupportedOTF()) ? ((OpenTypeFont) (trueTypeFont)) : null;
        isEmbedded = true;
        isDamaged = false;
    } else {
        boolean fontIsDamaged = false;
        TrueTypeFont ttfFont = null;
        PDStream stream = null;
        if (fd != null) {
            stream = fd.getFontFile2();
            if (stream == null) {
                stream = fd.getFontFile3();
            }
            if (stream == null) {
                // Acrobat looks in FontFile too, even though it is not in the spec, see PDFBOX-2599
                stream = fd.getFontFile();
            }
        }
        if (stream != null) {
            try {
                // embedded OTF or TTF
                RandomAccessRead view = stream.getCOSObject().createView();
                TTFParser ttfParser = getParser(view, true);
                ttfFont = ttfParser.parse(view);
                ttfFont.close();
            } catch (IOException e) {
                fontIsDamaged = true;
                LOG.warn("Could not read embedded OTF for font " + getBaseFont(), e);
            }
            if ((ttfFont instanceof OpenTypeFont) && (!((OpenTypeFont) (ttfFont)).isSupportedOTF())) {
                // the OpenType font contains CFF2 outlines which are not supported yet
                ttfFont = null;
                fontIsDamaged = true;
                LOG.warn("Found an OpenType font using CFF2 outlines which are not supported " + fd.getFontName());
            }
        }
        isEmbedded = ttfFont != null;
        isDamaged = fontIsDamaged;
        if (ttfFont == null) {
            // PATH: Test should invoke the next PDCIDFontType2.findFontOrSubstitute(...) [step in execution path]
            ttfFont = findFontOrSubstitute();
        }
        otf = ((ttfFont instanceof OpenTypeFont) && ((OpenTypeFont) (ttfFont)).isSupportedOTF()) ? ((OpenTypeFont) (ttfFont)) : null;
        ttf = ttfFont;
    }
    cmap = ttf.getUnicodeCmapLookup(false);
    cid2gid = readCIDToGIDMap();
}

private TrueTypeFont findFontOrSubstitute() throws IOException {
    TrueTypeFont ttfFont;
    // PATH: Test should invoke the next FontMapperImpl.getCIDFont(...) [step in execution path]
    CIDFontMapping mapping = FontMappers.instance().getCIDFont(getBaseFont(), getFontDescriptor(), getCIDSystemInfo());
    if (mapping.isCIDFont()) {
        ttfFont = mapping.getFont();
    } else {
        ttfFont = ((TrueTypeFont) (mapping.getTrueTypeFont()));
        if (ttfFont == null) {
            // shouldn't happen?!
            throw new IOException("mapping.getTrueTypeFont() returns null, please report");
        }
    }
    if (mapping.isFallback()) {
        LOG.warn((("Using fallback font " + ttfFont.getName()) + " for CID-keyed TrueType font ") + getBaseFont());
    }
    return ttfFont;
}

/**
 * Finds a CFF CID-Keyed font with the given PostScript name, or a suitable substitute, or null.
 * This method can also map CJK fonts via their CIDSystemInfo (ROS).
 *
 * @param fontDescriptor
 * 		FontDescriptor
 * @param cidSystemInfo
 * 		the CID system info, e.g. "Adobe-Japan1", if any.
 */
@Override
public CIDFontMapping getCIDFont(String baseFont, PDFontDescriptor fontDescriptor, PDCIDSystemInfo cidSystemInfo) {
    // try name match or substitute with OTF
    OpenTypeFont otf1 = ((OpenTypeFont) (findFont(FontFormat.OTF, baseFont)));
    if (otf1 != null) {
        return new CIDFontMapping(otf1, null, false);
    }
    // try name match or substitute with TTF
    TrueTypeFont ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, baseFont)));
    if (ttf != null) {
        return new CIDFontMapping(null, ttf, false);
    }
    if (cidSystemInfo != null) {
        // "In Acrobat 3.0.1 and later, Type 0 fonts that use a CMap whose CIDSystemInfo
        // dictionary defines the Adobe-GB1, Adobe-CNS1 Adobe-Japan1, or Adobe-Korea1 character
        // collection can also be substituted." - Adobe Supplement to the ISO 32000
        String collection = (cidSystemInfo.getRegistry() + "-") + cidSystemInfo.getOrdering();
        if (((collection.equals("Adobe-GB1") || collection.equals("Adobe-CNS1")) || collection.equals("Adobe-Japan1")) || collection.equals("Adobe-Korea1")) {
            // try automatic substitutes via character collection
            PriorityQueue<FontMatch> queue = getFontMatches(fontDescriptor, cidSystemInfo);
            FontMatch bestMatch = queue.poll();
            if (bestMatch != null) {
                if (LOG.isDebugEnabled()) {
                    LOG.debug((("Best match for '" + baseFont) + "': ") + bestMatch.info);
                }
                // PATH: Test should invoke the next FileSystemFontProvider$FSFontInfo.getFont(...) [step in execution path]
                FontBoxFont font = bestMatch.info.getFont();
                if (font instanceof OpenTypeFont) {
                    return new CIDFontMapping(((OpenTypeFont) (font)), null, true);
                } else if (font != null) {
                    return new CIDFontMapping(null, font, true);
                }
            }
        }
    }
    // last-resort fallback
    return new CIDFontMapping(null, lastResortFont, true);
}

/**
 * {@inheritDoc }
 * <p>
 * The method returns null if there was an error opening the font.
 */
@Override
public synchronized FontBoxFont getFont() {
    // synchronized to avoid race condition on cache access,
    // which could result in an unreferenced but open font
    FontBoxFont cached = parent.cache.getFont(this);
    if (cached != null) {
        return cached;
    } else {
        FontBoxFont font;
        switch (format) {
            case PFB :
                font = getType1Font(postScriptName, file);
                break;
            case TTF :
                // PATH: Test should invoke the next FileSystemFontProvider$FSFontInfo.getTrueTypeFont(...) [step in execution path]
                font = getTrueTypeFont(postScriptName, file);
                break;
            case OTF :
                font = getOTFFont(postScriptName, file);
                break;
            default :
                throw new RuntimeException("can't happen");
        }
        if (font != null) {
            parent.cache.addFont(this, font);
        }
        return font;
    }
}

private TrueTypeFont getTrueTypeFont(String postScriptName, File file) {
    try {
        TrueTypeFont ttf = readTrueTypeFont(postScriptName, file);
        if (LOG.isDebugEnabled()) // PATH: Test should invoke the next Log.debug(...) [step in execution path]
        {
            LOG.debug((("Loaded " + postScriptName) + " from ") + file);
        }
        return ttf;
    } catch (IOException e) {
        LOG.warn("Could not load font file: " + file, e);
    }
    return null;
}

