/**
 * This is the public method for setting the appearance stream.
 *
 * @param apValue
 * 		the String value which the appearance should represent
 * @throws IOException
 * 		If there is an error creating the stream.
 */
public void setAppearanceValue(String apValue) throws IOException {
    value = getFormattedValue(apValue);
    // Treat multiline field values in single lines as single lime values.
    // This is in line with how Adobe Reader behaves when entering text
    // interactively but NOT how it behaves when the field value has been
    // set programmatically and Reader is forced to generate the appearance
    // using PDAcroForm.setNeedAppearances
    // see PDFBOX-3911
    if ((field instanceof PDTextField) && (!((PDTextField) (field)).isMultiline())) {
        value = value.replaceAll("\\u000D\\u000A|[\\u000A\\u000B\\u000C\\u000D\\u0085\\u2028\\u2029]", " ");
    }
    for (PDAnnotationWidget widget : field.getWidgets()) // PATH: Test should invoke the next AppearanceGeneratorHelper.setAppearanceContent(...) [step in execution path]
    {
        if (widget.getCOSObject().containsKey("PMD")) {
            LOG.warn(("widget of field " + field.getFullyQualifiedName()) + " is a PaperMetaData widget, no appearance stream created");
            continue;
        }
        // some fields have the /Da at the widget level if the
        // widgets differ in layout.
        PDDefaultAppearanceString acroFormAppearance = defaultAppearance;
        if (widget.getCOSObject().getDictionaryObject(COSName.DA) != null) {
            defaultAppearance = getWidgetDefaultAppearanceString(widget);
        }
        PDRectangle rect = widget.getRectangle();
        if (rect == null) {
            widget.getCOSObject().removeItem(COSName.AP);
            LOG.warn(("widget of field " + field.getFullyQualifiedName()) + " has no rectangle, no appearance stream created");
            continue;
        }
        PDAppearanceDictionary appearanceDict = widget.getAppearance();
        if (appearanceDict == null) {
            appearanceDict = new PDAppearanceDictionary();
            widget.setAppearance(appearanceDict);
        }
        PDAppearanceEntry appearance = appearanceDict.getNormalAppearance();
        // TODO support appearances other than "normal"
        PDAppearanceStream appearanceStream;
        if (isValidAppearanceStream(appearance)) {
            appearanceStream = appearance.getAppearanceStream();
        } else {
            appearanceStream = prepareNormalAppearanceStream(widget);
            appearanceDict.setNormalAppearance(appearanceStream);
            // TODO support appearances other than "normal"
        }
        PDAppearanceCharacteristicsDictionary appearanceCharacteristics = widget.getAppearanceCharacteristics();
        /* Adobe Acrobat always recreates the complete appearance stream if there is an appearance characteristics
        entry (the widget dictionaries MK entry). In addition if there is no content yet also create the appearance
        stream from the entries.
         */
        if ((appearanceCharacteristics != null) || (appearanceStream.getContentStream().getLength() == 0)) {
            initializeAppearanceContent(widget, appearanceCharacteristics, appearanceStream);
        }
        setAppearanceContent(widget, appearanceStream);
        // restore the field level appearance
        defaultAppearance = acroFormAppearance;
    }
}

/**
 * Constructs and sets new contents for given appearance stream.
 */
private void setAppearanceContent(PDAnnotationWidget widget, PDAppearanceStream appearanceStream) throws IOException {
    // first copy any needed resources from the document’s DR dictionary into
    // the stream’s Resources dictionary
    defaultAppearance.copyNeededResourcesTo(appearanceStream);
    // then replace the existing contents of the appearance stream from /Tx BMC
    // to the matching EMC
    try (ByteArrayOutputStream output = new ByteArrayOutputStream()) // PATH: Test should invoke the next AppearanceGeneratorHelper.insertGeneratedAppearance(...) [step in execution path]
    {
        ContentStreamWriter writer = new ContentStreamWriter(output);
        List<Object> tokens = new PDFStreamParser(appearanceStream).parse();
        int bmcIndex = tokens.indexOf(BMC);
        if (bmcIndex == (-1)) {
            // append to existing stream
            writer.writeTokens(tokens);
            writer.writeTokens(COSName.TX, BMC);
        } else {
            // prepend content before BMC
            writer.writeTokens(tokens.subList(0, bmcIndex + 1));
        }
        // insert field contents
        insertGeneratedAppearance(widget, appearanceStream, output);
        int emcIndex = tokens.indexOf(EMC);
        if (emcIndex == (-1)) {
            // append EMC
            writer.writeTokens(EMC);
        } else {
            // append contents after EMC
            writer.writeTokens(tokens.subList(emcIndex, tokens.size()));
        }
        writeToStream(output.toByteArray(), appearanceStream);
    }
}

/**
 * Generate and insert text content and clipping around it.
 */
private void insertGeneratedAppearance(PDAnnotationWidget widget, PDAppearanceStream appearanceStream, OutputStream output) throws IOException {
    try (PDAppearanceContentStream contents = new PDAppearanceContentStream(appearanceStream, output)) {
        PDRectangle bbox = resolveBoundingBox(widget, appearanceStream);
        // Acrobat calculates the left and right padding dependent on the offset of the border edge
        // This calculation works for forms having been generated by Acrobat.
        // The minimum distance is always 1f even if there is no rectangle being drawn around.
        float borderWidth = 0;
        if (widget.getBorderStyle() != null) {
            borderWidth = widget.getBorderStyle().getWidth();
        }
        float padding = Math.max(1.0F, borderWidth);
        PDRectangle clipRect = applyPadding(bbox, padding);
        float clipRectLowerLeftY = clipRect.getLowerLeftY();
        float clipRectHeight = clipRect.getHeight();
        PDRectangle contentRect = applyPadding(clipRect, padding);
        contents.saveGraphicsState();
        // Acrobat always adds a clipping path
        contents.addRect(clipRect.getLowerLeftX(), clipRectLowerLeftY, clipRect.getWidth(), clipRectHeight);
        contents.clip();
        // get the font
        PDFont font = defaultAppearance.getFont();
        if (font == null) {
            throw new IllegalArgumentException("font is null, check whether /DA entry is incomplete or incorrect");
        }
        if (font.getName().contains("+")) {
            LOG.warn(((((("Font '" + defaultAppearance.getFontName().getName()) + "' of field '") + field.getFullyQualifiedName()) + "' contains subsetted font '") + font.getName()) + "'");
            LOG.warn("This may bring trouble with PDField.setValue(), PDAcroForm.flatten() or " + "PDAcroForm.refreshAppearances()");
            LOG.warn("You should replace this font with a non-subsetted font:");
            LOG.warn("PDFont font = PDType0Font.load(doc, new FileInputStream(fontfile), false);");
            LOG.warn(("acroForm.getDefaultResources().put(COSName.getPDFName(\"" + defaultAppearance.getFontName().getName()) + "\", font);");
        }
        // calculate the fontSize (because 0 = autosize)
        float fontSize = defaultAppearance.getFontSize();
        if (Float.compare(fontSize, 0) == 0) {
            fontSize = calculateFontSize(font, contentRect);
        }
        // for a listbox generate the highlight rectangle for the selected
        // options
        if (field instanceof PDListBox) {
            insertGeneratedListboxSelectionHighlight(contents, appearanceStream, font, fontSize);
        }
        // start the text output
        contents.beginText();
        // write font and color from the /DA string, with the calculated font size
        defaultAppearance.writeTo(contents, fontSize);
        // calculate the y-position of the baseline
        float y;
        // calculate font metrics at font size
        float fontScaleY = fontSize / FONTSCALE;
        float fontBoundingBoxAtSize = font.getBoundingBox().getHeight() * fontScaleY;
        float fontCapAtSize;
        float fontDescentAtSize;
        if (font.getFontDescriptor() != null) {
            fontCapAtSize = font.getFontDescriptor().getCapHeight() * fontScaleY;
            fontDescentAtSize = font.getFontDescriptor().getDescent() * fontScaleY;
        } else {
            // PATH: Test should invoke the next AppearanceGeneratorHelper.resolveCapHeight(...) [step in execution path]
            float fontCapHeight = resolveCapHeight(font);
            float fontDescent = resolveDescent(font);
            LOG.debug((("missing font descriptor - resolved Cap/Descent to " + fontCapHeight) + "/") + fontDescent);
            fontCapAtSize = fontCapHeight * fontScaleY;
            fontDescentAtSize = fontDescent * fontScaleY;
        }
        if ((field instanceof PDTextField) && ((PDTextField) (field)).isMultiline()) {
            y = contentRect.getUpperRightY() - fontBoundingBoxAtSize;
        } else // Adobe shows the text 'shifted up' in case the caps don't fit into the clipping area
        if (fontCapAtSize > clipRectHeight) {
            y = clipRectLowerLeftY + (-fontDescentAtSize);
        } else {
            // calculate the position based on the content rectangle
            y = clipRectLowerLeftY + ((clipRectHeight - fontCapAtSize) / 2);
            // check to ensure that ascents and descents fit
            if ((y - clipRectLowerLeftY) < (-fontDescentAtSize)) {
                float contentRectLowerLeftY = contentRect.getLowerLeftY();
                float fontDescentBased = (-fontDescentAtSize) + contentRectLowerLeftY;
                float fontCapBased = (contentRect.getHeight() - contentRectLowerLeftY) - fontCapAtSize;
                y = Math.min(fontDescentBased, Math.max(y, fontCapBased));
            }
        }
        // show the text
        float x = contentRect.getLowerLeftX();
        // special handling for comb boxes as these are like table cells with individual
        // chars
        if (shallComb()) {
            insertGeneratedCombAppearance(contents, appearanceStream, font, fontSize);
        } else if (field instanceof PDListBox) {
            insertGeneratedListboxAppearance(contents, appearanceStream, contentRect, font, fontSize);
        } else {
            PlainText textContent = new PlainText(value);
            AppearanceStyle appearanceStyle = new AppearanceStyle();
            appearanceStyle.setFont(font);
            appearanceStyle.setFontSize(fontSize);
            // Adobe Acrobat uses the font's bounding box for the leading between the lines
            appearanceStyle.setLeading(font.getBoundingBox().getHeight() * fontScaleY);
            PlainTextFormatter formatter = new PlainTextFormatter.Builder(contents).style(appearanceStyle).text(textContent).width(contentRect.getWidth()).wrapLines(isMultiLine()).initialOffset(x, y).textAlign(getTextAlign(widget)).build();
            formatter.format();
        }
        contents.endText();
        contents.restoreGraphicsState();
    }
}

/* Resolve the cap height.

This is a very basic implementation using the height of "H" as reference.
 */
private float resolveCapHeight(PDFont font) throws IOException {
    // PATH: Test should invoke the next AppearanceGeneratorHelper.resolveGlyphHeight(...) [step in execution path]
    return resolveGlyphHeight(font, "H".codePointAt(0));
}

// this calculates the real (except for type 3 fonts) individual glyph bounds
private float resolveGlyphHeight(PDFont font, int code) throws IOException {
    GeneralPath path = null;
    if (font instanceof PDType3Font) {
        // It is difficult to calculate the real individual glyph bounds for type 3
        // fonts
        // because these are not vector fonts, the content stream could contain almost
        // anything
        // that is found in page content streams.
        PDType3Font t3Font = ((PDType3Font) (font));
        PDType3CharProc charProc = t3Font.getCharProc(code);
        if (charProc != null) {
            // PATH: Test should invoke the next PDType3Font.getBoundingBox(...) [step in execution path]
            BoundingBox fontBBox = t3Font.getBoundingBox();
            PDRectangle glyphBBox = charProc.getGlyphBBox();
            if (glyphBBox != null) {
                // PDFBOX-3850: glyph bbox could be larger than the font bbox
                glyphBBox.setLowerLeftX(Math.max(fontBBox.getLowerLeftX(), glyphBBox.getLowerLeftX()));
                glyphBBox.setLowerLeftY(Math.max(fontBBox.getLowerLeftY(), glyphBBox.getLowerLeftY()));
                glyphBBox.setUpperRightX(Math.min(fontBBox.getUpperRightX(), glyphBBox.getUpperRightX()));
                glyphBBox.setUpperRightY(Math.min(fontBBox.getUpperRightY(), glyphBBox.getUpperRightY()));
                path = glyphBBox.toGeneralPath();
            }
        }
    } else if (font instanceof PDVectorFont) {
        PDVectorFont vectorFont = ((PDVectorFont) (font));
        path = vectorFont.getPath(code);
    } else if (font instanceof PDSimpleFont) {
        PDSimpleFont simpleFont = ((PDSimpleFont) (font));
        // these two lines do not always work, e.g. for the TT fonts in file 032431.pdf
        // which is why PDVectorFont is tried first.
        String name = simpleFont.getEncoding().getName(code);
        path = simpleFont.getPath(name);
    } else {
        // shouldn't happen, please open issue in JIRA
        LOG.warn("Unknown font class: " + font.getClass());
    }
    if (path == null) {
        return -1;
    }
    return ((float) (path.getBounds2D().getHeight()));
}

@Override
public BoundingBox getBoundingBox() {
    if (fontBBox == null) {
        // PATH: Test should invoke the next PDType3Font.generateBoundingBox(...) [step in execution path]
        fontBBox = generateBoundingBox();
    }
    return fontBBox;
}

private BoundingBox generateBoundingBox() {
    PDRectangle rect = getFontBBox();
    if (rect == null) {
        LOG.warn("FontBBox missing, returning empty rectangle");
        return new BoundingBox();
    }
    if (!isNonZeroBoundingBox(rect)) {
        // Plan B: get the max bounding box of the glyphs
        COSDictionary cp = getCharProcs();
        if (cp != null) {
            for (COSName name : cp.keySet()) {
                COSStream typ3CharProcStream = cp.getCOSStream(name);
                if (typ3CharProcStream != null) {
                    PDType3CharProc charProc = new PDType3CharProc(this, typ3CharProcStream);
                    try {
                        // PATH: Test should invoke the next PDType3CharProc.getGlyphBBox(...) [step in execution path]
                        PDRectangle glyphBBox = charProc.getGlyphBBox();
                        if (glyphBBox == null) {
                            continue;
                        }
                        rect.setLowerLeftX(Math.min(rect.getLowerLeftX(), glyphBBox.getLowerLeftX()));
                        rect.setLowerLeftY(Math.min(rect.getLowerLeftY(), glyphBBox.getLowerLeftY()));
                        rect.setUpperRightX(Math.max(rect.getUpperRightX(), glyphBBox.getUpperRightX()));
                        rect.setUpperRightY(Math.max(rect.getUpperRightY(), glyphBBox.getUpperRightY()));
                    } catch (IOException ex) {
                        // ignore
                        LOG.debug("error getting the glyph bounding box - font bounding box will be used", ex);
                    }
                }
            }
        }
    }
    return new BoundingBox(rect.getLowerLeftX(), rect.getLowerLeftY(), rect.getUpperRightX(), rect.getUpperRightY());
}

/**
 * Calculate the bounding box of this glyph. This will work only if the first operator in the
 * stream is d1.
 *
 * @return the bounding box of this glyph, or null if the first operator is not d1.
 * @throws IOException
 * 		If an io error occurs while parsing the stream.
 */
public PDRectangle getGlyphBBox() throws IOException {
    List<COSBase> arguments = new ArrayList<>();
    PDFStreamParser parser = new PDFStreamParser(this);
    // PATH: Test should invoke the next PDFStreamParser.parseNextToken(...) [step in execution path]
    Object token = parser.parseNextToken();
    while (token != null) {
        if (token instanceof Operator) {
            if (((Operator) (token)).getName().equals("d1") && (arguments.size() == 6)) {
                for (int i = 0; i < 6; ++i) {
                    if (!(arguments.get(i) instanceof COSNumber)) {
                        return null;
                    }
                }
                float x = ((COSNumber) (arguments.get(2))).floatValue();
                float y = ((COSNumber) (arguments.get(3))).floatValue();
                return new PDRectangle(x, y, ((COSNumber) (arguments.get(4))).floatValue() - x, ((COSNumber) (arguments.get(5))).floatValue() - y);
            } else {
                return null;
            }
        } else {
            arguments.add(((COSBase) (token)));
        }
        token = parser.parseNextToken();
    } 
    return null;
}

/**
 * This will parse the next token in the stream.
 *
 * @return The next token in the stream or null if there are no more tokens in the stream.
 * @throws IOException
 * 		If an io error occurs while parsing the stream.
 */
public Object parseNextToken() throws IOException {
    if (source.isClosed()) {
        return null;
    }
    skipSpaces();
    if (source.isEOF()) {
        close();
        return null;
    }
    char c = ((char) (source.peek()));
    switch (c) {
        case '<' :
            // pull off first left bracket
            source.read();
            // check for second left bracket
            c = ((char) (source.peek()));
            // put back first bracket
            source.rewind(1);
            if (c == '<') {
                try {
                    // PATH: Test should invoke the next BaseParser.parseCOSDictionary(...) [step in execution path]
                    return parseCOSDictionary(true);
                } catch (IOException exception) {
                    LOG.warn("Stop reading invalid dictionary from content stream at offset " + source.getPosition());
                    close();
                    return null;
                }
            } else {
                return parseCOSString();
            }
        case '[' :
            // array
            try {
                return parseCOSArray();
            } catch (IOException exception) {
                LOG.warn("Stop reading invalid array from content stream at offset " + source.getPosition());
                close();
                return null;
            }
        case '(' :
            // string
            return parseCOSString();
        case '/' :
            // name
            return parseCOSName();
        case 'n' :
            // null
            String nullString = readString();
            if (nullString.equals("null")) {
                return COSNull.NULL;
            } else {
                return Operator.getOperator(nullString);
            }
        case 't' :
        case 'f' :
            String next = readString();
            if (next.equals("true")) {
                return COSBoolean.TRUE;
            } else if (next.equals("false")) {
                return COSBoolean.FALSE;
            } else {
                return Operator.getOperator(next);
            }
        case '0' :
        case '1' :
        case '2' :
        case '3' :
        case '4' :
        case '5' :
        case '6' :
        case '7' :
        case '8' :
        case '9' :
        case '-' :
        case '+' :
        case '.' :
            /* We will be filling buf with the rest of the number.  Only
            allow 1 "." and "-" and "+" at start of number.
             */
            StringBuilder buf = new StringBuilder();
            buf.append(c);
            source.read();
            // Ignore double negative (this is consistent with Adobe Reader)
            if ((c == '-') && (source.peek() == c)) {
                source.read();
            }
            boolean dotNotRead = c != '.';
            while ((Character.isDigit(c = ((char) (source.peek()))) || (dotNotRead && (c == '.'))) || (c == '-')) {
                if (c != '-') {
                    // PDFBOX-4064: ignore "-" in the middle of a number
                    buf.append(c);
                }
                source.read();
                if (dotNotRead && (c == '.')) {
                    dotNotRead = false;
                }
            } 
            String s = buf.toString();
            if ("+".equals(s)) {
                // PDFBOX-5906
                LOG.warn("isolated '+' is ignored");
                return COSNull.NULL;
            }
            return COSNumber.get(s);
        case 'B' :
            String nextOperator = readString();
            Operator beginImageOP = Operator.getOperator(nextOperator);
            if (nextOperator.equals(OperatorName.BEGIN_INLINE_IMAGE)) {
                inlineImageDepth++;
                if (inlineImageDepth > 1) {
                    // PDFBOX-6038
                    throw new IOException((((("Nested '" + OperatorName.BEGIN_INLINE_IMAGE) + "' operator not allowed at offset ") + source.getPosition()) + ", first: ") + inlineOffset);
                } else {
                    inlineOffset = source.getPosition();
                }
                COSDictionary imageParams = new COSDictionary();
                beginImageOP.setImageParameters(imageParams);
                Object nextToken = null;
                while ((nextToken = parseNextToken()) instanceof COSName) {
                    Object value = parseNextToken();
                    if (!(value instanceof COSBase)) {
                        LOG.warn("Unexpected token in inline image dictionary at offset " + (source.isClosed() ? "EOF" : source.getPosition()));
                        break;
                    }
                    imageParams.setItem(((COSName) (nextToken)), ((COSBase) (value)));
                } 
                // final token will be the image data, maybe??
                if (nextToken instanceof Operator) {
                    Operator imageData = ((Operator) (nextToken));
                    if ((imageData.getImageData() == null) || (imageData.getImageData().length == 0)) {
                        LOG.warn("empty inline image at stream offset " + (source.isClosed() ? "EOF" : source.getPosition()));
                    }
                    beginImageOP.setImageData(imageData.getImageData());
                    inlineImageDepth--;
                } else {
                    LOG.warn(((((("nextToken " + nextToken) + " at position ") + (source.isClosed() ? "EOF" : source.getPosition())) + ", expected ") + OperatorName.BEGIN_INLINE_IMAGE_DATA) + "?!");
                }
            }
            return beginImageOP;
        case 'I' :
            // Special case for ID operator
            String id = Character.toString(((char) (source.read()))) + ((char) (source.read()));
            if (!id.equals(OperatorName.BEGIN_INLINE_IMAGE_DATA)) {
                long currentPosition = source.getPosition();
                close();
                throw new IOException((("Error: Expected operator 'ID' actual='" + id) + "' at stream offset ") + currentPosition);
            }
            ByteArrayOutputStream imageData = new ByteArrayOutputStream();
            // skip one line break (CR, LF or CRLF) or any one-byte whitespace
            if ((!skipLinebreak()) && isWhitespace()) {
                // pull off the whitespace character
                source.read();
            }
            int lastByte = source.read();
            int currentByte = source.read();
            // PDF spec is kinda unclear about this. Should a whitespace
            // always appear before EI? Not sure, so that we just read
            // until EI<whitespace>.
            // Be aware not all kind of whitespaces are allowed here. see PDFBOX-1561
            while ((!((((lastByte == 'E') && (currentByte == 'I')) && hasNextSpaceOrReturn()) && hasNoFollowingBinData())) && (!isEOF())) {
                imageData.write(lastByte);
                lastByte = currentByte;
                currentByte = source.read();
            } 
            // the EI operator isn't unread, as it won't be processed anyway
            Operator beginImageDataOP = Operator.getOperator(OperatorName.BEGIN_INLINE_IMAGE_DATA);
            // save the image data to the operator, so that it can be accessed later
            beginImageDataOP.setImageData(imageData.toByteArray());
            return beginImageDataOP;
        case ']' :
            // some ']' around without its previous '['
            // this means a PDF is somewhat corrupt but we will continue to parse.
            source.read();
            // must be a better solution than null...
            return COSNull.NULL;
        default :
            // we must be an operator
            String operator = readOperator().trim();
            if (operator.length() > 0) {
                return Operator.getOperator(operator);
            }
    }
    return null;
}

/**
 * This will parse a PDF dictionary.
 *
 * @param isDirect
 * 		indicates whether the dictionary to be read is a direct object
 * @return The parsed dictionary, never null.
 * @throws IOException
 * 		If there is an error reading the stream.
 */
protected COSDictionary parseCOSDictionary(boolean isDirect) throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        readExpectedChar('<');
        readExpectedChar('<');
        skipSpaces();
        COSDictionary obj = new COSDictionary();
        obj.setDirect(isDirect);
        while (true) {
            skipSpaces();
            char c = ((char) (source.peek()));
            if (c == '>') {
                break;
            } else if (c == '/') {
                // something went wrong, most likely the dictionary is corrupted
                // stop immediately and return everything read so far
                if (!parseCOSDictionaryNameValuePair(obj)) {
                    return obj;
                }
            } else // PATH: Test should invoke the next Log.warn(...) [step in execution path]
            {
                // invalid dictionary, we were expecting a /Name, read until the end or until we can recover
                LOG.warn((("Invalid dictionary, found: '" + c) + "' but expected: '/' at offset ") + source.getPosition());
                if (readUntilEndOfCOSDictionary()) {
                    // we couldn't recover
                    return obj;
                }
            }
        } 
        try {
            readExpectedChar('>');
            readExpectedChar('>');
        } catch (IOException exception) {
            LOG.warn("Invalid dictionary, can't find end of dictionary at offset " + source.getPosition());
        }
        return obj;
    } finally {
        recursionDepth--;
    }
}

