 */
AppearanceGeneratorHelper(PDVariableText field) throws IOException {
    this.field = field;
    validateAndEnsureAcroFormResources();
    try {
        this.defaultAppearance = field.getDefaultAppearanceString();
    } catch (IOException ex) {
