    } else if (!endStream.equals(ENDSTREAM_STRING)) {
        throw new IOException((("Error reading stream, expected='endstream' actual='" + endStream) + "' at offset ") + source.getPosition());
    }
    return document.createCOSStream(dic, streamStartPosition, streamLength);
}

private boolean validateStreamLength(long streamLength) throws IOException {
    long originOffset = source.getPosition();
    if (streamLength == 0) {
        // This may be valid (PDFBOX-5954), or not (PDFBOX-5880)
        LOG.debug("Suspicious stream length 0, stream position: " + originOffset);
        return false;
    } else if (streamLength < 0) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn((("Invalid stream length: " + streamLength) + ", start position: ") + originOffset);
        return false;
    }
    long expectedEndOfStream = originOffset + streamLength;
    if (expectedEndOfStream > fileLen) {
        LOG.warn(((((("The end of the stream is out of range, using workaround to read the stream, " + "stream start position: ") + originOffset) + ", length: ") + streamLength) + ", expected end position: ") + expectedEndOfStream);
        return false;
    }
    source.seek(expectedEndOfStream);
    skipSpaces();
    boolean endStreamFound = isString(ENDSTREAM);
    source.seek(originOffset);
    if (!endStreamFound) {
        LOG.warn(((((("The end of the stream doesn't point to the correct offset, using workaround to read the stream, " + "stream start position: ") + originOffset) + ", length: ") + streamLength) + ", expected end position: ") + expectedEndOfStream);
        return false;
    }
    return true;
}

