/**
 * Process a content stream.
 *
 * @param contentStream
 * 		the content stream
 * @throws IOException
 * 		if there is an exception while processing the stream
 */
private void processStream(PDContentStream contentStream) throws IOException {
    PDResources parent = pushResources(contentStream);
    Deque<PDGraphicsState> savedStack = saveGraphicsStack();
    Matrix parentMatrix = initialMatrix;
    PDGraphicsState graphicsState = getGraphicsState();
    // transform the CTM using the stream's matrix
    graphicsState.getCurrentTransformationMatrix().concatenate(contentStream.getMatrix());
    // the stream's initial matrix includes the parent CTM, e.g. this allows a scaled form
    initialMatrix = graphicsState.getCurrentTransformationMatrix().clone();
    // clip to bounding box
    PDRectangle bbox = contentStream.getBBox();
    clipToRect(bbox);
    try // PATH: Test should invoke the next PDFStreamEngine.processStreamOperators(...) [step in execution path]
    {
        processStreamOperators(contentStream);
    } finally {
        initialMatrix = parentMatrix;
        restoreGraphicsStack(savedStack);
        popResources(parent);
    }
}

/**
 * Processes the operators of the given content stream.
 *
 * @param contentStream
 * 		to content stream to parse.
 * @throws IOException
 * 		if there is an error reading or parsing the content stream.
 */
private void processStreamOperators(PDContentStream contentStream) throws IOException {
    List<COSBase> arguments = new ArrayList<>();
    PDFStreamParser parser = new PDFStreamParser(contentStream);
    Object token = parser.parseNextToken();
    boolean isFirstOperator = true;
    boolean oldShouldProcessColorOperators = shouldProcessColorOperators;
    shouldProcessColorOperators = true;
    if ((contentStream instanceof PDTilingPattern) && (((PDTilingPattern) (contentStream)).getPaintType() == PDTilingPattern.PAINT_UNCOLORED)) {
        shouldProcessColorOperators = false;
    }
    try {
        while (token != null) {
            if (token instanceof Operator) // PATH: Test should invoke the next PDFStreamEngine.processOperator(...) [step in execution path]
            {
                if ((isFirstOperator && (contentStream instanceof PDType3CharProc)) && OperatorName.TYPE3_D1.equals(((Operator) (token)).getName())) {
                    shouldProcessColorOperators = false;
                }
                isFirstOperator = false;
                processOperator(((Operator) (token)), arguments);
                arguments.clear();
            } else {
                arguments.add(((COSBase) (token)));
            }
            token = parser.parseNextToken();
        } 
    } finally {
        shouldProcessColorOperators = oldShouldProcessColorOperators;
    }
}

/**
 * This is used to handle an operation.
 *
 * @param operator
 * 		The operation to perform.
 * @param operands
 * 		The list of arguments.
 * @throws IOException
 * 		If there is an error processing the operation.
 */
protected void processOperator(Operator operator, List<COSBase> operands) throws IOException {
    String name = operator.getName();
    OperatorProcessor processor = operators.get(name);
    if (processor != null) {
        try // PATH: Test should invoke the next SetGraphicsStateParameters.process(...) [step in execution path]
        {
            processor.process(operator, operands);
        } catch (IOException e) {
            operatorException(operator, operands, e);
        }
    } else {
        unsupportedOperator(operator, operands);
    }
}

@Override
public void process(Operator operator, List<COSBase> arguments) throws IOException // PATH: Test should invoke the next PDExtendedGraphicsState.copyIntoGraphicsState(...) [step in execution path]
{
    if (arguments.isEmpty()) {
        throw new MissingOperandException(operator, arguments);
    }
    COSBase base0 = arguments.get(0);
    if (!(base0 instanceof COSName)) {
        return;
    }
    // set parameters from graphics state parameter dictionary
    COSName graphicsName = ((COSName) (base0));
    PDFStreamEngine context = getContext();
    PDExtendedGraphicsState gs = context.getResources().getExtGState(graphicsName);
    if (gs == null) {
        LOG.error("name for 'gs' operator not found in resources: /" + graphicsName.getName());
        return;
    }
    gs.copyIntoGraphicsState(context.getGraphicsState());
}

/**
 * This will implement the gs operator.
 *
 * @param gs
 * 		The state to copy this dictionaries values into.
 * @throws IOException
 * 		If there is an error copying font information.
 */
public void copyIntoGraphicsState(PDGraphicsState gs) throws IOException {
    for (COSName key : dict.keySet()) {
        if (key.equals(COSName.LW)) {
            gs.setLineWidth(defaultIfNull(getLineWidth(), 1));
        } else if (key.equals(COSName.LC)) {
            gs.setLineCap(getLineCapStyle());
        } else if (key.equals(COSName.LJ)) {
            gs.setLineJoin(getLineJoinStyle());
        } else if (key.equals(COSName.ML)) {
            gs.setMiterLimit(defaultIfNull(getMiterLimit(), 10));
        } else if (key.equals(COSName.D)) {
            gs.setLineDashPattern(getLineDashPattern());
        } else if (key.equals(COSName.RI)) {
            gs.setRenderingIntent(getRenderingIntent());
        } else if (key.equals(COSName.OPM)) {
            Integer overprintMode = getOverprintMode();
            gs.setOverprintMode(overprintMode != null ? overprintMode : 0);
        } else if (key.equals(COSName.OP)) {
            gs.setOverprint(getStrokingOverprintControl());
        } else if (key.equals(COSName.OP_NS)) {
            gs.setNonStrokingOverprint(getNonStrokingOverprintControl());
        } else if (key.equals(COSName.FONT)) {
            PDFontSetting setting = getFontSetting();
            if (setting != null) {
                // PATH: Test should invoke the next PDFontSetting.getFont(...) [step in execution path]
                gs.getTextState().setFont(setting.getFont());
                gs.getTextState().setFontSize(setting.getFontSize());
            }
        } else if (key.equals(COSName.FL)) {
            gs.setFlatness(defaultIfNull(getFlatnessTolerance(), 1.0F));
        } else if (key.equals(COSName.SM)) {
            gs.setSmoothness(defaultIfNull(getSmoothnessTolerance(), 0));
        } else if (key.equals(COSName.SA)) {
            gs.setStrokeAdjustment(getAutomaticStrokeAdjustment());
        } else if (key.equals(COSName.CA)) {
            gs.setAlphaConstant(defaultIfNull(getStrokingAlphaConstant(), 1.0F));
        } else if (key.equals(COSName.CA_NS)) {
            gs.setNonStrokeAlphaConstant(defaultIfNull(getNonStrokingAlphaConstant(), 1.0F));
        } else if (key.equals(COSName.AIS)) {
            gs.setAlphaSource(getAlphaSourceFlag());
        } else if (key.equals(COSName.TK)) {
            gs.getTextState().setKnockoutFlag(getTextKnockoutFlag());
        } else if (key.equals(COSName.SMASK)) {
            PDSoftMask softmask = getSoftMask();
            if (softmask != null) {
                // Softmask must know the CTM at the time the ExtGState is activated. Read
                // https://bugs.ghostscript.com/show_bug.cgi?id=691157#c7 for a good explanation.
                softmask.setInitialTransformationMatrix(gs.getCurrentTransformationMatrix().clone());
            }
            gs.setSoftMask(softmask);
        } else if (key.equals(COSName.BM)) {
            gs.setBlendMode(getBlendMode());
        } else if (key.equals(COSName.TR)) {
            if (dict.containsKey(COSName.TR2)) {
