                // TR2 shall take precedence."
                continue;
            }
            gs.setTransfer(getTransfer());
        } else if (key.equals(COSName.TR2)) {
            gs.setTransfer(getTransfer2());
        }
    }
}

/**
 * This will get the font for this font setting.
