    // it by combining single lines instead of creating a simple rectangle
    linePath.moveTo(((float) (p0.getX())), ((float) (p0.getY())));
    linePath.lineTo(((float) (p1.getX())), ((float) (p1.getY())));
    linePath.lineTo(((float) (p2.getX())), ((float) (p2.getY())));
