    if ((exportValues.isEmpty() || (index < 0)) || (index >= exportValues.size())) {
        throw new IllegalArgumentException((((("index '" + index) + "' is not a valid index for the field ") + getFullyQualifiedName()) + ", valid indices are from 0 to ") + (exportValues.size() - 1));
    }
