 * @param at
 * 		the transformation
 * @throws IOException
 * 		if something went wrong
 */
private void drawGlyph(GeneralPath path, PDFont font, int code, Vector displacement, AffineTransform at) throws IOException {
    PDGraphicsState state = getGraphicsState();
