/**
 * Merge the list of source documents, saving the result in the destination file. The source
 * list is not reset after merge. If you want to merge one document at a time, then it's better
 * to use
 * {@link #appendDocument(org.apache.pdfbox.pdmodel.PDDocument, org.apache.pdfbox.pdmodel.PDDocument)}.
 *
 * @param streamCacheCreateFunction
 * 		a function to create an instance of a stream cache; in case of <code>null</code>
 * 		unrestricted main memory is used
 * @param compressParameters
 * 		defines if compressed object streams are enabled
 * @throws IOException
 * 		If there is an error saving the document.
 */
public void mergeDocuments(StreamCacheCreateFunction streamCacheCreateFunction, CompressParameters compressParameters) throws IOException {
    if (documentMergeMode == DocumentMergeMode.PDFBOX_LEGACY_MODE) // PATH: Test should invoke the next PDFMergerUtility.legacyMergeDocuments(...) [step in execution path]
    {
        legacyMergeDocuments(streamCacheCreateFunction, compressParameters);
    } else if (documentMergeMode == DocumentMergeMode.OPTIMIZE_RESOURCES_MODE) {
        optimizedMergeDocuments(streamCacheCreateFunction, compressParameters);
    }
}

/**
 * Merge the list of source documents, saving the result in the destination file.
 *
 * @param streamCacheCreateFunction
 * 		a function to create an instance of a stream cache; in case of <code>null</code>
 * 		unrestricted main memory is used
 * @throws IOException
 * 		If there is an error saving the document.
 */
private void legacyMergeDocuments(StreamCacheCreateFunction streamCacheCreateFunction, CompressParameters compressParameters) throws IOException {
    if (!sources.isEmpty()) {
        // Make sure that:
        // - first Exception is kept
        // - all PDDocuments are closed
        // - all FileInputStreams are closed
        // - there's a way to see which errors occurred
        StreamCacheCreateFunction strmCacheFunc = (streamCacheCreateFunction != null) ? streamCacheCreateFunction : IOUtils.createMemoryOnlyStreamCache();
        try (PDDocument destination = new PDDocument(strmCacheFunc)) {
            for (Object sourceObject : sources) {
                PDDocument sourceDoc;
                if (sourceObject instanceof File) {
                    sourceDoc = Loader.loadPDF(((File) (sourceObject)));
                } else {
                    sourceDoc = Loader.loadPDF(((RandomAccessRead) (sourceObject)));
                }
                try // PATH: Test should invoke the next PDFMergerUtility.appendDocument(...) [step in execution path]
                {
                    appendDocument(destination, sourceDoc);
                } finally {
                    IOUtils.closeAndLogException(sourceDoc, LOG, "PDDocument", null);
                }
            }
            // optionally set meta data
            if (destinationDocumentInformation != null) {
                destination.setDocumentInformation(destinationDocumentInformation);
            }
            if (destinationMetadata != null) {
                destination.getDocumentCatalog().setMetadata(destinationMetadata);
            }
            if (destinationStream == null) {
                destination.save(destinationFileName, compressParameters);
            } else {
                destination.save(destinationStream, compressParameters);
            }
        }
    }
}

/**
 * append all pages from source to destination.
 *
 * @param destination
 * 		the document to receive the pages
 * @param source
 * 		the document originating the new pages
 * @throws IOException
 * 		If there is an error accessing data from either
 * 		document.
 */
public void appendDocument(PDDocument destination, PDDocument source) throws IOException {
    PDFCloneUtility cloner = new PDFCloneUtility(destination);
    if (source.getDocument().isClosed()) {
        throw new IOException("Error: source PDF is closed.");
    }
    if (destination.getDocument().isClosed()) {
        throw new IOException("Error: destination PDF is closed.");
    }
    PDDocumentCatalog srcCatalog = source.getDocumentCatalog();
    if (// PATH: Test should invoke the next PDDocumentCatalog.getAcroForm(...) [step in execution path]
    isDynamicXfa(srcCatalog.getAcroForm())) {
        throw new IOException("Error: can't merge source document containing dynamic XFA form content.");
    }
    PDDocumentInformation destInfo = destination.getDocumentInformation();
    PDDocumentInformation srcInfo = source.getDocumentInformation();
    mergeInto(srcInfo.getCOSObject(), destInfo.getCOSObject(), cloner, Collections.emptySet());
    // use the highest version number for the resulting pdf
    float destVersion = destination.getVersion();
    float srcVersion = source.getVersion();
    if (destVersion < srcVersion) {
        destination.setVersion(srcVersion);
    }
    PDDocumentCatalog destCatalog = destination.getDocumentCatalog();
    mergeAcroForm(cloner, destCatalog, srcCatalog);
    COSArray destThreads = destCatalog.getCOSObject().getCOSArray(COSName.THREADS);
    COSArray srcThreads = cloner.cloneForNewDocument(destCatalog.getCOSObject().getCOSArray(COSName.THREADS));
    if (destThreads == null) {
        destCatalog.getCOSObject().setItem(COSName.THREADS, srcThreads);
    } else {
        destThreads.addAll(srcThreads);
    }
    PDDocumentNameDictionary destNames = destCatalog.getNames();
    PDDocumentNameDictionary srcNames = srcCatalog.getNames();
    if (srcNames != null) {
        if (destNames == null) {
            destCatalog.getCOSObject().setItem(COSName.NAMES, cloner.cloneForNewDocument(srcNames.getCOSObject()));
        } else {
            cloner.cloneMerge(srcNames, destNames);
        }
    }
    if ((destNames != null) && destNames.getCOSObject().containsKey(COSName.ID_TREE)) {
        // found in 001031.pdf from PDFBOX-4417 and doesn't belong there
        destNames.getCOSObject().removeItem(COSName.ID_TREE);
        LOG.warn("Removed /IDTree from /Names dictionary, doesn't belong there");
    }
    PDDocumentNameDestinationDictionary srcDests = srcCatalog.getDests();
    if (srcDests != null) {
        PDDocumentNameDestinationDictionary destDests = destCatalog.getDests();
        if (destDests == null) {
            destCatalog.getCOSObject().setItem(COSName.DESTS, cloner.cloneForNewDocument(srcDests.getCOSObject()));
        } else {
            cloner.cloneMerge(srcDests, destDests);
        }
    }
    PDDocumentOutline srcOutline = srcCatalog.getDocumentOutline();
    if (srcOutline != null) {
        PDDocumentOutline destOutline = destCatalog.getDocumentOutline();
        if ((destOutline == null) || (destOutline.getFirstChild() == null)) {
            PDDocumentOutline cloned = new PDDocumentOutline(cloner.cloneForNewDocument(srcOutline.getCOSObject()));
            destCatalog.setDocumentOutline(cloned);
        } else {
            // search last sibling for dest, because /Last entry is sometimes wrong
            PDOutlineItem destLastOutlineItem = destOutline.getFirstChild();
            while (true) {
                PDOutlineItem outlineItem = destLastOutlineItem.getNextSibling();
                if (outlineItem == null) {
                    break;
                }
                destLastOutlineItem = outlineItem;
            } 
            for (PDOutlineItem item : srcOutline.children()) {
                // get each child, clone its dictionary, remove siblings info,
                // append outline item created from there
                COSDictionary clonedDict = cloner.cloneForNewDocument(item.getCOSObject());
                clonedDict.removeItem(COSName.PREV);
                clonedDict.removeItem(COSName.NEXT);
                PDOutlineItem clonedItem = new PDOutlineItem(clonedDict);
                destLastOutlineItem.insertSiblingAfter(clonedItem);
                destLastOutlineItem = destLastOutlineItem.getNextSibling();
            }
        }
    }
    PageMode destPageMode = destCatalog.getPageMode();
    if (destPageMode == null) {
        PageMode srcPageMode = srcCatalog.getPageMode();
        destCatalog.setPageMode(srcPageMode);
    }
    COSDictionary srcLabels = srcCatalog.getCOSObject().getCOSDictionary(COSName.PAGE_LABELS);
    if (srcLabels != null) {
        int destPageCount = destination.getNumberOfPages();
        COSArray destNums;
        COSDictionary destLabels = destCatalog.getCOSObject().getCOSDictionary(COSName.PAGE_LABELS);
        if (destLabels == null) {
            destLabels = new COSDictionary();
            destNums = new COSArray();
            destLabels.setItem(COSName.NUMS, destNums);
            destCatalog.getCOSObject().setItem(COSName.PAGE_LABELS, destLabels);
        } else {
            destNums = destLabels.getCOSArray(COSName.NUMS);
        }
        COSArray srcNums = srcLabels.getCOSArray(COSName.NUMS);
        if (srcNums != null) {
            int startSize = destNums.size();
            for (int i = 0; i < srcNums.size(); i += 2) {
                COSBase base = srcNums.getObject(i);
                if (!(base instanceof COSNumber)) {
                    LOG.error((("page labels ignored, index " + i) + " should be a number, but is ") + base);
                    // remove what we added
                    while (destNums.size() > startSize) {
                        destNums.remove(startSize);
                    } 
                    break;
                }
                COSNumber labelIndex = ((COSNumber) (base));
                long labelIndexValue = labelIndex.intValue();
                destNums.add(COSInteger.get(labelIndexValue + destPageCount));
                destNums.add(cloner.cloneForNewDocument(srcNums.getObject(i + 1)));
            }
        }
    }
    COSStream destMetadata = destCatalog.getCOSObject().getCOSStream(COSName.METADATA);
    COSStream srcMetadata = srcCatalog.getCOSObject().getCOSStream(COSName.METADATA);
    if ((destMetadata == null) && (srcMetadata != null)) {
        try {
            PDStream newStream = new PDStream(destination, srcMetadata.createInputStream(), ((COSName) (null)));
            mergeInto(srcMetadata, newStream.getCOSObject(), cloner, new HashSet<>(Arrays.asList(COSName.FILTER, COSName.LENGTH)));
            destCatalog.getCOSObject().setItem(COSName.METADATA, newStream);
        } catch (IOException ex) {
            // PDFBOX-4227 cleartext XMP stream with /Flate
            LOG.error("Metadata skipped because it could not be read", ex);
        }
    }
    COSDictionary destOCP = destCatalog.getCOSObject().getCOSDictionary(COSName.OCPROPERTIES);
    COSDictionary srcOCP = srcCatalog.getCOSObject().getCOSDictionary(COSName.OCPROPERTIES);
    if ((destOCP == null) && (srcOCP != null)) {
        destCatalog.getCOSObject().setItem(COSName.OCPROPERTIES, cloner.cloneForNewDocument(srcOCP));
    } else if ((destOCP != null) && (srcOCP != null)) {
        cloner.cloneMerge(srcOCP, destOCP);
    }
    mergeOutputIntents(srcCatalog, destCatalog, cloner);
    // merge logical structure hierarchy
    boolean mergeStructTree = false;
    int destParentTreeNextKey = -1;
    Map<Integer, COSObjectable> srcNumberTreeAsMap = null;
    Map<Integer, COSObjectable> destNumberTreeAsMap = null;
    PDStructureTreeRoot srcStructTree = srcCatalog.getStructureTreeRoot();
    PDStructureTreeRoot destStructTree = destCatalog.getStructureTreeRoot();
    if ((destStructTree == null) && (srcStructTree != null)) {
        // create a dummy structure tree in the destination, so that the source
        // tree is cloned. (We can't just copy the tree reference due to PDFBOX-3999)
        destStructTree = new PDStructureTreeRoot();
        destCatalog.setStructureTreeRoot(destStructTree);
        destStructTree.setParentTree(new PDNumberTreeNode(PDParentTreeValue.class));
        // PDFBOX-4429: remove bogus StructParent(s)
        for (PDPage page : destCatalog.getPages()) {
            page.getCOSObject().removeItem(COSName.STRUCT_PARENTS);
            for (PDAnnotation ann : page.getAnnotations()) {
                ann.getCOSObject().removeItem(COSName.STRUCT_PARENT);
            }
        }
    }
    if (destStructTree != null) {
        PDNumberTreeNode destParentTree = destStructTree.getParentTree();
        destParentTreeNextKey = destStructTree.getParentTreeNextKey();
        if (destParentTree != null) {
            destNumberTreeAsMap = getNumberTreeAsMap(destParentTree);
            if (destParentTreeNextKey < 0) {
                if (destNumberTreeAsMap.isEmpty()) {
                    destParentTreeNextKey = 0;
                } else {
                    destParentTreeNextKey = Collections.max(destNumberTreeAsMap.keySet()) + 1;
                }
            }
            if ((destParentTreeNextKey >= 0) && (srcStructTree != null)) {
                PDNumberTreeNode srcParentTree = srcStructTree.getParentTree();
                if (srcParentTree != null) {
                    srcNumberTreeAsMap = getNumberTreeAsMap(srcParentTree);
                    if (!srcNumberTreeAsMap.isEmpty()) {
                        mergeStructTree = true;
                    }
                }
            }
        }
    }
    Map<COSDictionary, COSDictionary> objMapping = new HashMap<>();
    PDPageTree destinationPageTree = destination.getPages();// cache PageTree

    for (PDPage page : srcCatalog.getPages()) {
        PDPage newPage = new PDPage(cloner.cloneForNewDocument(page.getCOSObject()));
        if (!mergeStructTree) {
            // PDFBOX-4429: remove bogus StructParent(s)
            newPage.getCOSObject().removeItem(COSName.STRUCT_PARENTS);
            for (PDAnnotation ann : newPage.getAnnotations()) {
                ann.getCOSObject().removeItem(COSName.STRUCT_PARENT);
            }
        }
        newPage.setCropBox(page.getCropBox());
        newPage.setMediaBox(page.getMediaBox());
        newPage.setRotation(page.getRotation());
        PDResources resources = page.getResources();
        if (resources != null) {
            // this is smart enough to just create references for resources that are used on multiple pages
            newPage.setResources(new PDResources(cloner.cloneForNewDocument(resources.getCOSObject())));
        } else {
            newPage.setResources(new PDResources());
        }
        if (mergeStructTree) {
            // add the value of the destination ParentTreeNextKey to every source element
            // StructParent(s) value so that these don't overlap with the existing values
            updateStructParentEntries(newPage, destParentTreeNextKey);
            objMapping.put(page.getCOSObject(), newPage.getCOSObject());
            List<PDAnnotation> oldAnnots = page.getAnnotations();
            List<PDAnnotation> newAnnots = newPage.getAnnotations();
            for (int i = 0; i < oldAnnots.size(); i++) {
                objMapping.put(oldAnnots.get(i).getCOSObject(), newAnnots.get(i).getCOSObject());
            }
            // TODO update mapping for XObjects
        }
        destinationPageTree.add(newPage);
    }
    mergeOpenAction(srcCatalog, destCatalog, cloner);
    if (mergeStructTree) {
        updatePageReferences(cloner, srcNumberTreeAsMap, objMapping);
        int maxSrcKey = -1;
        for (Map.Entry<Integer, COSObjectable> entry : srcNumberTreeAsMap.entrySet()) {
            int srcKey = entry.getKey();
            maxSrcKey = Math.max(srcKey, maxSrcKey);
            COSObjectable value = entry.getValue();
            if (value != null) {
                value = cloner.cloneForNewDocument(value.getCOSObject());
                destNumberTreeAsMap.put(destParentTreeNextKey + srcKey, value);
            }
        }
        destParentTreeNextKey += maxSrcKey + 1;
        PDNumberTreeNode newParentTreeNode = new PDNumberTreeNode(PDParentTreeValue.class);
        // Note that all elements are stored flatly. This could become a problem for large files
        // when these are opened in a viewer that uses the tagging information.
        // If this happens, then PDNumberTreeNode should be improved with a convenience method that
        // stores the map into a B+Tree, see https://en.wikipedia.org/wiki/B+_tree
        newParentTreeNode.setNumbers(destNumberTreeAsMap);
        destStructTree.setParentTree(newParentTreeNode);
        destStructTree.setParentTreeNextKey(destParentTreeNextKey);
        mergeKEntries(cloner, srcStructTree, destStructTree);
        mergeRoleMap(srcStructTree, destStructTree, cloner);
        mergeIDTree(cloner, srcStructTree, destStructTree);
        mergeMarkInfo(destCatalog, srcCatalog);
        mergeLanguage(destCatalog, srcCatalog);
        mergeViewerPreferences(destCatalog, srcCatalog, cloner);
    }
}

/**
 * Get the documents AcroForm. This will return null if no AcroForm is part of the document.
 *
 * @return The document's AcroForm.
 */
public PDAcroForm getAcroForm() {
    // PATH: Test should invoke the next PDDocumentCatalog.getAcroForm(...) [step in execution path]
    return getAcroForm(new AcroFormDefaultFixup(document));
}

/**
 * Get the documents AcroForm. This will return null if no AcroForm is part of the document.
 *
 * Dependent on setting <code>acroFormFixup</code> some fixing/changes will be done to the AcroForm.
 * If you need to ensure that there are no fixes applied call <code>getAcroForm</code> with <code>null</code>.
 *
 * Using <code>getAcroForm(PDDocumentFixup acroFormFixup)</code> might change the original content and
 * subsequent calls with <code>getAcroForm(null)</code> will return the changed content.
 *
 * @param acroFormFixup
 * 		the fix up action or null
 * @return The document's AcroForm.
 */
public PDAcroForm getAcroForm(PDDocumentFixup acroFormFixup) {
    if ((acroFormFixup != null) && (acroFormFixup != acroFormFixupApplied)) // PATH: Test should invoke the next AcroFormDefaultFixup.apply(...) [step in execution path]
    {
        acroFormFixup.apply();
        cachedAcroForm = null;
        acroFormFixupApplied = acroFormFixup;
    } else if (acroFormFixupApplied != null) {
        LOG.debug("AcroForm content has already been retrieved with fixes applied - original content changed because of that");
    }
    if (cachedAcroForm == null) {
        COSDictionary dict = root.getCOSDictionary(COSName.ACRO_FORM);
        cachedAcroForm = (dict == null) ? null : new PDAcroForm(document, dict);
    }
    return cachedAcroForm;
}

@Override
public void apply() {
    new AcroFormDefaultsProcessor(document).process();
    /* Get the AcroForm in it's current state.

    Also note: getAcroForm() applies a default fixup which this processor
    is part of. So keep the null parameter otherwise this will end
    in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    // PDFBOX-4985
    // build the visual appearance as there is none for the widgets
    if ((acroForm != null) && acroForm.getNeedAppearances()) {
        if (acroForm.getFields().isEmpty()) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.process(...) [step in execution path]
        {
            new AcroFormOrphanWidgetsProcessor(document).process();
        }
        // PDFBOX-4985
        // build the visual appearance as there is none for the widgets
        new AcroFormGenerateAppearancesProcessor(document).process();
    }
}

@Override
public void process() {
    /* Get the AcroForm in it's current state.

    Also note: getAcroForm() applies a default fixup which this processor
    is part of. So keep the null parameter otherwise this will end
    in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    if (acroForm != null) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.resolveFieldsFromWidgets(...) [step in execution path]
    {
        resolveFieldsFromWidgets(acroForm);
    }
}

private void resolveFieldsFromWidgets(PDAcroForm acroForm) {
    LOG.debug("rebuilding fields from widgets");
    PDResources resources = acroForm.getDefaultResources();
    if (resources == null) {
        // failsafe. Currently resources is never null because defaultfixup is called first.
        LOG.debug("AcroForm default resources is null");
        return;
    }
    List<PDField> fields = new ArrayList<>();
    Map<String, PDField> nonTerminalFieldsMap = new HashMap<>();
    for (PDPage page : document.getPages()) {
        try {
            handleAnnotations(acroForm, resources, fields, page.getAnnotations(), nonTerminalFieldsMap);
        } catch (IOException ioe) {
            LOG.debug("couldn't read annotations for page " + ioe.getMessage());
        }
    }
    acroForm.setFields(fields);
    for (PDField field : acroForm.getFieldTree()) {
        if (field instanceof PDVariableText) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.ensureFontResources(...) [step in execution path]
        {
            ensureFontResources(resources, ((PDVariableText) (field)));
        }
    }
}

/* Lookup the font used in the default appearance and if this is 
not available try to find a suitable font and use that.
This may not be the original font but a similar font replacement

TODO: implement a font lookup similar as discussed in PDFBOX-2661 so that already existing
font resources might be accepatble.
In such case this must be implemented in PDDefaultAppearanceString too!
 */
private void ensureFontResources(PDResources defaultResources, PDVariableText field) {
    String daString = field.getDefaultAppearance();
    if (daString.startsWith("/") && (daString.length() > 1)) {
        COSName fontName = COSName.getPDFName(daString.substring(1, daString.indexOf(" ")));
        try {
            if (defaultResources.getFont(fontName) == null) {
                if (LOG.isDebugEnabled()) {
                    LOG.debug("trying to add missing font resource for field " + field.getFullyQualifiedName());
                }
                FontMapper mapper = FontMappers.instance();
                // PATH: Test should invoke the next FontMapperImpl.getTrueTypeFont(...) [step in execution path]
                FontMapping<TrueTypeFont> fontMapping = mapper.getTrueTypeFont(fontName.getName(), null);
                if (fontMapping != null) {
                    PDType0Font pdFont = PDType0Font.load(document, fontMapping.getFont(), false);
                    if (LOG.isDebugEnabled()) {
                        LOG.debug((("looked up font for " + fontName.getName()) + " - found ") + fontMapping.getFont().getName());
                    }
                    defaultResources.put(fontName, pdFont);
                } else if (LOG.isDebugEnabled()) {
                    LOG.debug((("no suitable font found for field " + field.getFullyQualifiedName()) + " for font name ") + fontName.getName());
                }
            }
        } catch (IOException ioe) {
            LOG.debug((("unable to handle font resources for field " + field.getFullyQualifiedName()) + ": ") + ioe.getMessage());
        }
    }
}

/**
 * Finds a TrueType font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param fontDescriptor
 * 		FontDescriptor
 */
@Override
public FontMapping<TrueTypeFont> getTrueTypeFont(String baseFont, PDFontDescriptor fontDescriptor) {
    // PATH: Test should invoke the next FontMapperImpl.findFont(...) [step in execution path]
    TrueTypeFont ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, baseFont)));
    if (ttf != null) {
        return new FontMapping<>(ttf, false);
    } else {
        // fallback - todo: i.e. fuzzy match
        String fontName = getFallbackFontName(fontDescriptor);
        ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, fontName)));
        if (ttf == null) {
            // we have to return something here as TTFs aren't strictly required on the system
            ttf = lastResortFont;
        }
        return new FontMapping<>(ttf, true);
    }
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param postScriptName
 * 		PostScript font name
 */
private FontBoxFont findFont(FontFormat format, String postScriptName) {
    // handle damaged PDFs, see PDFBOX-2884
    if (postScriptName == null) {
        return null;
    }
    // make sure the font provider is initialized
    if (fontProvider == null) {
        getProvider();
    }
    // first try to match the PostScript name
    // PATH: Test should invoke the next FontMapperImpl.getFont(...) [step in execution path]
    FontInfo info = getFont(format, postScriptName);
    if (info != null) {
        return info.getFont();
    }
    // remove hyphens (e.g. Arial-Black -> ArialBlack)
    info = getFont(format, postScriptName.replace("-", ""));
    if (info != null) {
        return info.getFont();
    }
    // then try named substitutes
    for (String substituteName : getSubstitutes(postScriptName)) {
        info = getFont(format, substituteName);
        if (info != null) {
            return info.getFont();
        }
    }
    // then try converting Windows names e.g. (ArialNarrow,Bold) -> (ArialNarrow-Bold)
    info = getFont(format, postScriptName.replace(",", "-"));
    if (info != null) {
        return info.getFont();
    }
    if (postScriptName.contains(",")) {
        postScriptName = postScriptName.substring(0, postScriptName.indexOf(","));
        // PDFBOX-5806: try cutting font style and getting the basefont
        // eg. for "Wingdings,Bolt" to "Wingding-Regular" (including the following step)
        info = getFont(format, postScriptName);
        if (info != null) {
            return info.getFont();
        }
    }
    // try appending "-Regular", works for Wingdings on windows
    info = getFont(format, postScriptName + "-Regular");
    if (info != null) {
        return info.getFont();
    }
    // no matches
    return null;
}

/**
 * Finds the named font with the given format.
 */
private FontInfo getFont(FontFormat format, String postScriptName) {
    int index = postScriptName.indexOf('+');
    // strip subset tag (happens when we substitute a corrupt embedded font, see PDFBOX-2642)
    if (index > (-1)) {
        postScriptName = postScriptName.substring(index + 1);
    }
    // look up the PostScript name
    FontInfo info = fontInfoByName.get(postScriptName.toLowerCase(Locale.ENGLISH));
    if ((info != null) && (info.getFormat() == format)) {
        if (LOG.isDebugEnabled()) // PATH: Test should invoke the next Log.debug(...) [step in execution path]
        {
            LOG.debug(String.format("getFont('%s','%s') returns %s", format, postScriptName, info));
        }
        return info;
    }
    return null;
}

