/**
 * Returns an AWT paint for the given PDColor.
 *
 * @param color
 * 		The color to get a paint for. This can be an actual color or a pattern.
 * @return an AWT paint for the given PDColor
 * @throws IOException
 * 		if the AWT paint could not be created
 */
protected Paint getPaint(PDColor color) throws IOException {
    PDColorSpace colorSpace = color.getColorSpace();
    // PDFBOX-5782
    if (colorSpace == null) {
        LOG.error("colorSpace is null, will be rendered as transparency");
        return new Color(0, 0, 0, 0);
    } else if ((colorSpace instanceof PDSeparation) && "None".equals(((PDSeparation) (colorSpace)).getColorantName())) {
        // PDFBOX-4900: "The special colorant name None shall not produce any visible output"
        // TODO better solution needs to be found for all occurences where toRGB is called
        return new Color(0, 0, 0, 0);
    } else if (!(colorSpace instanceof PDPattern)) {
        float[] rgb = colorSpace.toRGB(color.getComponents());
        return new Color(clampColor(rgb[0]), clampColor(rgb[1]), clampColor(rgb[2]));
    } else {
        PDPattern patternSpace = ((PDPattern) (colorSpace));
        PDAbstractPattern pattern = patternSpace.getPattern(color);
        if (pattern instanceof PDTilingPattern) {
            PDTilingPattern tilingPattern = ((PDTilingPattern) (pattern));
            if (tilingPattern.getPaintType() == PDTilingPattern.PAINT_COLORED) {
                // colored tiling pattern
                // PATH: Test should invoke the next TilingPaintFactory.create(...) [step in execution path]
                return tilingPaintFactory.create(tilingPattern, null, null, xform);
            } else {
                // uncolored tiling pattern
                return tilingPaintFactory.create(tilingPattern, patternSpace.getUnderlyingColorSpace(), color, xform);
            }
        } else {
            PDShadingPattern shadingPattern = ((PDShadingPattern) (pattern));
            PDShading shading = shadingPattern.getShading();
            if (shading == null) {
                LOG.error("shadingPattern is null, will be filled with transparency");
                return new Color(0, 0, 0, 0);
            }
            return shading.toPaint(Matrix.concatenate(getInitialMatrix(), shadingPattern.getMatrix()));
        }
    }
}

Paint create(PDTilingPattern pattern, PDColorSpace colorSpace, PDColor color, AffineTransform xform) throws IOException {
    Paint paint = null;
    TilingPaintParameter tilingPaintParameter = new TilingPaintParameter(drawer.getInitialMatrix(), pattern.getCOSObject(), colorSpace, color, xform);
    WeakReference<Paint> weakRef = weakCache.get(tilingPaintParameter);
    if (weakRef != null) {
        // PDFBOX-4058: additional WeakReference makes gc work better
        paint = weakRef.get();
    }
    if (paint == null) {
        paint = new TilingPaint(drawer, pattern, colorSpace, color, xform);
        weakCache.put(tilingPaintParameter, new WeakReference<>(paint));
    }
    return paint;
}

/**
