    if (trueTypeFont != null) {
        ttf = trueTypeFont;
        otf = ((trueTypeFont instanceof OpenTypeFont) && ((OpenTypeFont) (trueTypeFont)).isSupportedOTF()) ? ((OpenTypeFont) (trueTypeFont)) : null;
        isEmbedded = true;
        isDamaged = false;
    } else {
        boolean fontIsDamaged = false;
        TrueTypeFont ttfFont = null;
        PDStream stream = null;
        if (fd != null) {
            stream = fd.getFontFile2();
            if (stream == null) {
                stream = fd.getFontFile3();
