@Override
public void apply() {
    new AcroFormDefaultsProcessor(document).process();
    /* Get the AcroForm in it's current state.

    Also note: getAcroForm() applies a default fixup which this processor
    is part of. So keep the null parameter otherwise this will end
    in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    // PDFBOX-4985
    // build the visual appearance as there is none for the widgets
    if ((acroForm != null) && acroForm.getNeedAppearances()) {
        if (acroForm.getFields().isEmpty()) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.process(...) [step in execution path]
        {
            new AcroFormOrphanWidgetsProcessor(document).process();
        }
        // PDFBOX-4985
        // build the visual appearance as there is none for the widgets
        new AcroFormGenerateAppearancesProcessor(document).process();
    }
}

@Override
public void process() {
    /* Get the AcroForm in it's current state.

    Also note: getAcroForm() applies a default fixup which this processor
    is part of. So keep the null parameter otherwise this will end
    in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    if (acroForm != null) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.resolveFieldsFromWidgets(...) [step in execution path]
    {
        resolveFieldsFromWidgets(acroForm);
    }
}

private void resolveFieldsFromWidgets(PDAcroForm acroForm) {
    LOG.debug("rebuilding fields from widgets");
    PDResources resources = acroForm.getDefaultResources();
    if (resources == null) {
        // failsafe. Currently resources is never null because defaultfixup is called first.
        LOG.debug("AcroForm default resources is null");
        return;
    }
    List<PDField> fields = new ArrayList<>();
    Map<String, PDField> nonTerminalFieldsMap = new HashMap<>();
    for (PDPage page : document.getPages()) {
        try {
            handleAnnotations(acroForm, resources, fields, page.getAnnotations(), nonTerminalFieldsMap);
        } catch (IOException ioe) {
            LOG.debug("couldn't read annotations for page " + ioe.getMessage());
        }
    }
    acroForm.setFields(fields);
    for (PDField field : acroForm.getFieldTree()) {
        if (field instanceof PDVariableText) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.ensureFontResources(...) [step in execution path]
        {
            ensureFontResources(resources, ((PDVariableText) (field)));
        }
    }
}

/* Lookup the font used in the default appearance and if this is 
not available try to find a suitable font and use that.
This may not be the original font but a similar font replacement

TODO: implement a font lookup similar as discussed in PDFBOX-2661 so that already existing
font resources might be accepatble.
In such case this must be implemented in PDDefaultAppearanceString too!
 */
private void ensureFontResources(PDResources defaultResources, PDVariableText field) {
    String daString = field.getDefaultAppearance();
    if (daString.startsWith("/") && (daString.length() > 1)) {
        COSName fontName = COSName.getPDFName(daString.substring(1, daString.indexOf(" ")));
        try {
            if (defaultResources.getFont(fontName) == null) {
                if (LOG.isDebugEnabled()) {
                    LOG.debug("trying to add missing font resource for field " + field.getFullyQualifiedName());
                }
                FontMapper mapper = FontMappers.instance();
                FontMapping<TrueTypeFont> fontMapping = mapper.getTrueTypeFont(fontName.getName(), null);
                if (fontMapping != null) {
                    // PATH: Test should invoke the next PDType0Font.load(...) [step in execution path]
                    PDType0Font pdFont = PDType0Font.load(document, fontMapping.getFont(), false);
                    if (LOG.isDebugEnabled()) {
                        LOG.debug((("looked up font for " + fontName.getName()) + " - found ") + fontMapping.getFont().getName());
                    }
                    defaultResources.put(fontName, pdFont);
                } else if (LOG.isDebugEnabled()) {
                    LOG.debug((("no suitable font found for field " + field.getFullyQualifiedName()) + " for font name ") + fontName.getName());
                }
            }
        } catch (IOException ioe) {
            LOG.debug((("unable to handle font resources for field " + field.getFullyQualifiedName()) + ": ") + ioe.getMessage());
        }
    }
}

/**
 * Private. Creates a new PDType0Font font for embedding.
 *
 * @param document
 * @param ttf
 * @param embedSubset
 * @param closeTTF
 * 		whether to close the ttf parameter after embedding. Must be true when the ttf
 * 		parameter was created in the load() method, false when the ttf parameter was passed to the
 * 		load() method.
 * @param vertical
 * 		whether to enable vertical substitutions.
 * @throws IOException
 */
private (PDDocument document, TrueTypeFont ttf, boolean embedSubset, boolean closeTTF, boolean vertical) throws IOException {
    if (vertical) {
        ttf.enableVerticalSubstitutions();
    }
    gsubData = ttf.getGsubData();
    cmapLookup = ttf.getUnicodeCmapLookup();
    embedder = new PDCIDFontType2Embedder(document, dict, ttf, embedSubset, this, vertical);
    // PATH: Test should invoke the next PDCIDFontType2Embedder.getCIDFont(...) [step in execution path]
    descendantFont = embedder.getCIDFont();
    readEncoding();
    fetchCMapUCS2();
    if (closeTTF) {
        if (embedSubset) {
            this.ttf = ttf;
            document.registerTrueTypeFontForClosing(ttf);
        } else {
            // the TTF is fully loaded and it is safe to close the underlying data source
            ttf.close();
        }
    }
}

/**
 * Returns the descendant CIDFont.
 */
public PDCIDFont getCIDFont() throws IOException {
    return new PDCIDFontType2(cidFont, parent, ttf);
}

/**
 * Constructor.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @param parent
 * 		The parent font.
 * @param trueTypeFont
 * 		The true type font used to create the parent font
 * @throws IOException
 * 		if the font could not be read
 */
public PDCIDFontType2(COSDictionary fontDictionary, PDType0Font parent, TrueTypeFont trueTypeFont) throws IOException {
    super(fontDictionary, parent);
    PDFontDescriptor fd = getFontDescriptor();
    if (trueTypeFont != null) {
        ttf = trueTypeFont;
        otf = ((trueTypeFont instanceof OpenTypeFont) && ((OpenTypeFont) (trueTypeFont)).isSupportedOTF()) ? ((OpenTypeFont) (trueTypeFont)) : null;
        isEmbedded = true;
        isDamaged = false;
    } else {
        boolean fontIsDamaged = false;
        TrueTypeFont ttfFont = null;
        PDStream stream = null;
        if (fd != null) {
            stream = fd.getFontFile2();
            if (stream == null) {
                stream = fd.getFontFile3();
            }
            if (stream == null) {
                // Acrobat looks in FontFile too, even though it is not in the spec, see PDFBOX-2599
                stream = fd.getFontFile();
            }
        }
        if (stream != null) {
            try {
                // embedded OTF or TTF
                RandomAccessRead view = stream.getCOSObject().createView();
                TTFParser ttfParser = getParser(view, true);
                ttfFont = ttfParser.parse(view);
                ttfFont.close();
            } catch (IOException e) {
                fontIsDamaged = true;
                LOG.warn("Could not read embedded OTF for font " + getBaseFont(), e);
            }
            if ((ttfFont instanceof OpenTypeFont) && (!((OpenTypeFont) (ttfFont)).isSupportedOTF())) {
                // the OpenType font contains CFF2 outlines which are not supported yet
                ttfFont = null;
                fontIsDamaged = true;
                LOG.warn("Found an OpenType font using CFF2 outlines which are not supported " + fd.getFontName());
            }
        }
        isEmbedded = ttfFont != null;
        isDamaged = fontIsDamaged;
        if (ttfFont == null) {
            ttfFont = findFontOrSubstitute();
        }
        otf = ((ttfFont instanceof OpenTypeFont) && ((OpenTypeFont) (ttfFont)).isSupportedOTF()) ? ((OpenTypeFont) (ttfFont)) : null;
        ttf = ttfFont;
    }
    cmap = ttf.getUnicodeCmapLookup(false);
    cid2gid = readCIDToGIDMap();
}

