protected void processAnnotation(PDAnnotation annotation, PDAppearanceStream appearance) throws IOException {
    PDRectangle bbox = appearance.getBBox();
    PDRectangle rect = annotation.getRectangle();
    // zero-sized rectangles are not valid
    if ((((((rect != null) && (rect.getWidth() > 0)) && (rect.getHeight() > 0)) && (bbox != null)) && (bbox.getWidth() > 0)) && (bbox.getHeight() > 0)) {
        PDResources parent = pushResources(appearance);
        Deque<PDGraphicsState> savedStack = saveGraphicsStack();
        Matrix matrix = appearance.getMatrix();
        // transformed appearance box  fixme: may be an arbitrary shape
        Rectangle2D transformedBox = bbox.transform(matrix).getBounds2D();
        // compute a matrix which scales and translates the transformed appearance box to align
        // with the edges of the annotation's rectangle
        Matrix a = Matrix.getTranslateInstance(rect.getLowerLeftX(), rect.getLowerLeftY());
        a.scale(((float) (rect.getWidth() / transformedBox.getWidth())), ((float) (rect.getHeight() / transformedBox.getHeight())));
        a.translate(((float) (-transformedBox.getX())), ((float) (-transformedBox.getY())));
