/**
 * Draws the page to the requested context.
 *
 * @param g
 * 		The graphics context to draw onto.
 * @param pageSize
 * 		The size of the page to draw.
 * @throws IOException
 * 		If there is an IO error while drawing the page.
 */
public void drawPage(Graphics2D g, PDRectangle pageSize) throws IOException {
    graphics = g;
    xform = graphics.getTransform();
    Matrix m = new Matrix(xform);
    xformScalingFactorX = Math.abs(m.getScalingFactorX());
    xformScalingFactorY = Math.abs(m.getScalingFactorY());
    initialClip = graphics.getClip();
    this.pageSize = pageSize;
    setRenderingHints();
    graphics.translate(0, pageSize.getHeight());
    graphics.scale(1, -1);
    // adjust for non-(0,0) crop box
    graphics.translate(-pageSize.getLowerLeftX(), -pageSize.getLowerLeftY());
    processPage(getPage());
    for (PDAnnotation annotation : getPage().getAnnotations(annotationFilter)) // PATH: Test should invoke the next PageDrawer.showAnnotation(...) [step in execution path]
    {
        showAnnotation(annotation);
    }
    graphics = null;
}

@Override
public void showAnnotation(PDAnnotation annotation) throws IOException {
    lastClips = null;
    if (shouldSkipAnnotation(annotation)) {
        return;
    }
    // TODO support NoZoom, example can be found in p5 of PDFBOX-2348
    PDAppearanceDictionary appearance = annotation.getAppearance();
    if ((appearance == null) || (appearance.getNormalAppearance() == null)) // PATH: Test should invoke the next PDAnnotationSquiggly.constructAppearances(...) [step in execution path]
    {
        annotation.constructAppearances(renderer.document);
    }
    if (annotation.isNoRotate() && (getCurrentPage().getRotation() != 0)) {
        appearance = annotation.getAppearance();
        if (appearance != null) {
            PDAppearanceEntry appearanceEntry = appearance.getNormalAppearance();
            if (((appearanceEntry != null) && appearanceEntry.isStream()) && hasTransparency(appearanceEntry.getAppearanceStream())) {
                // PDFBOX-4744: avoid appearances with transparency groups until we have fixed
                // the rendering. A real solution should probably be
                // in PDFStreamEngine.processAnnotation().
                annotation.constructAppearances();
            }
        }
        PDRectangle rect = annotation.getRectangle();
        AffineTransform savedTransform = graphics.getTransform();
        // "The upper-left corner of the annotation remains at the same point in
        // default user space; the annotation pivots around that point."
        graphics.rotate(Math.toRadians(getCurrentPage().getRotation()), rect.getLowerLeftX(), rect.getUpperRightY());
        super.showAnnotation(annotation);
        graphics.setTransform(savedTransform);
        annotation.setAppearance(appearance);// restore

    } else {
        super.showAnnotation(annotation);
    }
}

@Override
public void constructAppearances(PDDocument document) {
    if (customAppearanceHandler == null) // PATH: Test should invoke the next PDAppearanceHandler.generateAppearanceStreams(...) [step in execution path]
    {
        PDSquigglyAppearanceHandler appearanceHandler = new PDSquigglyAppearanceHandler(this, document);
        appearanceHandler.generateAppearanceStreams();
    } else {
        customAppearanceHandler.generateAppearanceStreams();
    }
}

default void generateAppearanceStreams() // PATH: Test should invoke the next PDFreeTextAppearanceHandler.generateNormalAppearance(...) [step in execution path]
{
    generateNormalAppearance();
    generateRolloverAppearance();
    generateDownAppearance();
}

@Override
public void generateNormalAppearance() {
    PDAnnotationFreeText annotation = ((PDAnnotationFreeText) (getAnnotation()));
    float[] pathsArray;
    if (PDAnnotationFreeText.IT_FREE_TEXT_CALLOUT.equals(annotation.getIntent())) {
        pathsArray = annotation.getCallout();
        if ((pathsArray == null) || ((pathsArray.length != 4) && (pathsArray.length != 6))) {
            pathsArray = new float[0];
        }
    } else {
        pathsArray = new float[0];
    }
    AnnotationBorder ab = AnnotationBorder.getAnnotationBorder(annotation, annotation.getBorderStyle());
    try (PDAppearanceContentStream cs = getNormalAppearanceAsContentStream(true)) {
        // The fill color is the /C entry, there is no /IC entry defined
        boolean hasBackground = cs.setNonStrokingColorOnDemand(annotation.getColor());
        setOpacity(cs, annotation.getConstantOpacity());
        // Adobe uses the last non stroking color from /DA as stroking color!
        // But if there is a color in /DS, then that one is used for text.
        PDColor strokingColor = extractNonStrokingColor(annotation);
        boolean hasStroke = cs.setStrokingColorOnDemand(strokingColor);
        PDColor textColor = strokingColor;
        String defaultStyleString = annotation.getDefaultStyleString();
        if (defaultStyleString != null) {
            Matcher m = COLOR_PATTERN.matcher(defaultStyleString);
            if (m.find()) {
                int color = Integer.parseInt(m.group(1), 16);
                float r = ((color >> 16) & 0xff) / 255.0F;
                float g = ((color >> 8) & 0xff) / 255.0F;
                float b = (color & 0xff) / 255.0F;
                textColor = new PDColor(new float[]{ r, g, b }, PDDeviceRGB.INSTANCE);
            }
        }
        if (ab.dashArray != null) {
            cs.setLineDashPattern(ab.dashArray, 0);
        }
        cs.setLineWidth(ab.width);
        String lineEndingStyle = annotation.getLineEndingStyle();
        // draw callout line(s)
        // must be done before retangle paint to avoid a line cutting through cloud
        // see CTAN-example-Annotations.pdf
        for (int i = 0; i < (pathsArray.length / 2); ++i) {
            float x = pathsArray[i * 2];
            float y = pathsArray[(i * 2) + 1];
            if (i == 0) {
                if (SHORT_STYLES.contains(lineEndingStyle)) {
                    // modify coordinate to shorten the segment
                    // https://stackoverflow.com/questions/7740507/extend-a-line-segment-a-specific-distance
                    float x1 = pathsArray[2];
                    float y1 = pathsArray[3];
                    float len = ((float) (Math.sqrt(Math.pow(x - x1, 2) + Math.pow(y - y1, 2))));
                    if (Float.compare(len, 0) != 0) {
                        x += ((x1 - x) / len) * ab.width;
                        y += ((y1 - y) / len) * ab.width;
                    }
                }
                cs.moveTo(x, y);
            } else {
                cs.lineTo(x, y);
            }
        }
        if (pathsArray.length > 0) {
            cs.stroke();
        }
        // paint the styles here and after line(s) draw, to avoid line crossing a filled shape
        if ((PDAnnotationFreeText.IT_FREE_TEXT_CALLOUT.equals(annotation.getIntent()) && // check only needed to avoid q cm Q if LE_NONE
        (!LE_NONE.equals(lineEndingStyle))) && (pathsArray.length >= 4)) {
            float x2 = pathsArray[2];
            float y2 = pathsArray[3];
            float x1 = pathsArray[0];
            float y1 = pathsArray[1];
            cs.saveGraphicsState();
            if (ANGLED_STYLES.contains(lineEndingStyle)) {
                // do a transform so that first "arm" is imagined flat,
                // like in line handler.
                // The alternative would be to apply the transform to the
                // LE shape coordinates directly, which would be more work
                // and produce code difficult to understand
                double angle = Math.atan2(y2 - y1, x2 - x1);
                cs.transform(Matrix.getRotateInstance(angle, x1, y1));
            } else {
                cs.transform(Matrix.getTranslateInstance(x1, y1));
            }
            drawStyle(lineEndingStyle, cs, 0, 0, ab.width, hasStroke, hasBackground, false);
            cs.restoreGraphicsState();
        }
        PDRectangle borderBox;
        PDBorderEffectDictionary borderEffect = annotation.getBorderEffect();
        if ((borderEffect != null) && borderEffect.getStyle().equals(PDBorderEffectDictionary.STYLE_CLOUDY)) {
            // Adobe draws the text with the original rectangle in mind.
            // but if there is an /RD, then writing area get smaller.
            // do this here because /RD is overwritten in a few lines
            borderBox = applyRectDifferences(getRectangle(), annotation.getRectDifferences());
            // TODO this segment was copied from square handler. Refactor?
            CloudyBorder cloudyBorder = new CloudyBorder(cs, borderEffect.getIntensity(), ab.width, getRectangle());
            cloudyBorder.createCloudyRectangle(annotation.getRectDifference());
            annotation.setRectangle(cloudyBorder.getRectangle());
            annotation.setRectDifference(cloudyBorder.getRectDifference());
            PDAppearanceStream appearanceStream = annotation.getNormalAppearanceStream();
            appearanceStream.setBBox(cloudyBorder.getBBox());
            appearanceStream.setMatrix(cloudyBorder.getMatrix());
        } else {
            // handle the border box
            // 
            // There are two options. The handling is not part of the PDF specification but
            // implementation specific to Adobe Reader
            // - if /RD is set the border box is the /Rect entry inset by the respective
            // border difference.
            // - if /RD is not set then we don't touch /RD etc because Adobe doesn't either.
            borderBox = applyRectDifferences(getRectangle(), annotation.getRectDifferences());
            annotation.getNormalAppearanceStream().setBBox(borderBox);
            // note that borderBox is not modified
            PDRectangle paddedRectangle = getPaddedRectangle(borderBox, ab.width / 2);
            cs.addRect(paddedRectangle.getLowerLeftX(), paddedRectangle.getLowerLeftY(), paddedRectangle.getWidth(), paddedRectangle.getHeight());
        }
        cs.drawShape(ab.width, hasStroke, hasBackground);
        // rotation is an undocumented feature, but Adobe uses it. Examples can be found
        // in pdf_commenting_new.pdf file, page 3.
        int rotation = annotation.getCOSObject().getInt(COSName.ROTATE, 0);
        cs.transform(Matrix.getRotateInstance(Math.toRadians(rotation), 0, 0));
        float xOffset;
        float yOffset;
        float width = ((rotation == 90) || (rotation == 270)) ? borderBox.getHeight() : borderBox.getWidth();
        // strategy to write formatted text is somewhat inspired by
        // AppearanceGeneratorHelper.insertGeneratedAppearance()
        PDFont font = null;
        float clipY;
        float clipWidth = width - (ab.width * 4);
        float clipHeight = ((rotation == 90) || (rotation == 270)) ? borderBox.getWidth() - (ab.width * 4) : borderBox.getHeight() - (ab.width * 4);
        extractFontDetails(annotation);
        if (document != null) {
            PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm();
            if (acroForm != null) {
                // Try to get font from AcroForm default resources
                // Sample file: https://gitlab.freedesktop.org/poppler/poppler/issues/6
                PDResources defaultResources = acroForm.getDefaultResources();
                if (defaultResources != null) {
                    // PATH: Test should invoke the next PDResources.getFont(...) [step in execution path]
                    PDFont defaultResourcesFont = defaultResources.getFont(fontName);
                    if (defaultResourcesFont != null) {
                        font = defaultResourcesFont;
                    }
                }
            }
        }
        if (font == null) {
            font = getDefaultFont();
        }
        // value used by Adobe, no idea where it comes from, actual font bbox max y is 0.931
        // gathered by creating an annotation with width 0.
        float yDelta = 0.7896F;
        switch (rotation) {
            case 180 :
                xOffset = (-borderBox.getUpperRightX()) + (ab.width * 2);
                yOffset = ((-borderBox.getLowerLeftY()) - (ab.width * 2)) - (yDelta * fontSize);
                clipY = (-borderBox.getUpperRightY()) + (ab.width * 2);
                break;
            case 90 :
                xOffset = borderBox.getLowerLeftY() + (ab.width * 2);
                yOffset = ((-borderBox.getLowerLeftX()) - (ab.width * 2)) - (yDelta * fontSize);
                clipY = (-borderBox.getUpperRightX()) + (ab.width * 2);
                break;
            case 270 :
                xOffset = (-borderBox.getUpperRightY()) + (ab.width * 2);
                yOffset = (borderBox.getUpperRightX() - (ab.width * 2)) - (yDelta * fontSize);
                clipY = borderBox.getLowerLeftX() + (ab.width * 2);
                break;
            case 0 :
            default :
                xOffset = borderBox.getLowerLeftX() + (ab.width * 2);
                yOffset = (borderBox.getUpperRightY() - (ab.width * 2)) - (yDelta * fontSize);
                clipY = borderBox.getLowerLeftY() + (ab.width * 2);
                break;
        }
        // clip writing area
        cs.addRect(xOffset, clipY, clipWidth, clipHeight);
        cs.clip();
        String annotationContents = annotation.getContents();
        if (annotationContents != null) {
            cs.beginText();
            cs.setFont(font, fontSize);
            cs.setNonStrokingColor(textColor.getComponents());
            AppearanceStyle appearanceStyle = new AppearanceStyle();
            appearanceStyle.setFont(font);
            appearanceStyle.setFontSize(fontSize);
            PlainTextFormatter formatter = // Adobe ignores the /Q
            // .textAlign(annotation.getQ())
            new PlainTextFormatter.Builder(cs).style(appearanceStyle).text(new PlainText(annotationContents)).width(width - (ab.width * 4)).wrapLines(true).initialOffset(xOffset, yOffset).build();
            try {
                formatter.format();
            } catch (IllegalArgumentException ex) {
                throw new IOException(ex);
            } finally {
                cs.endText();
            }
        }
        if (pathsArray.length > 0) {
            PDRectangle rect = getRectangle();
            // Adjust rectangle
            // important to do this after the rectangle has been painted, because the
            // final rectangle will be bigger due to callout
            // CTAN-example-Annotations.pdf p1
            // TODO in a class structure this should be overridable
            float minX = Float.MAX_VALUE;
            float minY = Float.MAX_VALUE;
            float maxX = Float.MIN_VALUE;
            float maxY = Float.MIN_VALUE;
            for (int i = 0; i < (pathsArray.length / 2); ++i) {
                float x = pathsArray[i * 2];
                float y = pathsArray[(i * 2) + 1];
                minX = Math.min(minX, x);
                minY = Math.min(minY, y);
                maxX = Math.max(maxX, x);
                maxY = Math.max(maxY, y);
            }
            // arrow length is 9 * width at about 30° => 10 * width seems to be enough
            rect.setLowerLeftX(Math.min(minX - (ab.width * 10), rect.getLowerLeftX()));
            rect.setLowerLeftY(Math.min(minY - (ab.width * 10), rect.getLowerLeftY()));
            rect.setUpperRightX(Math.max(maxX + (ab.width * 10), rect.getUpperRightX()));
            rect.setUpperRightY(Math.max(maxY + (ab.width * 10), rect.getUpperRightY()));
            annotation.setRectangle(rect);
            // need to set the BBox too, because rectangle modification came later
            annotation.getNormalAppearanceStream().setBBox(getRectangle());
            // TODO when callout is used, /RD should be so that the result is the writable part
        }
    } catch (IOException ex) {
        LOG.error(ex);
    }
}

/**
 * Returns the font resource with the given name, or null if none exists.
 *
 * @param name
 * 		Name of the font resource.
 * @return the font with the given name or null
 * @throws IOException
 * 		if something went wrong.
 */
public PDFont getFont(COSName name) throws IOException {
    COSObject indirect = getIndirect(COSName.FONT, name);
    if ((cache != null) && (indirect != null)) {
        PDFont cached = cache.getFont(indirect);
        if (cached != null) {
            return cached;
        }
    } else if (indirect == null) {
        SoftReference<PDFont> ref = directFontCache.get(name);
        if (ref != null) {
            PDFont cached = ref.get();
            if (cached != null) {
                return cached;
            }
        }
    }
    PDFont font = null;
    COSBase base = get(COSName.FONT, name);
    if (base instanceof COSDictionary) {
        // PATH: Test should invoke the next PDFontFactory.createFont(...) [step in execution path]
        font = PDFontFactory.createFont(((COSDictionary) (base)), cache);
    }
    if ((cache != null) && (indirect != null)) {
        cache.put(indirect, font);
    } else if (indirect == null) {
        directFontCache.put(name, new SoftReference<>(font));
    }
    return font;
}

/**
 * Creates a new PDFont instance with the appropriate subclass.
 *
 * @param dictionary
 * 		a font dictionary
 * @param resourceCache
 * 		resource cache, only useful for type 3 fonts, can be null
 * @return a PDFont instance, based on the SubType entry of the dictionary
 * @throws IOException
 * 		if something goes wrong
 */
public static PDFont createFont(COSDictionary dictionary, ResourceCache resourceCache) throws IOException {
    COSName type = dictionary.getCOSName(COSName.TYPE, COSName.FONT);
    if (!COSName.FONT.equals(type)) {
        LOG.error(("Expected 'Font' dictionary but found '" + type.getName()) + "'");
    }
    COSName subType = dictionary.getCOSName(COSName.SUBTYPE);
    if (COSName.TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDType1Font(dictionary);
    } else if (COSName.MM_TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDMMType1Font(dictionary);
    } else if (COSName.TRUE_TYPE.equals(subType)) {
        return new PDTrueTypeFont(dictionary);
    } else if (COSName.TYPE3.equals(subType)) {
        return new PDType3Font(dictionary, resourceCache);
    } else if (COSName.TYPE0.equals(subType)) {
        COSDictionary fontDescriptor = getFontDescriptor(dictionary);
        FontType fontTypeFromFont = getFontTypeFromFont(fontDescriptor, subType);
        if (fontTypeFromFont != null) {
            COSDictionary descendantFont = getDescendantFont(dictionary);
            COSName descFontType = (descendantFont != null) ? descendantFont.getCOSName(COSName.SUBTYPE) : null;
            if ((descFontType != null) && (!fontTypeFromFont.isCIDSubtype(descFontType))) {
                fixType0Subtype(descendantFont, fontDescriptor, fontTypeFromFont.getSubtype());
            }
        }
        return new PDType0Font(dictionary);
    } else if (COSName.CID_FONT_TYPE0.equals(subType)) {
        throw new IOException("Type 0 descendant font not allowed");
    } else if (COSName.CID_FONT_TYPE2.equals(subType)) {
        throw new IOException("Type 2 descendant font not allowed");
    } else {
        // assuming Type 1 font (see PDFBOX-1988) because it seems that Adobe Reader does this
        // however, we may need more sophisticated logic perhaps looking at the FontFile
        LOG.warn(("Invalid font subtype '" + subType) + "'");
        return new PDType1Font(dictionary);
    }
}

/**
 * Constructor.
 *
 * @param fontDictionary
 * 		the corresponding dictionary
 * @throws IOException
 * 		it something went wrong
 */
public (COSDictionary fontDictionary) throws IOException {
    this(fontDictionary);
    boolean fontIsDamaged = false;
    CFFType1Font cffEmbedded = null;
    PDFontDescriptor fd = getFontDescriptor();
    if (fd != null) {
        PDStream ff3Stream = fd.getFontFile3();
        if (ff3Stream != null) {
            try (RandomAccessRead randomAccessRead = ff3Stream.getCOSObject().createView()) {
                if (randomAccessRead.length() == 0) {
                    LOG.error("Invalid data for embedded Type1C font " + getName());
                } else {
                    // note: this could be an OpenType file, fortunately CFFParser can handle that
                    CFFParser cffParser = new CFFParser();
                    CFFFont parsedCffFont = cffParser.parse(randomAccessRead).get(0);
                    if (parsedCffFont instanceof CFFType1Font) {
                        cffEmbedded = ((CFFType1Font) (parsedCffFont));
                    } else {
                        LOG.error("Expected CFFType1Font, got " + parsedCffFont.getClass().getSimpleName());
                        fontIsDamaged = true;
                    }
                }
            } catch (IOException e) {
                LOG.error("Can't read the embedded Type1C font " + getName(), e);
                fontIsDamaged = true;
            }
        }
    }
    isDamaged = fontIsDamaged;
    cffFont = cffEmbedded;
    if (cffFont != null) {
        genericFont = cffFont;
        isEmbedded = true;
    } else {
        String baseFont = getBaseFont();
        // PATH: Test should invoke the next FontMapperImpl.getFontBoxFont(...) [step in execution path]
        FontMapping<FontBoxFont> mapping = FontMappers.instance().getFontBoxFont(baseFont, fd);
        genericFont = mapping.getFont();
        if (mapping.isFallback()) {
            LOG.warn((("Using fallback font " + genericFont.getName()) + " for ") + baseFont);
        }
        isEmbedded = false;
    }
    readEncoding();
    fontMatrixTransform = getFontMatrix().createAffineTransform();
    fontMatrixTransform.scale(1000, 1000);
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null. This allows
 * any font to be substituted with a PFB, TTF or OTF.
 *
 * @param fontDescriptor
 * 		the FontDescriptor of the font to find
 */
@Override
public FontMapping<FontBoxFont> getFontBoxFont(String baseFont, PDFontDescriptor fontDescriptor) {
    // PATH: Test should invoke the next FontMapperImpl.findFontBoxFont(...) [step in execution path]
    FontBoxFont font = findFontBoxFont(baseFont);
    if (font != null) {
        return new FontMapping<>(font, false);
    } else {
        // fallback - todo: i.e. fuzzy match
        String fallbackName = getFallbackFontName(fontDescriptor);
        font = findFontBoxFont(fallbackName);
        if (font == null) {
            // we have to return something here as TTFs aren't strictly required on the system
            font = lastResortFont;
        }
        return new FontMapping<>(font, true);
    }
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param postScriptName
 * 		PostScript font name
 */
private FontBoxFont findFontBoxFont(String postScriptName) {
    // PATH: Test should invoke the next FontMapperImpl.findFont(...) [step in execution path]
    Type1Font t1 = ((Type1Font) (findFont(FontFormat.PFB, postScriptName)));
    if (t1 != null) {
        return t1;
    }
    TrueTypeFont ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, postScriptName)));
    if (ttf != null) {
        return ttf;
    }
    OpenTypeFont otf = ((OpenTypeFont) (findFont(FontFormat.OTF, postScriptName)));
    if (otf != null) {
        return otf;
    }
    return null;
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param postScriptName
 * 		PostScript font name
 */
private FontBoxFont findFont(FontFormat format, String postScriptName) {
    // handle damaged PDFs, see PDFBOX-2884
    if (postScriptName == null) {
        return null;
    }
    // make sure the font provider is initialized
    if (fontProvider == null) // PATH: Test should invoke the next FontMapperImpl.getProvider(...) [step in execution path]
    {
        getProvider();
    }
    // first try to match the PostScript name
    FontInfo info = getFont(format, postScriptName);
    if (info != null) {
        return info.getFont();
    }
    // remove hyphens (e.g. Arial-Black -> ArialBlack)
    info = getFont(format, postScriptName.replace("-", ""));
    if (info != null) {
        return info.getFont();
    }
    // then try named substitutes
    for (String substituteName : getSubstitutes(postScriptName)) {
        info = getFont(format, substituteName);
        if (info != null) {
            return info.getFont();
        }
    }
    // then try converting Windows names e.g. (ArialNarrow,Bold) -> (ArialNarrow-Bold)
    info = getFont(format, postScriptName.replace(",", "-"));
    if (info != null) {
        return info.getFont();
    }
    if (postScriptName.contains(",")) {
        postScriptName = postScriptName.substring(0, postScriptName.indexOf(","));
        // PDFBOX-5806: try cutting font style and getting the basefont
        // eg. for "Wingdings,Bolt" to "Wingding-Regular" (including the following step)
        info = getFont(format, postScriptName);
        if (info != null) {
            return info.getFont();
        }
    }
    // try appending "-Regular", works for Wingdings on windows
    info = getFont(format, postScriptName + "-Regular");
    if (info != null) {
        return info.getFont();
    }
    // no matches
    return null;
}

/**
 * Returns the font service provider. Defaults to using FileSystemFontProvider.
 */
public synchronized FontProvider getProvider() {
    if (fontProvider == null) {
        setProvider(DefaultFontProvider.INSTANCE);
    }
    return fontProvider;
}

org.apache.pdfbox.pdmodel.font.FontMapperImpl$DefaultFontProvider

// Static field initializations
private static final FontProvider INSTANCE = new FileSystemFontProvider(fontCache);

/**
 * Constructor.
 */
(FontCache cache) {
    this.cache = cache;
    try {
        if (LOG.isTraceEnabled()) {
            LOG.trace("Will search the local system for fonts");
        }
        // scan the local system for font files
        FontFileFinder fontFileFinder = new FontFileFinder();
        List<URI> fonts = fontFileFinder.find();
        List<File> files = new ArrayList<>(fonts.size());
        for (URI font : fonts) {
            files.add(new File(font));
        }
        if (LOG.isTraceEnabled()) {
            LOG.trace(("Found " + files.size()) + " fonts on the local system");
        }
        if (!files.isEmpty()) {
            // load cached FontInfo objects
            List<FSFontInfo> cachedInfos = loadDiskCache(files);
            if ((cachedInfos != null) && (!cachedInfos.isEmpty())) {
                fontInfoList.addAll(cachedInfos);
            } else // PATH: Test should invoke the next FileSystemFontProvider.scanFonts(...) [step in execution path]
            {
                LOG.info("Building on-disk font cache, this may take a while");
                scanFonts(files);
                saveDiskCache();
                LOG.info(("Finished building on-disk font cache, found " + fontInfoList.size()) + " fonts");
            }
        }
    } catch (AccessControlException e) {
        LOG.error("Error accessing the file system", e);
    }
}

private void scanFonts(List<File> files) {
    // to force a specific font for debug, add code like this here:
    // files = Collections.singletonList(new File("font filename"))
    for (File file : files) {
        String filePath = file.getPath().toLowerCase();
        if (filePath.endsWith(".ttf") || filePath.endsWith(".otf")) // PATH: Test should invoke the next FileSystemFontProvider.addTrueTypeFont(...) [step in execution path]
        {
            addTrueTypeFont(file);
        } else if (filePath.endsWith(".ttc") || filePath.endsWith(".otc")) {
            addTrueTypeCollection(file);
        } else if (filePath.endsWith(".pfb")) {
            addType1Font(file);
        }
    }
}

/**
 * Adds an OTF or TTF font to the file cache. To reduce memory, the parsed font is not cached.
 */
private void addTrueTypeFont(File ttfFile) {
    FontFormat fontFormat = null;
    try // PATH: Test should invoke the next FileSystemFontProvider.addTrueTypeFontImpl(...) [step in execution path]
    {
        TTFParser parser;
        if (ttfFile.getPath().toLowerCase().endsWith(".otf")) {
            fontFormat = FontFormat.OTF;
            parser = new OTFParser(false);
        } else {
            fontFormat = FontFormat.TTF;
            parser = new TTFParser(false);
        }
        FontHeaders headers = parser.parseTableHeaders(new RandomAccessReadBufferedFile(ttfFile));
        addTrueTypeFontImpl(headers, ttfFile, SKIP_CHECKSUMS ? CHECKSUM_PLACEHOLDER : computeHash(Files.newInputStream(ttfFile.toPath())));
    } catch (IOException e) {
        LOG.warn("Could not load font file: " + ttfFile, e);
        fontInfoList.add(createFSIgnored(ttfFile, fontFormat, "*skipexception*"));
    }
}

/**
 * Adds an OTF or TTF font to the file cache. To reduce memory, the parsed font is not cached.
 */
private void addTrueTypeFontImpl(FontHeaders fontHeaders, File file, String hash) {
    final String error = fontHeaders.getError();
    if (error == null) {
        // read PostScript name, if any
        final String name = fontHeaders.getName();
        if ((name != null) && name.contains("|")) {
            fontInfoList.add(createFSIgnored(file, FontFormat.TTF, "*skippipeinname*"));
            LOG.warn((("Skipping font with '|' in name " + name) + " in file ") + file);
        } else if (name != null) {
            // ignore bitmap fonts
            Integer macStyle = fontHeaders.getHeaderMacStyle();
            if (macStyle == null) {
                fontInfoList.add(createFSIgnored(file, FontFormat.TTF, name));
                return;
            }
            int sFamilyClass = -1;
            int usWeightClass = -1;
            int ulCodePageRange1 = 0;
            int ulCodePageRange2 = 0;
            byte[] panose = null;
            OS2WindowsMetricsTable os2WindowsMetricsTable = fontHeaders.getOS2Windows();
            // Apple's AAT fonts don't have an OS/2 table
            if (os2WindowsMetricsTable != null) {
                sFamilyClass = os2WindowsMetricsTable.getFamilyClass();
                usWeightClass = os2WindowsMetricsTable.getWeightClass();
                ulCodePageRange1 = ((int) (os2WindowsMetricsTable.getCodePageRange1()));
                ulCodePageRange2 = ((int) (os2WindowsMetricsTable.getCodePageRange2()));
                panose = os2WindowsMetricsTable.getPanose();
            }
            FontFormat format;
            CIDSystemInfo ros = null;
            if (fontHeaders.isOpenTypePostScript()) {
                format = FontFormat.OTF;
                String registry = fontHeaders.getOtfRegistry();
                String ordering = fontHeaders.getOtfOrdering();
                if ((registry != null) || (ordering != null)) {
                    ros = new CIDSystemInfo(registry, ordering, fontHeaders.getOtfSupplement());
                }
            } else {
                byte[] bytes = fontHeaders.getNonOtfTableGCID142();
                if (bytes != null) {
                    // Apple's AAT fonts have a "gcid" table with CID info
                    String reg = new String(bytes, 10, 64, StandardCharsets.US_ASCII);
                    String registryName = reg.substring(0, reg.indexOf('\u0000'));
                    String ord = new String(bytes, 76, 64, StandardCharsets.US_ASCII);
                    String orderName = ord.substring(0, ord.indexOf('\u0000'));
                    int supplementVersion = (bytes[140] << 8) & (bytes[141] & 0xff);
                    ros = new CIDSystemInfo(registryName, orderName, supplementVersion);
                }
                format = FontFormat.TTF;
            }
            fontInfoList.add(new FSFontInfo(file, format, name, ros, usWeightClass, sFamilyClass, ulCodePageRange1, ulCodePageRange2, macStyle, panose, this, hash, file.lastModified()));
            if (LOG.isTraceEnabled()) // PATH: Test should invoke the next Log.trace(...) [step in execution path]
            {
                LOG.trace(((((((format.name() + ": '") + name) + "' / '") + fontHeaders.getFontFamily()) + "' / '") + fontHeaders.getFontSubFamily()) + "'");
            }
        } else {
            fontInfoList.add(createFSIgnored(file, FontFormat.TTF, "*skipnoname*"));
            LOG.warn("Missing 'name' entry for PostScript name in font " + file);
        }
    } else {
        fontInfoList.add(createFSIgnored(file, FontFormat.TTF, "*skipexception*"));
        LOG.warn((("Could not load font file '" + file) + "': ") + error);
    }
}

