            getGraphicsState().intersectClippingPath(adjustClip(linePath));
        }
        // PDFBOX-3836: lastClip needs to be reset, because after intersection it is still the same
        // object, thus setClip() would believe that it is cached.
        lastClips = null;
        clipWindingRule = -1;
    }
